INSERT INTO metadata.cim_ref_classes (name, parent_name, namespace, is_abstract, description, source) VALUES
  ('ACDCConverter', 'ConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'A unit with valves for three phases, together with unit control equipment, essential protective and switching devices, DC storage capacitors, phase reactors and auxiliaries, if any, used for conversion.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCConverterDCTerminal', 'DCBaseTerminal', 'http://www.iec.ch/TC57/CIM#', false, 'A DC electrical connection point at the AC/DC converter. The AC/DC converter is electrically connected also to the AC side. The AC connection is inherited from the AC conducting equipment in the same way as any other AC equipment. The AC/DC converter DC terminal is separate from generic DC terminal to restrict the connection with the AC side to AC/DC converter and so that no other DC conducting equipment can be connected to the AC side.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCTerminal', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'An electrical connection point (AC or DC) to a piece of conducting equipment. Terminals are connected at physical connection points called connectivity nodes.', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegment', 'Conductor', 'http://www.iec.ch/TC57/CIM#', false, 'A wire or combination of wires, with consistent electrical characteristics, building a single electrical system, used to carry alternating current between points in the power system. For symmetrical, transposed 3ph lines, it is sufficient to use attributes of the line segment, which describe impedances and admittances for the entire length of the segment. Additionally impedances can be computed by using length and associated per length impedances. The BaseVoltage at the two ends of ACLineSegments in a Line shall have the same BaseVoltage.nominalVoltage. However, boundary lines may have slightly different BaseVoltage.nominalVoltages and variation is allowed. Larger voltage difference in general requires use of an equivalent branch.', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegmentPhase', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'Represents a single wire of an alternating current line segment.', 'schema/cim/IEC_CIM.ttl'),
  ('ADSInstructionTypeCommitment', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ADSInstructionTypeOOS', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ASRequirements', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Models Ancillary Service Requirements. Describes interval for which the requirement is applicable.', 'schema/cim/IEC_CIM.ttl'),
  ('AcceptanceTest', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Acceptance test for assets.', 'schema/cim/IEC_CIM.ttl'),
  ('AccessPermit', 'WorkDocument', 'http://www.iec.ch/TC57/CIM#', false, 'A permit is sometimes needed to provide legal access to land or equipment. For example, local authority permission for road works.', 'schema/cim/IEC_CIM.ttl'),
  ('AccountMovement', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Credit/debit movements for an account.', 'schema/cim/IEC_CIM.ttl'),
  ('AccountingUnit', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Unit for accounting; use either ''energyUnit'' or ''currencyUnit'' to specify the unit for ''value''.', 'schema/cim/IEC_CIM.ttl'),
  ('AccumulationKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Accumulator', 'Measure', 'http://www.iec.ch/TC57/CIM#', false, 'Accumulator represents an accumulated (counted) Measurement, e.g. an energy value.', 'schema/cim/IEC_CIM.ttl'),
  ('AccumulatorLimit', 'Limit', 'http://www.iec.ch/TC57/CIM#', false, 'Limit values for Accumulator measurements.', 'schema/cim/IEC_CIM.ttl'),
  ('AccumulatorLimitSet', 'LimitSet', 'http://www.iec.ch/TC57/CIM#', false, 'An AccumulatorLimitSet specifies a set of Limits that are associated with an Accumulator measurement.', 'schema/cim/IEC_CIM.ttl'),
  ('AccumulatorReset', 'Control', 'http://www.iec.ch/TC57/CIM#', false, 'This command reset the counter value to zero.', 'schema/cim/IEC_CIM.ttl'),
  ('AccumulatorValue', 'MeasurementValue', 'http://www.iec.ch/TC57/CIM#', false, 'AccumulatorValue represents an accumulated (counted) MeasurementValue.', 'schema/cim/IEC_CIM.ttl'),
  ('AceTariffType', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'The Area Control Error tariff type that is applied or used.', 'schema/cim/IEC_CIM.ttl'),
  ('ActionRequest', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Action request against an existing Trade.', 'schema/cim/IEC_CIM.ttl'),
  ('ActionType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ActivePower', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Product of RMS value of the voltage and the RMS value of the in-phase component of the current.', 'schema/cim/IEC_CIM.ttl'),
  ('ActivePowerChangeRate', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Rate of change of active power per time.', 'schema/cim/IEC_CIM.ttl'),
  ('ActivePowerLimit', 'OperationalLimit', 'http://www.iec.ch/TC57/CIM#', false, 'Limit on active power flow.', 'schema/cim/IEC_CIM.ttl'),
  ('ActivePowerPerCurrentFlow', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ActivePowerPerFrequency', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Active power variation with frequency.', 'schema/cim/IEC_CIM.ttl'),
  ('ActivityRecord', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Records activity for an entity at a point in time; activity may be for an event that has already occurred or for a planned activity.', 'schema/cim/IEC_CIM.ttl'),
  ('AdderType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('AdjacentCASet', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Goups Adjacent Control Areas', 'schema/cim/IEC_CIM.ttl'),
  ('Admittance', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Ratio of current to voltage.', 'schema/cim/IEC_CIM.ttl'),
  ('AggregateKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('AggregateNode', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'An aggregated node can define a typed grouping further defined by the AnodeType enumeratuion. Types range from System Zone/Regions to Market Energy Regions to Aggregated Loads and Aggregated Generators.', 'schema/cim/IEC_CIM.ttl'),
  ('AggregatedPnode', 'Pnode', 'http://www.iec.ch/TC57/CIM#', false, 'An aggregated pricing node is a specialized type of pricing node used to model items such as System Zone, Default Price Zone, Custom Price Zone, Control Area, Aggregated Generation, Aggregated Particpating Load, Aggregated Non-Participating Load, Trading Hub, Designated Control Area(DCA) Zone', 'schema/cim/IEC_CIM.ttl'),
  ('Agreement', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Formal agreement between two parties defining the terms and conditions for a set of services. The specifics of the services are, in turn, defined via one or more service agreements.', 'schema/cim/IEC_CIM.ttl'),
  ('AirCompressor', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'Combustion turbine air compressor which is an integral part of a compressed air energy storage (CAES) plant.', 'schema/cim/IEC_CIM.ttl'),
  ('AlarmDisplayType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('AllocationEnergyTypeCode', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('AllocationResult', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Models Market clearing results. Indicates market horizon, interval based. Used by a market quality system for billing and settlement purposes', 'schema/cim/IEC_CIM.ttl'),
  ('AllocationResultValues', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Models Market clearing results in terms of price and MW values', 'schema/cim/IEC_CIM.ttl'),
  ('AltGeneratingUnitMeas', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'A prioritized measurement to be used for the generating unit in the control area specificaiton.', 'schema/cim/IEC_CIM.ttl'),
  ('AltTieMeas', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'A prioritized measurement to be used for the tie flow as part of the control area specification.', 'schema/cim/IEC_CIM.ttl'),
  ('AlternateModel', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
