  ('Analog', 'Measure', 'http://www.iec.ch/TC57/CIM#', false, 'Analog represents an analog Measurement.', 'schema/cim/IEC_CIM.ttl'),
  ('AnalogControl', 'Control', 'http://www.iec.ch/TC57/CIM#', false, 'An analog control used for supervisory control.', 'schema/cim/IEC_CIM.ttl'),
  ('AnalogLimit', 'Limit', 'http://www.iec.ch/TC57/CIM#', false, 'Limit values for Analog measurements.', 'schema/cim/IEC_CIM.ttl'),
  ('AnalogLimitSet', 'LimitSet', 'http://www.iec.ch/TC57/CIM#', false, 'An AnalogLimitSet specifies a set of Limits that are associated with an Analog measurement.', 'schema/cim/IEC_CIM.ttl'),
  ('AnalogLimitType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('AnalogMeasurementValueQuality', 'MeasurementValueQuality', 'http://www.iec.ch/TC57/CIM#', false, 'Measurement quality flags for Analog Values.', 'schema/cim/IEC_CIM.ttl'),
  ('AnalogToDigitalLogicKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('AnalogValue', 'MeasurementValue', 'http://www.iec.ch/TC57/CIM#', false, 'AnalogValue represents an analog MeasurementValue.', 'schema/cim/IEC_CIM.ttl'),
  ('AnchorKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('AncillaryCommodityType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('AncillaryServiceClearing', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Model of results of market clearing with respect to Ancillary Service products', 'schema/cim/IEC_CIM.ttl'),
  ('AngleDegrees', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Measurement of angle in degrees.', 'schema/cim/IEC_CIM.ttl'),
  ('AngleRadians', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Phase angle in radians.', 'schema/cim/IEC_CIM.ttl'),
  ('AnodeType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ApnodeType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ApparentPower', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Product of the RMS value of the voltage and the RMS value of the current.', 'schema/cim/IEC_CIM.ttl'),
  ('ApparentPowerLimit', 'OperationalLimit', 'http://www.iec.ch/TC57/CIM#', false, 'Apparent power limit.', 'schema/cim/IEC_CIM.ttl'),
  ('Appointment', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Meeting time and location.', 'schema/cim/IEC_CIM.ttl'),
  ('Approver', 'DocumentPersonRole', 'http://www.iec.ch/TC57/CIM#', false, 'Person who accepted/signed or rejected the document.', 'schema/cim/IEC_CIM.ttl'),
  ('Area', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Area.', 'schema/cim/IEC_CIM.ttl'),
  ('AreaControlMode', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('AreaLoadBid', 'Bid', 'http://www.iec.ch/TC57/CIM#', false, 'AreaLoadBid is not submitted by a market participant into the Markets. Instead, it is simply an aggregation of all LoadBids contained wtihin a specific SubControlArea. This entity should inherit from Bid for representation of the timeframe (startTime, stopTime) and the market type.', 'schema/cim/IEC_CIM.ttl'),
  ('AreaLoadCurve', 'RegularIntervalSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'Area load curve definition.', 'schema/cim/IEC_CIM.ttl'),
  ('AreaReserveSpec', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'The control area''s reserve specification.', 'schema/cim/IEC_CIM.ttl'),
  ('AssemblyDescription', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A description for how to assemble model parts for a specific purpose.', 'schema/cim/IEC_CIM.ttl'),
  ('AssemblyManifest', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A collection of model parts when combined form a case or part of a case.', 'schema/cim/IEC_CIM.ttl'),
  ('Asset', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Tangible resource of the utility, including power system equipment, various end devices, cabinets, buildings, etc. For electrical network equipment, the role of the asset is defined through PowerSystemResource and its subclasses, defined mainly in the Wires model (refer to IEC61970-301 and model package IEC61970::Wires). Asset description places emphasis on the physical characteristics of the equipment fulfilling that role.', 'schema/cim/IEC_CIM.ttl'),
  ('AssetContainer', 'Asset', 'http://www.iec.ch/TC57/CIM#', false, 'Asset that is aggregation of other assets such as conductors, transformers, switchgear, land, fences, buildings, equipment, vehicles, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('AssetContainersAndWorkRelated', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('AssetFunction', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Function performed by an asset.', 'schema/cim/IEC_CIM.ttl'),
  ('AssetInfo', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Set of attributes of an asset, representing typical datasheet information of a physical device that can be instantiated and shared in different data exchange contexts: - as attributes of an asset instance (installed or in stock) - as attributes of an asset model (product by a manufacturer) - as attributes of a type asset (generic type of an asset as used in designs/extension planning).', 'schema/cim/IEC_CIM.ttl'),
  ('AssetLocationHazard', 'Hazard', 'http://www.iec.ch/TC57/CIM#', false, 'Potential hazard related to the location of an asset. Examples are trees growing under overhead power lines, a park being located by a substation (i.e., children climb fence to recover a ball), a lake near an overhead distribution line (fishing pole/line contacting power lines), dangerous neighbour, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('AssetModel', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Model of an asset, either a product of a specific manufacturer or a generic asset model or material item. Datasheet characteristics are available through the associated AssetInfo subclass and can be shared with asset or power system resource instances.', 'schema/cim/IEC_CIM.ttl'),
  ('AssetModelCatalogue', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Catalogue of available types of products and materials that are used to build or install, maintain or operate an Asset. Each catalogue item is for a specific product (AssetModel) available from a specific supplier.', 'schema/cim/IEC_CIM.ttl'),
  ('AssetModelCatalogueItem', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Provides pricing and other relevant information about a specific manufacturer''s product (i.e., AssetModel), and its price from a given supplier. A single AssetModel may be availble from multiple suppliers. Note that manufacturer and supplier are both types of organisation, which the association is inherited from Document.', 'schema/cim/IEC_CIM.ttl'),
  ('AssetModelUsageKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('AssetOrganisationRole', 'OrganisationRole', 'http://www.iec.ch/TC57/CIM#', false, 'Role an organisation plays with respect to asset.', 'schema/cim/IEC_CIM.ttl'),
  ('AssetOwner', 'AssetOrganisationRole', 'http://www.iec.ch/TC57/CIM#', false, 'Owner of the asset.', 'schema/cim/IEC_CIM.ttl'),
  ('AssetPropertyCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'An Asset Property that is described through curves rather than as a data point. The relationship is to be defined between an independent variable (X-axis) and one or two dependent variables (Y1-axis and Y2-axis).', 'schema/cim/IEC_CIM.ttl'),
  ('AssetRelationships', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('AssetUser', 'AssetOrganisationRole', 'http://www.iec.ch/TC57/CIM#', false, 'Organisation that is a user of the asset.', 'schema/cim/IEC_CIM.ttl'),
  ('Assignment', 'WorkDocument', 'http://www.iec.ch/TC57/CIM#', false, 'An assignment is given to an ErpPerson, Crew, Organisation, Equipment Item, Tool, etc. and may be used to perform Work, WorkTasks, Procedures, etc. TimeSchedules may be set up directly for Assignments or indirectly via the associated WorkTask. Note that these associations are all inherited through the recursive relationship on Document.', 'schema/cim/IEC_CIM.ttl'),
  ('AsynchronousMachine', 'RotatingMachine', 'http://www.iec.ch/TC57/CIM#', false, 'A rotating machine whose shaft rotates asynchronously with the electrical field. Also known as an induction machine with no external connection to the rotor windings, e.g squirrel-cage induction machine.', 'schema/cim/IEC_CIM.ttl'),
  ('AsynchronousMachineDynamics', 'RotatingMachineDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Asynchronous machine whose behaviour is described by reference to a standard model expressed in either time constant reactance form or equivalent circuit form <font color="#0f0f0f">or by definition of a user-defined model.</font> <b>Parameter Notes:</b> <ol> <li>Asynchronous machine parameters such as <b>Xl, Xs</b> etc. are actually used as inductances (L) in the model, but are commonly referred to as reactances since, at nominal frequency, the per unit values are the same. However, some references use the symbol L instead of X. </li> </ol>', 'schema/cim/IEC_CIM.ttl'),
  ('AsynchronousMachineEquivalentCircuit', 'AsynchronousMachineDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The electrical equations of all variations of the asynchronous model are based on the AsynchronousEquivalentCircuit diagram for the direct and quadrature axes, with two equivalent rotor windings in each axis. <b>Equations for conversion between Equivalent Circuit and Time Constant Reactance forms:</b> <b>Xs</b> = <b>Xm</b> + <b>Xl</b> <b>X''</b> = <b>Xl</b> + <b>Xm</b> * <b>Xlr1</b> / (<b>Xm</b> + <b>Xlr1</b>) <b>X''''</b> = <b>Xl</b> + <b>Xm</b> * <b>Xlr1</b>* <b>Xlr2</b> / (<b>Xm</b> * <b>Xlr1</b> + <b>Xm</b> * <b>Xlr2</b> + <b>Xlr1</b> * <b>Xlr2</b>) <b>T''o</b> = (<b>Xm</b> + <b>Xlr1</b>) / (<b>omega</b><b><sub>0</sub></b> * <b>Rr1</b>) <b>T''''o</b> = (<b>Xm</b> * <b>Xlr1</b> + <b>Xm</b> * <b>Xlr2</b> + <b>Xlr1</b> * <b>Xlr2</b>) / (<b>omega</b><b><sub>0</sub></b> * <b>Rr2</b> * (<b>Xm </b>+ <b>Xlr1</b>) <b> </b>Same equations using CIM attributes from AsynchronousMachineTimeConstantReactance class on left of = sign and AsynchronousMachineEquivalentCircuit class on right (except as noted): xs = xm + RotatingMachineDynamics.statorLeakageReactance xp = RotatingMachineDynamics.statorLeakageReactance + xm * xlr1 / (xm + xlr1) xpp = RotatingMachineDynamics.statorLeakageReactance + xm * xlr1* xlr2 / (xm * xlr1 + xm * xlr2 + xlr1 * xlr2) tpo = (xm + xlr1) / (2*pi*nominal frequency * rr1) tppo = (xm * xlr1 + xm * xlr2 + xlr1 * xlr2) / (2*pi*nominal frequency * rr2 * (xm + xlr1).', 'schema/cim/IEC_CIM.ttl'),
  ('AsynchronousMachineKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('AsynchronousMachineTimeConstantReactance', 'AsynchronousMachineDynamics', 'http://www.iec.ch/TC57/CIM#', false, '<b>Parameter Notes:</b> <ol> <li>If <b>X''''</b> = <b>X''</b>, a single cage (one equivalent rotor winding per axis) is modelled.</li> <li>The p in the attribute names is a substitution for a prime in the usual parameter notation, e.g. tpo refers to T''o.</li> </ol> The parameters used for models expressed in time constant reactance form include: <ul> <li>RotatingMachine.ratedS (MVAbase)</li> <li>RotatingMachineDynamics.damping (D)</li> <li>RotatingMachineDynamics.inertia (H)</li> <li>RotatingMachineDynamics.saturationFactor (S1)</li> <li>RotatingMachineDynamics.saturationFactor120 (S12)</li> <li>RotatingMachineDynamics.statorLeakageReactance (Xl)</li> <li>RotatingMachineDynamics.statorResistance (Rs)</li> <li>.xs (Xs)</li> <li>.xp (X'')</li> <li>.xpp (X'''')</li> <li>.tpo (T''o)</li> <li>.tppo (T''''o).</li> </ul>', 'schema/cim/IEC_CIM.ttl'),
  ('AsynchronousMachineUserDefined', 'AsynchronousMachineDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Asynchronous machine whose dynamic behaviour is described by a user-defined model.', 'schema/cim/IEC_CIM.ttl'),
  ('AttributeInstanceComponent', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'A class used to provide information about an attribute.', 'schema/cim/IEC_CIM.ttl'),
  ('AttributeProperty', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Property for a particular attribute that contains name and value', 'schema/cim/IEC_CIM.ttl'),
  ('Auction', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A class providing the identification and type of an auction.', 'schema/cim/IEC_CIM.ttl'),
  ('Author', 'DocumentPersonRole', 'http://www.iec.ch/TC57/CIM#', false, 'Person who created document or activity record.', 'schema/cim/IEC_CIM.ttl'),
  ('AutomaticDispInstTypeCommitment', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('AutomaticDispatchMode', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('AuxiliaryAccount', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Variable and dynamic part of auxiliary agreement, generally representing the current state of the account related to the outstanding balance defined in auxiliary agreement.', 'schema/cim/IEC_CIM.ttl'),
  ('AuxiliaryAgreement', 'Agreement', 'http://www.iec.ch/TC57/CIM#', false, 'An ad-hoc auxiliary account agreement associated with a customer agreement, not part of the customer''s account, but typically subject to formal agreement between customer and supplier (utility). Typically this is used to collect revenue owed by the customer for other services or arrears accrued with the utility for other services. It is typically linked to a prepaid token purchase transaction, thus forcing the customer to make a payment towards settlement of the auxiliary account balance whenever the customer needs to purchase a prepaid token for electricity. The present status of the auxiliary agreement can be defined in the context of the utility''s business rules, for example: enabled, disabled, pending, over recovered, under recovered, written off, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('AuxiliaryCost', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Models Market clearing results for Auxillary costs', 'schema/cim/IEC_CIM.ttl'),
  ('AuxiliaryEquipment', 'Equipment', 'http://www.iec.ch/TC57/CIM#', false, 'AuxiliaryEquipment describe equipment that is not performing any primary functions but support for the equipment performing the primary function. AuxiliaryEquipment is attached to primary eqipment via an association with Terminal.', 'schema/cim/IEC_CIM.ttl'),
  ('AuxiliaryObject', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Models Auxillary Values', 'schema/cim/IEC_CIM.ttl'),
  ('AuxiliaryValues', 'AuxiliaryObject', 'http://www.iec.ch/TC57/CIM#', false, 'Models Auxillary Values', 'schema/cim/IEC_CIM.ttl'),
  ('BWRSteamSupply', 'SteamSupply', 'http://www.iec.ch/TC57/CIM#', false, 'Boiling water reactor used as a steam supply to a steam turbine.', 'schema/cim/IEC_CIM.ttl'),
  ('Bank', 'OrganisationRole', 'http://www.iec.ch/TC57/CIM#', false, 'Organisation that is a commercial bank, agency, or other institution that offers a similar service.', 'schema/cim/IEC_CIM.ttl'),
  ('BankAccount', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Bank account.', 'schema/cim/IEC_CIM.ttl'),
  ('BankAccountDetail', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Details of a bank account.', 'schema/cim/IEC_CIM.ttl'),
  ('BaseCaseConstraintLimit', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Possibly time-varying max MW or MVA and optionally Min MW limit or MVA limit (Y1 and Y2, respectively) assigned to a contingency analysis base case. Use CurveSchedule XAxisUnits to specify MW or MVA. To be used only if the BaseCaseConstraintLimit differs from the DefaultConstraintLimit.', 'schema/cim/IEC_CIM.ttl'),
  ('BaseFrequency', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The class describe a base frequency for a power system network. In case of multiple power networks with different frequencies, e.g. 50 or 60 Hertz each network will have it''s own base frequency class. Hence it is assumed that power system objects having different base frequencies appear in separate documents where each document has a single base frequency instance.', 'schema/cim/IEC_CIM.ttl'),
  ('BasePower', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The BasePower class defines the base power used in the per unit calculations.', 'schema/cim/IEC_CIM.ttl'),
  ('BaseReading', 'MeasurementValue', 'http://www.iec.ch/TC57/CIM#', false, 'Common representation for reading values. Note that a reading value may have multiple qualities, as produced by various systems (''ReadingQuality.source'').', 'schema/cim/IEC_CIM.ttl'),
  ('BaseVoltage', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Defines a system base voltage which is referenced.', 'schema/cim/IEC_CIM.ttl'),
  ('BaseWork', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Common representation for work and work tasks.', 'schema/cim/IEC_CIM.ttl'),
  ('BasicIntervalSchedule', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Schedule of values at points in time.', 'schema/cim/IEC_CIM.ttl'),
  ('Bay', 'EquipmentContainer', 'http://www.iec.ch/TC57/CIM#', false, 'A collection of power system resources (within a given substation) including conducting equipment, protection relays, measurements, and telemetry. A bay typically represents a physical grouping related to modularization of equipment.', 'schema/cim/IEC_CIM.ttl'),
  ('Bid', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Represents both bids to purchase and offers to sell energy or ancillary services in an RTO-sponsored market.', 'schema/cim/IEC_CIM.ttl'),
  ('BidCalculationBasis', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('BidDistributionFactor', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'This class allows SC to input different time intervals for distribution factors', 'schema/cim/IEC_CIM.ttl'),
  ('BidError', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'This class represent the error information for a bid that is detected during bid validation', 'schema/cim/IEC_CIM.ttl'),
  ('BidHourlyProductSchedule', 'RegularIntervalSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'Containment for bid parameters that are dependent on a market product type.', 'schema/cim/IEC_CIM.ttl'),
  ('BidHourlySchedule', 'RegularIntervalSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'Containment for bid hourly parameters that are not product dependent.', 'schema/cim/IEC_CIM.ttl'),
  ('BidMitigationStatus', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('BidMitigationType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('BidPriceCap', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'This class represent the bid price cap.', 'schema/cim/IEC_CIM.ttl'),
  ('BidPriceCapType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('BidPriceCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Relationship between unit operating price in $/hour (Y-axis) and unit output in MW (X-axis).', 'schema/cim/IEC_CIM.ttl'),
  ('BidPriceSchedule', 'RegularIntervalSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'Defines bid schedules to allow a product bid to use specified bid price curves for different time intervals.', 'schema/cim/IEC_CIM.ttl'),
  ('BidSelfSched', 'RegularIntervalSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'Defines self schedule values to be used for specified time intervals.', 'schema/cim/IEC_CIM.ttl'),
  ('BidSet', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'As set of mutually exclusive bids for which a maximum of one may be scheduled. Of these generating bids, only one generating bid can be scheduled at a time.', 'schema/cim/IEC_CIM.ttl'),
  ('BidStatusType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('BidTimeSeries', 'TimeSeries', 'http://www.iec.ch/TC57/CIM#', false, 'The formal specification of specific characteristics related to a bid.', 'schema/cim/IEC_CIM.ttl'),
  ('BidType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('BidTypeRMR', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('BilateralTransaction', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Bilateral transaction', 'schema/cim/IEC_CIM.ttl'),
  ('BillDeterminant', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Model various charges to support billing and settlement of', 'schema/cim/IEC_CIM.ttl'),
  ('BillMediaKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('BoilerControlMode', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Boundary', 'FrameworkPart', 'http://www.iec.ch/TC57/CIM#', false, 'A framework part that is a boundary between 2 frames.', 'schema/cim/IEC_CIM.ttl'),
  ('BranchEndFlow', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Dynamic flows and ratings associated with a branch end.', 'schema/cim/IEC_CIM.ttl'),
  ('BranchGroup', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A group of branch terminals whose directed flow summation is to be monitored. A branch group need not form a cutset of the network.', 'schema/cim/IEC_CIM.ttl'),
  ('BranchGroupTerminal', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'A specific directed terminal flow for a branch group.', 'schema/cim/IEC_CIM.ttl'),
  ('Breaker', 'ProtectedSwitch', 'http://www.iec.ch/TC57/CIM#', false, 'A mechanical switching device capable of making, carrying, and breaking currents under normal circuit conditions and also making, carrying for a specified time, and breaking currents under specified abnormal circuit conditions e.g. those of short circuit.', 'schema/cim/IEC_CIM.ttl'),
  ('BreakerConfiguration', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('BreakerInfo', 'OldSwitchInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Properties of breaker assets.', 'schema/cim/IEC_CIM.ttl'),
  ('BusNameMarker', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Used to apply user standard names to topology buses. Typically used for "bus/branch" case generation. Associated with one or more terminals that are normally connected with the bus name. The associated terminals are normally connected by non-retained switches. For a ring bus station configuration, all busbar terminals in the ring are typically associated. For a breaker and a half scheme, both busbars would normally be associated. For a ring bus, all busbars would normally be associated. For a "straight" busbar configuration, normally only the main terminal at the busbar would be associated.', 'schema/cim/IEC_CIM.ttl'),
  ('BusbarConfiguration', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('BusbarSection', 'Connector', 'http://www.iec.ch/TC57/CIM#', false, 'A conductor, or group of conductors, with negligible impedance, that serve to connect other conducting equipment within a single substation. Voltage measurements are typically obtained from VoltageTransformers that are connected to busbar sections. A bus bar section may have many physical terminals but for analysis is modelled with exactly one logical terminal.', 'schema/cim/IEC_CIM.ttl'),
  ('BusbarSectionInfo', 'AssetInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Busbar section data.', 'schema/cim/IEC_CIM.ttl'),
  ('Bushing', 'Asset', 'http://www.iec.ch/TC57/CIM#', false, 'Bushing asset.', 'schema/cim/IEC_CIM.ttl'),
  ('BushingInsulationKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('BushingInsulationPF', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Bushing insulation power factor condition as a result of a test. Typical status values are: Acceptable, Minor Deterioration or Moisture Absorption, Major Deterioration or Moisture Absorption, Failed.', 'schema/cim/IEC_CIM.ttl'),
  ('BushingInsulationPfTestKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('BusinessCase', 'WorkDocument', 'http://www.iec.ch/TC57/CIM#', false, 'Business justification for capital expenditures, usually addressing operations and maintenance costs as well.', 'schema/cim/IEC_CIM.ttl'),
  ('BusinessPlan', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'A BusinessPlan is an organized sequence of predetermined actions required to complete a future organizational objective. It is a type of document that typically references a schedule, physical and/or logical resources (assets and/or PowerSystemResources), locations, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('BusinessRole', 'OrganisationRole', 'http://www.iec.ch/TC57/CIM#', false, 'A business role that this organisation plays. A single organisation typically performs many functions, each one described as a role.', 'schema/cim/IEC_CIM.ttl'),
  ('CAESPlant', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'Compressed air energy storage plant.', 'schema/cim/IEC_CIM.ttl'),
  ('CIMDataObject', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A description of a version of instance data.', 'schema/cim/IEC_CIM.ttl'),
  ('CRR', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Congestion Revenue Rights (CRR) class that is inherited from a Document class. A CRR is a financial concept that is used to hedge congestion charges. The CRR is usually settled based on the Locational Marginal Prices (LMPs) that are calculated in the day-ahead market. These LMPs are determined by the Day-ahead resource schedules/bids. CRRs will not hedge against marginal losses. If the congestion component of LMP at the sink is greater than at the source, then the CRR owner is entitled to receive a portion of congestion revenues. If the congestion component at the sink is less than at the source, then an obligation-type CRR owner will be charged, but an option-type CRR owner will not.', 'schema/cim/IEC_CIM.ttl'),
  ('CRRCategoryType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('CRRHedgeType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('CRRMarket', 'Market', 'http://www.iec.ch/TC57/CIM#', false, 'Model that describes the Congestion Revenue Rights Auction Market', 'schema/cim/IEC_CIM.ttl'),
  ('CRROrgRole', 'OrganisationRole', 'http://www.iec.ch/TC57/CIM#', false, 'Identifies a way in which an organisation may participate with a defined Congestion Revenue Right (CRR).', 'schema/cim/IEC_CIM.ttl'),
  ('CRRRoleType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('CRRSegment', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'CRRSegment represents a segment of a CRR in a particular time frame. The segment class contains CRR kind, type, quantity, hedger type, time of use flag, and segment period.', 'schema/cim/IEC_CIM.ttl'),
  ('CRRSegmentType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('CTTempActivePowerCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Relationship between the combustion turbine''s power output rating in gross active power (X-axis) and the ambient air temperature (Y-axis).', 'schema/cim/IEC_CIM.ttl'),
  ('CUAllowableAction', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Allowed actions: Install, Remove, Transfer, Abandon, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('CUContractorItem', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Compatible unit contractor item.', 'schema/cim/IEC_CIM.ttl'),
  ('CUGroup', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A Compatible Unit Group identifies a set of compatible units which may be jointly utilized for estimating and designating jobs.', 'schema/cim/IEC_CIM.ttl'),
  ('CULaborCode', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Labor code associated with various compatible unit labor items.', 'schema/cim/IEC_CIM.ttl'),
  ('CULaborItem', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Compatible unit labor item.', 'schema/cim/IEC_CIM.ttl'),
  ('CUMaterialItem', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Compatible unit of a consumable supply item. For example, nuts, bolts, brackets, glue, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('CUWorkEquipmentItem', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Compatible unit for various types of WorkEquipmentAssets, including vehicles.', 'schema/cim/IEC_CIM.ttl'),
  ('Cabinet', 'AssetContainer', 'http://www.iec.ch/TC57/CIM#', false, 'Enclosure that offers protection to the equipment it contains and/or safety to people/animals outside it.', 'schema/cim/IEC_CIM.ttl'),
  ('CableConstructionKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('CableInfo', 'WireInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Cable data.', 'schema/cim/IEC_CIM.ttl'),
  ('CableOuterJacketKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('CableShieldMaterialKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('CalculationKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Capability', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Capabilities of a crew.', 'schema/cim/IEC_CIM.ttl'),
  ('Capacitance', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Capacitive part of reactance (imaginary part of impedance), at rated frequency.', 'schema/cim/IEC_CIM.ttl'),
  ('CapacitancePerLength', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Capacitance per unit of length.', 'schema/cim/IEC_CIM.ttl'),
  ('Card', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Documentation of the tender when it is a type of card (credit, debit, etc).', 'schema/cim/IEC_CIM.ttl'),
  ('Cashier', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The operator of the point of sale for the duration of CashierShift. Cashier is under the exclusive management control of Vendor.', 'schema/cim/IEC_CIM.ttl'),
  ('CashierShift', 'Shift', 'http://www.iec.ch/TC57/CIM#', false, 'The operating shift for a cashier, during which the cashier may transact against the cashier shift, subject to vendor shift being open.', 'schema/cim/IEC_CIM.ttl'),
  ('Channel', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A single path for the collection or reporting of register values over a period of time. For example, a register which measures forward energy can have two channels, one providing bulk quantity readings and the other providing interval readings of a fixed interval size.', 'schema/cim/IEC_CIM.ttl'),
  ('Charge', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A charge element associated with other entities such as tariff structures, auxiliary agreements or other charge elements. The total charge amount applicable to this instance of charge is the sum of fixed and variable portion.', 'schema/cim/IEC_CIM.ttl'),
  ('ChargeComponent', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A Charge Component is a list of configurable charge quality items to feed into settlement calculation and/or bill determinants.', 'schema/cim/IEC_CIM.ttl'),
  ('ChargeGroup', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Charge Group is the grouping of Charge Types for settlement invoicing purpose. Examples such as Ancillary Services, Interests, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('ChargeKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ChargeProfile', 'Profile', 'http://www.iec.ch/TC57/CIM#', false, 'A type of profile for financial charges', 'schema/cim/IEC_CIM.ttl'),
  ('ChargeProfileData', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Model of various charges associated with an energy profile to support billing and settlement', 'schema/cim/IEC_CIM.ttl'),
  ('ChargeType', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Charge Type is the basic level configuration for settlement to process specific charges for invoicing purpose. Examples such as: Day Ahead Spinning Reserve Default Invoice Interest Charge, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('CheckOutType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Cheque', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'The actual tender when it is a type of cheque.', 'schema/cim/IEC_CIM.ttl'),
  ('ChequeKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Clamp', 'ConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'A Clamp is a galvanic connection at a line segment where other equipment is connected. A Clamp does not cut the line segment. A Clamp is ConductingEquipment and has one Terminal with an associated ConnectivityNode. Any other ConductingEquipment can be connected to the Clamp ConnectivityNode.', 'schema/cim/IEC_CIM.ttl'),
  ('Classification', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Classification of level. Specify as 1..n, with 1 being the most detailed, highest priority, etc as described on the attribue using this data type.', 'schema/cim/IEC_CIM.ttl'),
  ('CleanTradeProductType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ClearanceAction', 'SwitchingStep', 'http://www.iec.ch/TC57/CIM#', false, 'Action on clearance document as a switching step.', 'schema/cim/IEC_CIM.ttl'),
  ('ClearanceActionKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ClearanceDocument', 'SafetyDocument', 'http://www.iec.ch/TC57/CIM#', false, 'Safety document used to authorise work on conducting equipment in the field. Tagged equipment is not allowed to be operated.', 'schema/cim/IEC_CIM.ttl'),
  ('CnodeDistributionFactor', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Participation factors per Cnode. Used to calculate "participation" of Cnode in an AggregateNode. Each Cnode associated to an AggregateNode would be assigned a participation factor for its participation within the AggregateNode.', 'schema/cim/IEC_CIM.ttl'),
  ('CogenerationPlant', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'A set of thermal generating units for the production of electrical energy and process steam (usually from the output of the steam turbines). The steam sendout is typically used for industrial purposes or for municipal heating and cooling.', 'schema/cim/IEC_CIM.ttl'),
  ('ComDirectionKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ComFunction', 'EndDeviceFunction', 'http://www.iec.ch/TC57/CIM#', false, 'Communication function of communication equipment or a device such as a meter.', 'schema/cim/IEC_CIM.ttl'),
  ('ComMedia', 'Asset', 'http://www.iec.ch/TC57/CIM#', false, 'Communication media such as fibre optic cable, power-line, telephone, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('ComModule', 'Asset', 'http://www.iec.ch/TC57/CIM#', false, 'An asset having communications capabilities that can be paired with a meter or other end device to provide the device with communication ability, through associated communication function. An end device that has communications capabilities through embedded hardware can use that function directly (without the communication module), or combine embedded communication function with additional communication functions provided through an external communication module (e.g. zigbee).', 'schema/cim/IEC_CIM.ttl'),
  ('ComTechnologyKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('CombinedCycleConfiguration', 'RegisteredGenerator', 'http://www.iec.ch/TC57/CIM#', false, 'Configuration options for combined cycle units. For example, a Combined Cycle with (CT1, CT2, ST1) will have (CT1, ST1) and (CT2, ST1) configurations as part of(1CT + 1STlogicalconfiguration).', 'schema/cim/IEC_CIM.ttl'),
  ('CombinedCycleConfigurationMember', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Configuration Member of CCP Configuration.', 'schema/cim/IEC_CIM.ttl'),
  ('CombinedCycleLogicalConfiguration', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Logical Configuration of a Combined Cycle plant. Operating Combined Cycle Plant (CCP) configurations are represented as Logical CCP Resources. Logical representation shall be used for Market applications to optimize and control Market Operations. Logical representation is also necessary for controlling the number of CCP configurations and to temper performance issues that may otherwise occur. For example,(2CT configuration),(1CT + 1ST configuration) are examples of logical configuration, without specifying the specific CT and ST participating in the configuration.', 'schema/cim/IEC_CIM.ttl'),
  ('CombinedCyclePlant', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'A set of combustion turbines and steam turbines where the exhaust heat from the combustion turbines is recovered to make steam for the steam turbines, resulting in greater overall plant efficiency.', 'schema/cim/IEC_CIM.ttl'),
  ('CombinedCycleTransitionState', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Defines the available from and to Transition States for the Combine Cycle Configurations.', 'schema/cim/IEC_CIM.ttl'),
  ('CombustionTurbine', 'PrimeMover', 'http://www.iec.ch/TC57/CIM#', false, 'A prime mover that is typically fueled by gas or light oil.', 'schema/cim/IEC_CIM.ttl'),
  ('Command', 'Control', 'http://www.iec.ch/TC57/CIM#', false, 'A Command is a discrete control used for supervisory control.', 'schema/cim/IEC_CIM.ttl'),
  ('CommitmentClearing', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Models results of market clearing which call for commitment of units.', 'schema/cim/IEC_CIM.ttl'),
  ('CommitmentType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Commitments', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Provides the necessary information (on a resource basis) to capture the Startup/Shutdown commitment results. This information is relevant to all markets.', 'schema/cim/IEC_CIM.ttl'),
  ('CommodityKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('CommunicationLink', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'The connection to remote units is through one or more communication links. Reduntant links may exist. The CommunicationLink class inherit PowerSystemResource. The intention is to allow CommunicationLinks to have Measurements. These Measurements can be used to model link status as operational, out of service, unit failure etc.', 'schema/cim/IEC_CIM.ttl'),
  ('CompatibleUnit', 'WorkDocument', 'http://www.iec.ch/TC57/CIM#', false, 'A pre-planned job model containing labor, material, and accounting requirements for standardized job planning.', 'schema/cim/IEC_CIM.ttl'),
  ('ComplianceEvent', 'ActivityRecord', 'http://www.iec.ch/TC57/CIM#', false, 'Compliance events are used for reporting regulatory or contract compliance issues and/or variances. These might be created as a consequence of local business processes and associated rules. It is anticipated that this class will be customised extensively to meet local implementation needs. Use inherited ''type'' to indicate that, for example, expected performance will not be met or reported as mandated.', 'schema/cim/IEC_CIM.ttl'),
  ('CompositeSwitch', 'Equipment', 'http://www.iec.ch/TC57/CIM#', false, 'A model of a set of individual Switches normally enclosed within the same cabinet and possibly with interlocks that restrict the combination of switch positions. These are typically found in medium voltage distribution networks. A CompositeSwitch could represent a Ring-Main-Unit (RMU), or pad-mounted switchgear, with primitive internal devices such as an internal bus-bar plus 3 or 4 internal switches each of which may individually be open or closed. A CompositeSwitch and a set of contained Switches can also be used to represent a multi-position switch e.g. a switch that can connect a circuit to Ground, Open or Busbar.', 'schema/cim/IEC_CIM.ttl'),
  ('CompositeSwitchInfo', 'AssetInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Properties of a composite switch.', 'schema/cim/IEC_CIM.ttl'),
  ('CompositeSwitchKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ConcentricNeutralCableInfo', 'CableInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Concentric neutral cable data.', 'schema/cim/IEC_CIM.ttl'),
  ('ConditionFactor', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'This is to specify the various condition factors for a design that may alter the cost estimate or the allocation.', 'schema/cim/IEC_CIM.ttl'),
  ('ConditionFactorKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Conductance', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Factor by which voltage must be multiplied to give corresponding power lost from a circuit. Real part of admittance.', 'schema/cim/IEC_CIM.ttl'),
  ('ConductancePerLength', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Real part of admittance per unit of length.', 'schema/cim/IEC_CIM.ttl'),
  ('ConductingEquipment', 'Equipment', 'http://www.iec.ch/TC57/CIM#', false, 'The parts of the AC power system that are designed to carry current or that are conductively connected through terminals.', 'schema/cim/IEC_CIM.ttl'),
  ('Conductor', 'ConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'Combination of conducting material with consistent electrical characteristics, building a single electrical system, used to carry current between points in the power system.', 'schema/cim/IEC_CIM.ttl'),
  ('ConfigurationEvent', 'ActivityRecord', 'http://www.iec.ch/TC57/CIM#', false, 'Used to report details on creation, change or deletion of an entity or its configuration.', 'schema/cim/IEC_CIM.ttl'),
  ('ConformLoad', 'EnergyConsumer', 'http://www.iec.ch/TC57/CIM#', false, 'ConformLoad represent loads that follow a daily load change pattern where the pattern can be used to scale the load with a system load.', 'schema/cim/IEC_CIM.ttl'),
  ('ConformLoadGroup', 'LoadGroup', 'http://www.iec.ch/TC57/CIM#', false, 'A group of loads conforming to an allocation pattern.', 'schema/cim/IEC_CIM.ttl'),
  ('ConformLoadSchedule', 'SeasonDayTypeSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'A curve of load versus time (X-axis) showing the active power values (Y1-axis) and reactive power (Y2-axis) for each unit of the period covered. This curve represents a typical pattern of load over the time period for a given day type and season.', 'schema/cim/IEC_CIM.ttl'),
  ('CongestionArea', 'AggregatedPnode', 'http://www.iec.ch/TC57/CIM#', false, 'Designated Congestion Area Definition (DCA)', 'schema/cim/IEC_CIM.ttl'),
  ('ConnectDisconnectFunction', 'EndDeviceFunction', 'http://www.iec.ch/TC57/CIM#', false, 'A function that will disconnect and reconnect the customer''s load under defined conditions.', 'schema/cim/IEC_CIM.ttl'),
  ('ConnectivityNode', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Connectivity nodes are points where terminals of AC conducting equipment are connected together with zero impedance.', 'schema/cim/IEC_CIM.ttl'),
  ('ConnectivityNodeContainer', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'A base class for all objects that may contain connectivity nodes or topological nodes.', 'schema/cim/IEC_CIM.ttl'),
  ('Connector', 'ConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'A conductor, or group of conductors, with negligible impedance, that serve to connect other conducting equipment within a single substation and are modelled with a single logical terminal.', 'schema/cim/IEC_CIM.ttl'),
  ('ConstraintClearing', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Groups all items associated with Binding Constraints and Constraint Violations per interval and market.', 'schema/cim/IEC_CIM.ttl'),
  ('ConstraintDuration', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Duration constraint to activate, to put in operation, to deactivate, ... a given event.', 'schema/cim/IEC_CIM.ttl'),
  ('ConstraintLimitType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ConstraintRampType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ConstraintResults', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Provides the Market results for the constraint processing for either the DAM or RTM. The data includes the constraint type (binding or violated), the solved value for the constraint, and the associated shadow price.', 'schema/cim/IEC_CIM.ttl'),
  ('ConstraintTerm', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A constraint term is one element of a linear constraint.', 'schema/cim/IEC_CIM.ttl'),
  ('ConsumptionTariffInterval', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'One of a sequence of intervals defined in terms of consumption quantity of a service such as electricity, water, gas, etc. It is typically used in association with TariffProfile to define the steps or blocks in a step tariff structure, where startValue simultaneously defines the entry value of this step and the closing value of the previous step. Where consumption is &gt;= startValue it falls within this interval and where consumption is &lt; startValue it falls within the previous interval.', 'schema/cim/IEC_CIM.ttl'),
  ('Contingency', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ContingencyConstraintLimit', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Possibly time-varying max MW or MVA and optionally Min MW limit or MVA limit (Y1 and Y2, respectively) assigned to a constraint for a specific contingency. Use CurveSchedule XAxisUnits to specify MW or MVA.', 'schema/cim/IEC_CIM.ttl'),
  ('ContingencyElement', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'An element of a system event to be studied by contingency analysis, representing a change in status of a single piece of equipment.', 'schema/cim/IEC_CIM.ttl'),
  ('ContingencyEquipment', 'ContingencyElement', 'http://www.iec.ch/TC57/CIM#', false, 'A equipment to which the in service status is to change such as a power transformer or AC line segment.', 'schema/cim/IEC_CIM.ttl'),
  ('ContingencyEquipmentStatusKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ContractDistributionFactor', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Distribution amoung resources at the sink point or source point', 'schema/cim/IEC_CIM.ttl'),
  ('ContractRight', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Provides definition of Transmission Ownership Right and Existing Transmission Contract identifiers for use by SCUC. RMR contract hosting: Startup lead time, Contract Service Limits, Max Service Hours, Max MWhs, Max Start-ups, Ramp Rate, Max Net Dependable Capacity, Min Capacity and Unit Substitution for DAM/RTM to retrieve;', 'schema/cim/IEC_CIM.ttl'),
  ('ContractType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ContractorItem', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Contractor information for work task.', 'schema/cim/IEC_CIM.ttl'),
  ('Control', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Control is used for supervisory/device control. It represents control outputs that are used to change the state in a process, e.g. close or open breaker, a set point value or a raise lower command.', 'schema/cim/IEC_CIM.ttl'),
  ('ControlArea', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'A control area is a grouping of generating units and/or loads and a cutset of tie lines (as terminals) which may be used for a variety of purposes including automatic generation control, powerflow solution area interchange control specification, and input to load forecasting. Note that any number of overlapping control area specifications can be superimposed on the physical model.', 'schema/cim/IEC_CIM.ttl'),
  ('ControlAreaDesignation', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Indicates Control Area associated with self-schedule.', 'schema/cim/IEC_CIM.ttl'),
  ('ControlAreaGeneratingUnit', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A control area generating unit. This class is needed so that alternate control area definitions may include the same generating unit. Note only one instance within a control area should reference a specific generating unit.', 'schema/cim/IEC_CIM.ttl'),
  ('ControlAreaOperator', 'Organisation', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ControlAreaSolutionData', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'State Estimator Solution Pool Interchange and Losses', 'schema/cim/IEC_CIM.ttl'),
  ('ControlAreaTypeKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ControlledAppliance', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Appliance controlled with a PAN device control.', 'schema/cim/IEC_CIM.ttl'),
  ('CoolantType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('CoolingKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('CoolingPowerRating', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'There are often stages of power which are associated with stages of cooling. For instance, a transformer may be rated 121kV on the primary, 15kV on the secondary and 4kV on the tertiary winding. These are voltage ratings and the power ratings are generally the same for all three windings and independent of the voltage ratings, there are instances where the tertiary may have a lower power rating. For example, for three stages, the power rating may be 15/20/25 MVA and the cooling is OA/FA/FOA. The 15 MVA rating goes with the OA cooling (Oil and Air cooling). This is called the self cooled rating as there are no external cooling enhancements. The 20 MVA rating goes with the FA cooling (Forced Air cooling), this means that when the fans are running and thus enhancing the cooling characteristics, the transformer can operate at a power level of 20 MVA. The 25 MVA rating goes with the FOA cooling (Forced Oil and Air cooling), this means that when the fans and pumps are running and thus enhancing the cooling characteristics even more than before, the transformer can operate at a power level of 25 MVA. This 15/20/25 MVA does not state how the power is split between the various windings. It may be 25 MVA input on the primary, 25 MVA output on the secondary and 0 MVA output on the tertiary. It may also operate at 25 MVA input on the primary, 17 MVA output on the secondary and 8 MVA output on the tertiary.', 'schema/cim/IEC_CIM.ttl'),
  ('CoordinateSystem', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Coordinate reference system.', 'schema/cim/IEC_CIM.ttl'),
  ('CorporateStandardKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('CostBasis', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('CostPerEnergyUnit', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Cost, in units of currency, per quantity of electrical energy generated.', 'schema/cim/IEC_CIM.ttl'),
  ('CostPerHeatUnit', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Cost, in units of currency, per quantity of heat generated.', 'schema/cim/IEC_CIM.ttl'),
  ('CostPerVolume', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Cost per unit volume.', 'schema/cim/IEC_CIM.ttl'),
  ('CostRate', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Cost, in units of currency, per elapsed time.', 'schema/cim/IEC_CIM.ttl'),
  ('CostType', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A categorization for resources, often costs, in accounting transactions. Examples include: material components, building in service, coal sales, overhead, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('Craft', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Craft of a person or a crew. Examples include overhead electric, underground electric, high pressure gas, etc. This ensures necessary knowledge and skills before being allowed to perform certain types of work.', 'schema/cim/IEC_CIM.ttl'),
  ('CreateCIMDataObject', 'IncrementalCIMDataObject', 'http://www.iec.ch/TC57/CIM#', false, 'An object is to be created in the context.', 'schema/cim/IEC_CIM.ttl'),
  ('Crew', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Group of people with specific skills, tools, and vehicles.', 'schema/cim/IEC_CIM.ttl'),
  ('CrewMember', 'OperationPersonRole', 'http://www.iec.ch/TC57/CIM#', false, 'Member of a crew.', 'schema/cim/IEC_CIM.ttl'),
  ('CrewType', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Custom description of the type of crew. This may be used to determine the type of work the crew can be assigned to. Examples include repair, tree trimming, switching, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('CsConverter', 'ACDCConverter', 'http://www.iec.ch/TC57/CIM#', false, 'DC side of the current source converter (CSC).', 'schema/cim/IEC_CIM.ttl'),
  ('CsOperatingModeKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('CsPpccControlKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Currency', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('CurrentEmergencyScheduledInterchange', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Control area emergency schedules', 'schema/cim/IEC_CIM.ttl'),
  ('CurrentFlow', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Electrical current with sign convention: positive flow is out of the conducting equipment into the connectivity node. Can be both AC and DC.', 'schema/cim/IEC_CIM.ttl'),
  ('CurrentLimit', 'OperationalLimit', 'http://www.iec.ch/TC57/CIM#', false, 'Operational limit on current.', 'schema/cim/IEC_CIM.ttl'),
  ('CurrentRelay', 'ProtectionEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'A device that checks current flow values in any direction or designated direction.', 'schema/cim/IEC_CIM.ttl'),
  ('CurrentScheduledInterchange', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Control area current net tie (scheduled interchange) sent to real time dispatch.', 'schema/cim/IEC_CIM.ttl'),
  ('CurrentStatusSC', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('CurrentTransformer', 'Sensor', 'http://www.iec.ch/TC57/CIM#', false, 'Instrument transformer used to measure electrical qualities of the circuit that is being protected and/or monitored. Typically used as current transducer for the purpose of metering or protection. A typical secondary current rating would be 5A.', 'schema/cim/IEC_CIM.ttl'),
  ('CurrentTransformerInfo', 'AssetInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Properties of current transformer asset.', 'schema/cim/IEC_CIM.ttl'),
  ('CurtailmentProfile', 'Profile', 'http://www.iec.ch/TC57/CIM#', false, 'Curtailing entity must be providing at least one service to the EnergyTransaction. The CurtailmentProfile must be completely contained within the EnergyProfile timeframe for this EnergyTransaction.', 'schema/cim/IEC_CIM.ttl'),
  ('Curve', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A multi-purpose curve or functional relationship between an independent variable (X-axis) and dependent (Y-axis) variables.', 'schema/cim/IEC_CIM.ttl'),
  ('CurveData', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Multi-purpose data points for defining a curve. The use of this generic class is discouraged if a more specific class can be used to specify the x and y axis values along with their specific data types.', 'schema/cim/IEC_CIM.ttl'),
  ('CurveStyle', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Customer', 'OrganisationRole', 'http://www.iec.ch/TC57/CIM#', false, 'Organisation receiving services from service supplier.', 'schema/cim/IEC_CIM.ttl'),
  ('CustomerAccount', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Assignment of a group of products and services purchased by the customer through a customer agreement, used as a mechanism for customer billing and payment. It contains common information from the various types of customer agreements to create billings (invoices) for a customer and receive payment.', 'schema/cim/IEC_CIM.ttl'),
  ('CustomerAgreement', 'Agreement', 'http://www.iec.ch/TC57/CIM#', false, 'Agreement between the customer and the service supplier to pay for service at a specific service location. It records certain billing information about the type of service provided at the service location and is used during charge creation to determine the type of service.', 'schema/cim/IEC_CIM.ttl'),
  ('CustomerBillingInfo', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'The creation of the monthly customer billing statements is the method employed to notify Customers of charges, adjustments and credits applied to their account for Services and Products. The actuall billing occurs through an ErpInvoice. The CustomerBillingInfo includes information from the payment, collection, meter reading, installed meter, service, site, customer, customer account, customer agreement, services and pricing subject areas. Each component price shows up as a separate line item on the ErpInvoice. The Customer Billing Statement may include collection and account messages, marketing/civic event messages and bill inserts. One Customer Billing Statement is produced for all Agreements under a CustomerAccount per billing cycle date defined in ''CustomerAccount.billingCycle''. The history of CustomerBillingInfo, Invoices and Payments is to be maintained in associated ActivityRecords.', 'schema/cim/IEC_CIM.ttl'),
  ('CustomerBillingKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('CustomerConsumer', 'Organisation', 'http://www.iec.ch/TC57/CIM#', false, 'The energy buyer in the energy marketplace.', 'schema/cim/IEC_CIM.ttl'),
  ('CustomerKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('CustomerNotification', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Conditions for notifying the customer about the changes in the status of their service (e.g., outage restore, estimated restoration time, tariff or service level change, etc.)', 'schema/cim/IEC_CIM.ttl'),
  ('Cut', 'Switch', 'http://www.iec.ch/TC57/CIM#', false, 'A cut separates a line segment into two parts. The cut appears as a switch inserted between these two parts and connects them together. As the cut is normally open there is no galvanic connection between the two line segment parts. But it is possible to close the cut to get galvanic connection. The cut terminals are oriented towards the line segment terminals with the same sequence number. Hence the cut terminal with sequence number equal to 1 is oriented to the line segment''s terminal with sequence number equal to 1. The cut terminals also act as connection points for jumpers and other equipment, e.g. a mobile generator. To enable this, connectivity nodes are placed at the cut terminals. Once the connectivity nodes are in place any conducting equipment can be connected at them.', 'schema/cim/IEC_CIM.ttl'),
  ('CutAction', 'SwitchingStep', 'http://www.iec.ch/TC57/CIM#', false, 'Action on cut as a switching step.', 'schema/cim/IEC_CIM.ttl'),
  ('DAMMarketType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('DCBaseTerminal', 'ACDCTerminal', 'http://www.iec.ch/TC57/CIM#', false, 'An electrical connection point at a piece of DC conducting equipment. DC terminals are connected at one physical DC node that may have multiple DC terminals connected. A DC node is similar to an AC connectivity node. The model enforces that DC connections are distinct from AC connections.', 'schema/cim/IEC_CIM.ttl'),
  ('DCBreaker', 'DCSwitch', 'http://www.iec.ch/TC57/CIM#', false, 'A breaker within a DC system.', 'schema/cim/IEC_CIM.ttl'),
  ('DCBusbar', 'DCConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'A busbar within a DC system.', 'schema/cim/IEC_CIM.ttl'),
  ('DCChopper', 'DCConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'Low resistance equipment used in the internal DC circuit to balance voltages. It has typically positive and negative pole terminals and a ground.', 'schema/cim/IEC_CIM.ttl'),
  ('DCConductingEquipment', 'Equipment', 'http://www.iec.ch/TC57/CIM#', false, 'The parts of the DC power system that are designed to carry current or that are conductively connected through DC terminals.', 'schema/cim/IEC_CIM.ttl'),
  ('DCConverterOperatingModeKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('DCConverterUnit', 'DCEquipmentContainer', 'http://www.iec.ch/TC57/CIM#', false, 'Indivisible operative unit comprising all equipment between the point of common coupling on the AC side and the point of common coupling  DC side, essentially one or more converters, together with one or more converter transformers, converter control equipment, essential protective and switching devices and auxiliaries, if any, used for conversion.', 'schema/cim/IEC_CIM.ttl'),
  ('DCDisconnector', 'DCSwitch', 'http://www.iec.ch/TC57/CIM#', false, 'A disconnector within a DC system.', 'schema/cim/IEC_CIM.ttl'),
  ('DCEquipmentContainer', 'EquipmentContainer', 'http://www.iec.ch/TC57/CIM#', false, 'A modeling construct to provide a root class for containment of DC as well as AC equipment. The class differ from the EquipmentContaner for AC in that it may also contain DCNodes. Hence it can contain both AC and DC equipment.', 'schema/cim/IEC_CIM.ttl'),
  ('DCGround', 'DCConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'A ground within a DC system.', 'schema/cim/IEC_CIM.ttl'),
  ('DCIMFaultModel', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('DCIMWireInfo', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('DCLine', 'DCEquipmentContainer', 'http://www.iec.ch/TC57/CIM#', false, 'Overhead lines and/or cables connecting two or more HVDC substations.', 'schema/cim/IEC_CIM.ttl'),
  ('DCLineSegment', 'DCConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'A wire or combination of wires not insulated from one another, with consistent electrical characteristics, used to carry direct current between points in the DC region of the power system.', 'schema/cim/IEC_CIM.ttl'),
  ('DCNode', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'DC nodes are points where terminals of DC conducting equipment are connected together with zero impedance.', 'schema/cim/IEC_CIM.ttl'),
  ('DCPolarityKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('DCSeriesDevice', 'DCConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'A series device within the DC system, typically a reactor used for filtering or smoothing. Needed for transient and short circuit studies.', 'schema/cim/IEC_CIM.ttl'),
  ('DCShunt', 'DCConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'A shunt device within the DC system, typically used for filtering. Needed for transient and short circuit studies.', 'schema/cim/IEC_CIM.ttl'),
  ('DCSwitch', 'DCConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'A switch within the DC system.', 'schema/cim/IEC_CIM.ttl'),
  ('DCTerminal', 'DCBaseTerminal', 'http://www.iec.ch/TC57/CIM#', false, 'An electrical connection point to generic DC conducting equipment.', 'schema/cim/IEC_CIM.ttl'),
  ('DCTopologicalIsland', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'An electrically connected subset of the network. DC topological islands can change as the current network state changes: e.g. due to - disconnect switches or breakers change state in a SCADA/EMS - manual creation, change or deletion of topological nodes in a planning tool.', 'schema/cim/IEC_CIM.ttl'),
  ('DCTopologicalNode', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'DC bus.', 'schema/cim/IEC_CIM.ttl'),
  ('Damping', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Per-unit active power variation with frequency referenced on the system apparent power base. Typical values are in range 1.0 - 2.0.', 'schema/cim/IEC_CIM.ttl'),
  ('Dataset', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Versioned instance of a model part. This would correspond to a payload of instance data without a header. The MRID would be used in audit trail, not in reusable script intended to work with new versions of data. A dataset could be serialized multiple times and in multiple technologies, yet retain the same identity.', 'schema/cim/IEC_CIM.ttl'),
  ('DatasetArg', 'ModelOperationArg', 'http://www.iec.ch/TC57/CIM#', false, 'A model operation argument referencing a dataset instance.', 'schema/cim/IEC_CIM.ttl'),
  ('DatasetArgDescription', 'ModelOperationArgDescription', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('DateAndOrTime', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'The date and or the time.', 'schema/cim/IEC_CIM.ttl'),
  ('DateInterval', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Interval between two dates.', 'schema/cim/IEC_CIM.ttl'),
  ('DateTimeInterval', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Interval between two date and time points.', 'schema/cim/IEC_CIM.ttl'),
  ('DayType', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Group of similar days. For example it could be used to represent weekdays, weekend, or holidays.', 'schema/cim/IEC_CIM.ttl'),
  ('Decimal', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Decimal is the base-10 notational system for representing real numbers.', 'schema/cim/IEC_CIM.ttl'),
  ('DecimalQuantity', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('DefaultBid', 'Bid', 'http://www.iec.ch/TC57/CIM#', false, 'DefaultBid is a generic class to hold Default Energy Bid, Default Startup Bid, and Default Minimum Load Bid: Default Energy Bid A Default Energy Bid is a monotonically increasing staircase function consisting at maximum 10 economic bid segments, or 10 ($/MW, MW) pairs. There are three methods for determining the Default Energy Bid: <ul> <li>Cost Based: derived from the Heat Rate or Average Cost multiplied by the Gas Price Index plus 10%. </li> <li>LMP Based: a weighted average of LMPs in the preceding 90 days</li> <li>Negotiated: an amount negotiated with the designated Independent Entity.</li> </ul> Default Startup Bid A Default Startup Bid (DSUB) shall be calculated for each RMR unit based on the Startup Cost stored in the Master File and the applicable GPI and EPI Default Minimum Load Bid A Default Minimum Load Bid (DMLB) shall be calculated for each RMR unit based on the Minimum Load Cost stored in the Master File and the applicable GPI.', 'schema/cim/IEC_CIM.ttl'),
  ('DefaultBidCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Default bid curve for default energy bid curve and default startup curves (cost and time)', 'schema/cim/IEC_CIM.ttl'),
  ('DefaultBidCurveData', 'CurveData', 'http://www.iec.ch/TC57/CIM#', false, 'Curve data for default bid curve and startup cost curve.', 'schema/cim/IEC_CIM.ttl'),
  ('DefaultConstraintLimit', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Possibly time-varying max MW or MVA and optionally Min MW limit or MVA limit (Y1 and Y2, respectively) applied as a default value if no specific constraint limits are specified for a contingency analysis. Use CurveSchedule XAxisUnits to specify MW or MVA.', 'schema/cim/IEC_CIM.ttl'),
  ('DeleteCIMDataObject', 'IncrementalCIMDataObject', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('DemandResponseProgram', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Demand response program.', 'schema/cim/IEC_CIM.ttl'),
  ('DemographicKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Design', 'WorkDocument', 'http://www.iec.ch/TC57/CIM#', false, 'A design for consideration by customers, potential customers, or internal work. Note that the Version of design is the revision attribute that is inherited from Document.', 'schema/cim/IEC_CIM.ttl'),
  ('DesignKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('DesignLocation', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A logical part of the design (e.g., pole and all equipment on a pole). This includes points and spans.', 'schema/cim/IEC_CIM.ttl'),
  ('DesignLocationCU', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Compatible unit at a given design location.', 'schema/cim/IEC_CIM.ttl'),
  ('DetailedDiagrams_:_part3:_MeasurementList_message_type', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('DetailedDiagrams_:_part4:_AssetCatalogue_message_type', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('DetailedDiagrams_:_part4:_TypeAssetCatalogue_message_type', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('DiagnosisDataSet', 'ProcedureDataSet', 'http://www.iec.ch/TC57/CIM#', false, 'The result of a problem (typically an asset failure) diagnosis.', 'schema/cim/IEC_CIM.ttl'),
  ('Diagram', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The diagram being exchanged. The coordinate system is a standard Cartesian coordinate system and the orientation attribute defines the orientation.', 'schema/cim/IEC_CIM.ttl'),
  ('DiagramObject', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'An object that defines one or more points in a given space. This object can be associated with anything that specializes IdentifiedObject. For single line diagrams such objects typically include such items as analog values, breakers, disconnectors, power transformers, and transmission lines.', 'schema/cim/IEC_CIM.ttl'),
  ('DiagramObjectGluePoint', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'This is used for grouping diagram object points from different diagram objects that are considered to be glued together in a diagram even if they are not at the exact same coordinates.', 'schema/cim/IEC_CIM.ttl'),
  ('DiagramObjectPoint', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'A point in a given space defined by 3 coordinates and associated to a diagram object. The coordinates may be positive or negative as the origin does not have to be in the corner of a diagram.', 'schema/cim/IEC_CIM.ttl'),
  ('DiagramObjectStyle', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A reference to a style used by the originating system for a diagram object. A diagram object style describes information such as line thickness, shape such as circle or rectangle etc, and color.', 'schema/cim/IEC_CIM.ttl'),
  ('DiagramStyle', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The diagram style refer to a style used by the originating system for a diagram. A diagram style describes information such as schematic, geographic, bus-branch etc.', 'schema/cim/IEC_CIM.ttl'),
  ('DifferentialModel', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'A set of statements describing the changes in the network model. The statement is defined in the incremental model.', 'schema/cim/IEC_CIM.ttl'),
  ('DimensionsInfo', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'As applicable, the basic linear, area, or volume dimensions of an asset, asset type (AssetModel) or other type of object (such as land area). Units and multipliers are specified per dimension.', 'schema/cim/IEC_CIM.ttl'),
  ('DiscExcContIEEEDEC1A', 'DiscontinuousExcitationControlDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Type DEC1A discontinuous excitation control model that boosts generator excitation to a level higher than that demanded by the voltage regulator and stabilizer immediately following a system fault. Reference: IEEE Standard 421.5-2005 Section 12.2.', 'schema/cim/IEC_CIM.ttl'),
  ('DiscExcContIEEEDEC2A', 'DiscontinuousExcitationControlDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Type DEC2A model for the discontinuous excitation control. This system provides transient excitation boosting via an open-loop control as initiated by a trigger signal generated remotely. Reference: IEEE Standard 421.5-2005 Section 12.3.', 'schema/cim/IEC_CIM.ttl'),
  ('DiscExcContIEEEDEC3A', 'DiscontinuousExcitationControlDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Type DEC3A model. In some systems, the stabilizer output is disconnected from the regulator immediately following a severe fault to prevent the stabilizer from competing with action of voltage regulator during the first swing. Reference: IEEE Standard 421.5-2005 Section 12.4.', 'schema/cim/IEC_CIM.ttl'),
  ('Disconnector', 'Switch', 'http://www.iec.ch/TC57/CIM#', false, 'A manually operated or motor operated mechanical switching device used for changing the connections in a circuit, or for isolating a circuit or equipment from a source of power. It is required to open or close circuits when negligible current is broken or made.', 'schema/cim/IEC_CIM.ttl'),
  ('DiscontinuousExcitationControlDynamics', 'DynamicsFunctionBlock', 'http://www.iec.ch/TC57/CIM#', false, 'Discontinuous excitation control function block whose behaviour is described by reference to a standard model <font color="#0f0f0f">or by definition of a user-defined model</font>.', 'schema/cim/IEC_CIM.ttl'),
  ('DiscontinuousExcitationControlUserDefined', 'DiscontinuousExcitationControlDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Discontinuous excitation control function block whose dynamic behaviour is described by <font color="#0f0f0f">a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('Discrete', 'Measure', 'http://www.iec.ch/TC57/CIM#', false, 'Discrete represents a discrete Measurement, i.e. a Measurement representing discrete values, e.g. a Breaker position.', 'schema/cim/IEC_CIM.ttl'),
  ('DiscreteCommand', 'Command', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('DiscreteMeasurementValueQuality', 'MeasurementValueQuality', 'http://www.iec.ch/TC57/CIM#', false, 'Measurement quality flags for Discrete Values.', 'schema/cim/IEC_CIM.ttl'),
  ('DiscreteValue', 'MeasurementValue', 'http://www.iec.ch/TC57/CIM#', false, 'DiscreteValue represents a discrete MeasurementValue.', 'schema/cim/IEC_CIM.ttl'),
  ('DispatchAcceptStatus', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('DispatchInstReply', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Response from registered resource acknowleging receipt of dispatch instructions', 'schema/cim/IEC_CIM.ttl'),
  ('DispatchResponseType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('DispatchTransactionType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Displacement', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Unit of displacement relative a reference position, hence can be negative.', 'schema/cim/IEC_CIM.ttl'),
  ('DistributionFactorSet', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'A containing class that groups all the distribution factors within a market. This is calculated daily for DA factors and hourly for RT factors.', 'schema/cim/IEC_CIM.ttl'),
  ('Document', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Parent class for different groupings of information collected and managed as a part of a business process. It will frequently contain references to other objects, such as assets, people and power system resources.', 'schema/cim/IEC_CIM.ttl'),
  ('DocumentOrganisationRole', 'OrganisationRole', 'http://www.iec.ch/TC57/CIM#', false, 'Role an organisation plays with respect to documents.', 'schema/cim/IEC_CIM.ttl'),
  ('DocumentPersonRole', 'PersonRole', 'http://www.iec.ch/TC57/CIM#', false, 'Person role with respect to documents.', 'schema/cim/IEC_CIM.ttl'),
  ('Domain', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'An area of activity defined within the energy market.', 'schema/cim/IEC_CIM.ttl'),
  ('DopInstruction', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Provides the necessary information (on a resource basis) to capture the Dispatch Operating Point (DOP) results on a Dispatch interval. This information is only relevant to the RT interval market.', 'schema/cim/IEC_CIM.ttl'),
  ('DotInstruction', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Provides the necessary information (on a resource basis) to capture the Dispatch Operating Target (DOT) results on a Dispatch interval. This information is only relevant to the RT interval market.', 'schema/cim/IEC_CIM.ttl'),
  ('DroopSignalFeedbackKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('DrumBoiler', 'FossilSteamSupply', 'http://www.iec.ch/TC57/CIM#', false, 'Drum boiler.', 'schema/cim/IEC_CIM.ttl'),
  ('DuctBank', 'AssetContainer', 'http://www.iec.ch/TC57/CIM#', false, 'A duct contains individual wires in the layout as specified with associated wire spacing instances; number of them gives the number of conductors in this duct.', 'schema/cim/IEC_CIM.ttl'),
  ('Due', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Details on amounts due for an account.', 'schema/cim/IEC_CIM.ttl'),
  ('Duration', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Duration as "PnYnMnDTnHnMnS" which conforms to ISO 8601, where nY expresses a number of years, nM a number of months, nD a number of days. The letter T separates the date expression from the time expression and, after it, nH identifies a number of hours, nM a number of minutes and nS a number of seconds. The number of seconds could be expressed as a decimal number, but all other numbers are integers.', 'schema/cim/IEC_CIM.ttl'),
  ('DynamicSchedule', 'BasicIntervalSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'A continuously variable component of a control area''s MW net interchange schedule. Dynamic schedules are sent and received by control areas.', 'schema/cim/IEC_CIM.ttl'),
  ('DynamicsFunctionBlock', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Abstract parent class for all Dynamics function blocks.', 'schema/cim/IEC_CIM.ttl'),
  ('EarthFaultCompensator', 'ConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'A conducting equipment used to represent a connection to ground which is typically used to compensate earth faults.. An earth fault compensator device modeled with a single terminal implies a second terminal solidly connected to ground. If two terminals are modeled, the ground is not assumed and normal connection rules apply.', 'schema/cim/IEC_CIM.ttl'),
  ('Editor', 'DocumentPersonRole', 'http://www.iec.ch/TC57/CIM#', false, 'Person who modified the document.', 'schema/cim/IEC_CIM.ttl'),
  ('ElectricalAssets', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ElectronicAddress', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Electronic address information.', 'schema/cim/IEC_CIM.ttl'),
  ('Emission', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Quantity of emission per fuel heat content.', 'schema/cim/IEC_CIM.ttl'),
  ('EmissionAccount', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Accounts for tracking emissions usage and credits for thermal generating units. A unit may have zero or more emission accounts, and will typically have one for tracking usage and one for tracking credits.', 'schema/cim/IEC_CIM.ttl');
INSERT INTO metadata.cim_ref_classes (name, parent_name, namespace, is_abstract, description, source) VALUES
  ('EmissionCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Relationship between the unit''s emission rate in units of mass per hour (Y-axis) and output active power (X-axis) for a given type of emission. This curve applies when only one type of fuel is being burned.', 'schema/cim/IEC_CIM.ttl'),
  ('EmissionType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('EmissionValueSource', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('EndDevice', 'AssetContainer', 'http://www.iec.ch/TC57/CIM#', false, 'Asset container that performs one or more end device functions. One type of end device is a meter which can perform metering, load management, connect/disconnect, accounting functions, etc. Some end devices, such as ones monitoring and controlling air conditioners, refrigerators, pool pumps may be connected to a meter. All end devices may have communication capability defined by the associated communication function(s). An end device may be owned by a consumer, a service provider, utility or otherwise. There may be a related end device function that identifies a sensor or control point within a metering application or communications systems (e.g., water, gas, electricity). Some devices may use an optical port that conforms to the ANSI C12.18 standard for communications.', 'schema/cim/IEC_CIM.ttl'),
  ('EndDeviceAction', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Action/command performed by an end device on a device other than the end device.', 'schema/cim/IEC_CIM.ttl'),
  ('EndDeviceCapability', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Inherent capabilities of an end device (i.e., the functions it supports).', 'schema/cim/IEC_CIM.ttl'),
  ('EndDeviceControl', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Instructs an end device (or an end device group) to perform a specified action.', 'schema/cim/IEC_CIM.ttl'),
  ('EndDeviceControlType', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Detailed description for a control produced by an end device. Values in attributes allow for creation of recommended codes to be used for identifying end device controls as follows: &lt;type&gt;.&lt;domain&gt;.&lt;subDomain&gt;.&lt;eventOrAction&gt;.', 'schema/cim/IEC_CIM.ttl'),
  ('EndDeviceEvent', 'ActivityRecord', 'http://www.iec.ch/TC57/CIM#', false, 'Event detected by a device function associated with the end device.', 'schema/cim/IEC_CIM.ttl'),
  ('EndDeviceEventDetail', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Name-value pair, specific to end device events.', 'schema/cim/IEC_CIM.ttl'),
  ('EndDeviceEventType', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Detailed description for an event produced by an end device. Values in attributes allow for creation of recommended codes to be used for identifying end device events as follows: &lt;type&gt;.&lt;domain&gt;.&lt;subDomain&gt;.&lt;eventOrAction&gt;.', 'schema/cim/IEC_CIM.ttl'),
  ('EndDeviceFunction', 'AssetFunction', 'http://www.iec.ch/TC57/CIM#', false, 'Function performed by an end device such as a meter, communication equipment, controllers, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('EndDeviceFunctionKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('EndDeviceGroup', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Abstraction for management of group communications within a two-way AMR system or the data for a group of related end devices. Commands can be issued to all of the end devices that belong to the group using a defined group address and the underlying AMR communication infrastructure.', 'schema/cim/IEC_CIM.ttl'),
  ('EndDeviceInfo', 'AssetInfo', 'http://www.iec.ch/TC57/CIM#', false, 'End device data.', 'schema/cim/IEC_CIM.ttl'),
  ('EndDeviceTiming', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Timing for the control actions of end devices.', 'schema/cim/IEC_CIM.ttl'),
  ('EnergyArea', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Describes an area having energy production or consumption. Specializations are intended to support the load allocation function as typically required in energy management systems or planning studies to allocate hypothesized load levels to individual load points for power flow analysis. Often the energy area can be linked to both measured and forecast load levels.', 'schema/cim/IEC_CIM.ttl'),
  ('EnergyConsumer', 'ConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'Generic user of energy - a point of consumption on the power system model.', 'schema/cim/IEC_CIM.ttl'),
  ('EnergyConsumerData', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Optimal Power Flow or State Estimator Load Data for OTS. This is used for RealTime, Study and Maintenance Users', 'schema/cim/IEC_CIM.ttl'),
  ('EnergyConsumerPhase', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'A single phase of an energy consumer.', 'schema/cim/IEC_CIM.ttl'),
  ('EnergyMarket', 'Market', 'http://www.iec.ch/TC57/CIM#', false, 'Energy and Ancillary Market (e.g. Energy, Spinning Reserve, Non-Spinning Reserve) with a description of the Market operation control parameters.', 'schema/cim/IEC_CIM.ttl'),
  ('EnergyPriceCurve', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Relationship between a price in $(or other monetary unit) /hour (Y-axis) and a MW value (X-axis).', 'schema/cim/IEC_CIM.ttl'),
  ('EnergyPriceIndex', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'An Energy Price Index for each Resource is valid for a period (e.g. daily) that is identified by a Valid Period Start Time and a Valid Period End Time. An Energy Price Index is in $/MWh.', 'schema/cim/IEC_CIM.ttl'),
  ('EnergyPriceIndexType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('EnergyProduct', 'Agreement', 'http://www.iec.ch/TC57/CIM#', false, 'An EnergyProduct is offered commercially as a ContractOrTariff.', 'schema/cim/IEC_CIM.ttl'),
  ('EnergyProductType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('EnergyProfile', 'Profile', 'http://www.iec.ch/TC57/CIM#', false, 'Specifies the start time, stop time, level for an EnergyTransaction.', 'schema/cim/IEC_CIM.ttl'),
  ('EnergySchedulingType', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Used to define the type of generation for scheduling purposes.', 'schema/cim/IEC_CIM.ttl'),
  ('EnergySource', 'ConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'A generic equivalent for an energy supplier on a transmission or distribution voltage level.', 'schema/cim/IEC_CIM.ttl'),
  ('EnergySourceAction', 'SwitchingStep', 'http://www.iec.ch/TC57/CIM#', false, 'Action on energy source as a switching step.', 'schema/cim/IEC_CIM.ttl'),
  ('EnergySourcePhase', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'Represents the single phase information of an unbalanced energy source.', 'schema/cim/IEC_CIM.ttl'),
  ('EnergyTransaction', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Specifies the schedule for energy transfers between interchange areas that are necessary to satisfy the associated interchange transaction.', 'schema/cim/IEC_CIM.ttl'),
  ('EnergyTransactionType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('EnergyTypeCode', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('EnvironmentalDependentLimit', 'LimitDependency', 'http://www.iec.ch/TC57/CIM#', false, 'This is a environmental based limit dependency model for calculating operational limits.', 'schema/cim/IEC_CIM.ttl'),
  ('Equipment', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'The parts of a power system that are physical devices, electronic or mechanical.', 'schema/cim/IEC_CIM.ttl'),
  ('EquipmentContainer', 'ConnectivityNodeContainer', 'http://www.iec.ch/TC57/CIM#', false, 'A modeling construct to provide a root class for containing equipment.', 'schema/cim/IEC_CIM.ttl'),
  ('EquipmentFault', 'Fault', 'http://www.iec.ch/TC57/CIM#', false, 'A fault applied at the terminal, external to the equipment. This class is not used to specify faults internal to the equipment.', 'schema/cim/IEC_CIM.ttl'),
  ('EquipmentLimitSeriesComponent', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'This represents one instance of an equipment that contributes to the calculation of an operational limit.', 'schema/cim/IEC_CIM.ttl'),
  ('EquipmentStatusType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('EquivalentBranch', 'EquivalentEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents equivalent branches.', 'schema/cim/IEC_CIM.ttl'),
  ('EquivalentEquipment', 'ConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents equivalent objects that are the result of a network reduction. The class is the base for equivalent objects of different types.', 'schema/cim/IEC_CIM.ttl'),
  ('EquivalentInjection', 'EquivalentEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'This class represents equivalent injections (generation or load). Voltage regulation is allowed only at the point of connection.', 'schema/cim/IEC_CIM.ttl'),
  ('EquivalentNetwork', 'ConnectivityNodeContainer', 'http://www.iec.ch/TC57/CIM#', false, 'A class that represents an external meshed network that has been reduced to an electrically equivalent model. The ConnectivityNodes contained in the equivalent are intended to reflect internal nodes of the equivalent. The boundary Connectivity nodes where the equivalent connects outside itself are NOT contained by the equivalent.', 'schema/cim/IEC_CIM.ttl'),
  ('EquivalentShunt', 'EquivalentEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents equivalent shunts.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpAccountKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ErpBOM', 'ErpDocument', 'http://www.iec.ch/TC57/CIM#', false, 'Information that generally describes the Bill of Material Structure and its contents for a utility. This is used by ERP systems to transfer Bill of Material information between two business applications.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpBankAccount', 'BankAccount', 'http://www.iec.ch/TC57/CIM#', false, 'Relationship under a particular name, usually evidenced by a deposit against which withdrawals can be made. Types of bank accounts include: demand, time, custodial, joint, trustee, corporate, special, and regular accounts. A statement of transactions during a fiscal period and the resulting balance is maintained on each account. For Payment metering, the account is associated with Bank and Supplier, reflecting details of the bank account used for depositing revenue collected by TokenVendor. The name of the account holder should be specified in ''name'' attribute.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpBomItemData', 'ErpIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'An individual item on a bill of materials.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpChartOfAccounts', 'ErpDocument', 'http://www.iec.ch/TC57/CIM#', false, 'Accounting structure of a business. Each account represents a financial aspect of a business, such as its Accounts Payable, or the value of its inventory, or its office supply expenses.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpCompetency', 'ErpIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Information that describes aptitudes of a utility employee. Unlike Skills that an ErpPerson must be certified to perform before undertaking certain type of assignments (to be able to perfrom a Craft), ErpCompetency has more to do with typical Human Resource (HR) matters such as schooling, training, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpDocument', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Shadow class for Document, to isolate subclassing from this package. If any subclass gets normative and needs inheritance, it will inherit directly from Document.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpEngChangeOrder', 'ErpDocument', 'http://www.iec.ch/TC57/CIM#', false, 'General Utility Engineering Change Order information.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpIdentifiedObject', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Shadow class for IdentifiedObject, to isolate subclassing from this package. If any subclass gets normative and needs inheritance, it will inherit directly from IdentifiedObject.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpInventory', 'ErpIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Utility inventory-related information about an item or part (and not for description of the item and its attributes). It is used by ERP applications to enable the synchronization of Inventory data that exists on separate Item Master databases. This data is not the master data that describes the attributes of the item such as dimensions, weight, or unit of measure - it describes the item as it exists at a specific location.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpInventoryCount', 'ErpIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'This is related to Inventory physical counts organized by AssetModel. Note that a count of a type of asset can be accomplished by the association inherited by AssetModel (from Document) to Asset. It enables ERP applications to transfer an inventory count between ERP and the actual physical inventory location. This count may be a cycle count or a physical count.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpInvoice', 'ErpDocument', 'http://www.iec.ch/TC57/CIM#', false, 'A roll up of invoice line items. The whole invoice has a due date and amount to be paid, with information such as customer, banks etc. being obtained through associations. The invoice roll up is based on individual line items that each contain amounts and descriptions for specific services or products.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpInvoiceKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ErpInvoiceLineItem', 'ErpDocument', 'http://www.iec.ch/TC57/CIM#', false, 'An individual line item on an invoice.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpInvoiceLineItemKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ErpIssueInventory', 'ErpIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Can be used to request an application to process an issue or request information about an issue.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpItemMaster', 'ErpIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Any unique purchased part for manufactured product tracked by ERP systems for a utility. Item, as used by the OAG, refers to the basic information about an item, including its attributes, cost, and locations. It does not include item quantities. Compare to the Inventory, which includes all quantities and other location-specific information.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpJournal', 'ErpDocument', 'http://www.iec.ch/TC57/CIM#', false, 'Book for recording accounting transactions as they occur. Transactions and adjustments are first recorded in a journal, which is like a diary of instructions, advising which account to be charged and by how much. A journal represents a change in the balances of a business''s financial accounts. Many tasks or transactions throughout an enterprise will result in the creation of a journal. Some examples are creating a customer invoice, paying a vendor, transferring inventory, or paying employees.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpJournalEntry', 'ErpIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Details of an individual entry in a journal, which is to be posted to a ledger on the posting date.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpLedBudLineItem', 'ErpIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Individual entry of a given Ledger Budget, typically containing information such as amount, accounting date, accounting period, and is associated with the applicable general ledger account.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpLedger', 'ErpDocument', 'http://www.iec.ch/TC57/CIM#', false, 'In accounting transactions, a ledger is a book containing accounts to which debits and credits are posted from journals, where transactions are initially recorded. Journal entries are periodically posted to the ledger. Ledger Actual represents actual amounts by account within ledger within company or business area. Actual amounts may be generated in a source application and then loaded to a specific ledger within the enterprise general ledger or budget application.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpLedgerBudget', 'ErpDocument', 'http://www.iec.ch/TC57/CIM#', false, 'Information for utility Ledger Budgets. They support the transfer budget amounts between all possible source applications throughout an enterprise and a general ledger or budget application.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpLedgerEntry', 'ErpIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Details of an individual entry in a ledger, which was posted from a journal on the posted date.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpPOLineItem', 'ErpDocument', 'http://www.iec.ch/TC57/CIM#', false, 'Of an ErpPurchaseOrder, this is an individually ordered item or product along with the quantity, price and other descriptive information.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpPayable', 'ErpDocument', 'http://www.iec.ch/TC57/CIM#', false, 'A transaction that represents an invoice from a supplier. A payable (or voucher) is an open item, approved and ready for payment, in the Accounts Payable ledger.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpPayableLineItem', 'ErpIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Of an ErpPayable, a line item references an ErpInvoiceLineitem or other source such as credit memos.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpPayment', 'ErpDocument', 'http://www.iec.ch/TC57/CIM#', false, 'Payment infromation and status for any individual line item of an ErpInvoice (e.g., when payment is from a customer). ErpPayable is also updated when payment is to a supplier and ErpReceivable is updated when payment is from a customer. Multiple payments can be made against a single line item and an individual payment can apply to more that one line item.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpPersonnel', 'ErpIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Information that applies to the basic data about a utility person, used by ERP applications to transfer Personnel data for a worker.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpProjectAccounting', 'ErpDocument', 'http://www.iec.ch/TC57/CIM#', false, 'Utility Project Accounting information, used by ERP applications to enable all relevant sub-systems that submit single sided transactions to transfer information with a Project Accounting Application. This would include, but not necessarily be limited to: Accounts Payable, Accounts Receivable, Budget, Order Management, Purchasing, Time and Labor, Travel and Expense.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpPurchaseOrder', 'ErpDocument', 'http://www.iec.ch/TC57/CIM#', false, 'A document that communicates an order to purchase goods from a buyer to a supplier. The PurchaseOrder carries information to and from the buyer and supplier. It is a legally binding document once both Parties agree to the contents and the specified terms and conditions of the order.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpQuote', 'ErpDocument', 'http://www.iec.ch/TC57/CIM#', false, 'Document describing the prices of goods or services provided by a supplier. It includes the terms of the purchase, delivery proposals, identification of goods or services ordered, as well as their quantities.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpQuoteLineItem', 'ErpIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Of an ErpQuote, the item or product quoted along with quantity, price and other descriptive information.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpRecDelvLineItem', 'ErpIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Of an ErpReceiveDelivery, this is an individually received good or service by the Organisation receiving goods or services. It may be used to indicate receipt of goods in conjunction with a purchase order line item.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpRecLineItem', 'ErpIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Individual entry of an ErpReceivable, it is a particular transaction representing an invoice, credit memo or debit memo to a customer.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpReceivable', 'ErpDocument', 'http://www.iec.ch/TC57/CIM#', false, 'Transaction representing an invoice, credit memo or debit memo to a customer. It is an open (unpaid) item in the Accounts Receivable ledger.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpReceiveDelivery', 'ErpDocument', 'http://www.iec.ch/TC57/CIM#', false, 'Transaction for an Organisation receiving goods or services that may be used to indicate receipt of goods in conjunction with a purchase order. A receivable is an open (unpaid) item in the Accounts Receivable ledger.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpReqLineItem', 'ErpIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Information that describes a requested item and its attributes.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpRequisition', 'ErpDocument', 'http://www.iec.ch/TC57/CIM#', false, 'General information that applies to a utility requisition that is a request for the purchase of goods or services. Typically, a requisition leads to the creation of a purchase order to a specific supplier.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpSalesOrder', 'ErpDocument', 'http://www.iec.ch/TC57/CIM#', false, 'General purpose Sales Order is used for utility service orders, etc. As used by the OAG, the SalesOrder is a step beyond a PurchaseOrder in that the receiving entity of the order also communicates SalesInformoration about the Order along with the Order itself.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpSiteLevelData', 'ErpIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'For a utility, general information that describes physical locations of organizations or the location codes and their meanings. This enables ERP applications to ensure that the physical location identifiers are synchronized between the business applications.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpTimeEntry', 'ErpIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'An individual entry on an ErpTimeSheet.', 'schema/cim/IEC_CIM.ttl'),
  ('ErpTimeSheet', 'ErpDocument', 'http://www.iec.ch/TC57/CIM#', false, 'Time sheet for employees and contractors. Note that ErpTimeSheet inherits the relationship to ErpPerson from Document.', 'schema/cim/IEC_CIM.ttl'),
  ('ExPostLoss', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Model of ex-post calcultion of MW losses.', 'schema/cim/IEC_CIM.ttl'),
  ('ExPostLossResults', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Model results of ex-post calculation of MW losses. Summarizes loss in two categories losses on the the extra high voltage transmission and total losses. Calculated for each subcontrol area.', 'schema/cim/IEC_CIM.ttl'),
  ('ExPostMarketRegion', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Model of ex-post calculation of cleared MW on a regional basis', 'schema/cim/IEC_CIM.ttl'),
  ('ExPostMarketRegionResults', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Model of expost calculation of cleared MW on a region basis. Includes cleared price', 'schema/cim/IEC_CIM.ttl'),
  ('ExPostPricing', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Model of ex-post pricing of nodes', 'schema/cim/IEC_CIM.ttl'),
  ('ExPostPricingResults', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Model of ex-post pricing of nodes. Includes LMP information, pnode based.', 'schema/cim/IEC_CIM.ttl'),
  ('ExPostResource', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Model of ex-post pricing of resources.', 'schema/cim/IEC_CIM.ttl'),
  ('ExPostResourceResults', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Model of ex-post pricing of resources contains components of LMPs: energy, congestion, loss. Resource based.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcAC1A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Modified IEEE AC1A alternator-supplied rectifier excitation system with different rate feedback source.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcAC2A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Modified IEEE AC2A alternator-supplied rectifier excitation system with different field current limit.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcAC3A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Modified IEEE AC3A alternator-supplied rectifier excitation system with different field current limit.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcAC4A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Modified IEEE AC4A alternator-supplied rectifier excitation system with different minimum controller output.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcAC5A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Modified IEEE AC5A alternator-supplied rectifier excitation system with different minimum controller output.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcAC6A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Modified IEEE AC6A alternator-supplied rectifier excitation system with speed input.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcAC8B', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Modified IEEE AC8B alternator-supplied rectifier excitation system with speed input and input limiter.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcANS', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Italian excitation system. It represents static field voltage or excitation current feedback excitation system.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcAVR1', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Italian excitation system corresponding to IEEE (1968) Type 1 Model. It represents exciter dynamo and electromechanical regulator.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcAVR2', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Italian excitation system corresponding to IEEE (1968) Type 2 Model. It represents alternator and rotating diodes and electromechanic voltage regulators.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcAVR3', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Italian excitation system. It represents exciter dynamo and electric regulator.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcAVR4', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Italian excitation system. It represents static exciter and electric voltage regulator.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcAVR5', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Manual excitation control with field circuit resistance. This model can be used as a very simple representation of manual voltage control.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcAVR7', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'IVO excitation system.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcBBC', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Transformer fed static excitation system (static with ABB regulator). This model represents a static excitation system in which a gated thyristor bridge fed by a transformer at the main generator terminals feeds the main generator directly.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcCZ', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Czech Proportion/Integral Exciter.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcDC1A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Modified IEEE DC1A direct current commutator exciter with speed input and without underexcitation limiters (UEL) inputs.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcDC2A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Modified IEEE DC2A direct current commutator exciters with speed input, one more leg block in feedback loop and without underexcitation limiters (UEL) inputs. DC type 2 excitation system model with added speed multiplier, added lead-lag, and voltage-dependent limits.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcDC3A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'This is modified IEEE DC3A direct current commutator exciters with speed input, and death band. DC old type 4.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcDC3A1', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'This is modified old IEEE type 3 excitation system.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcELIN1', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Static PI transformer fed excitation system: ELIN (VATECH) - simplified model. This model represents an all-static excitation system. A PI voltage controller establishes a desired field current set point for a proportional current controller. The integrator of the PI controller has a follow-up input to match its signal to the present field current. A power system stabilizer with power input is included in the model.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcELIN2', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Detailed Excitation System Model - ELIN (VATECH). This model represents an all-static excitation system. A PI voltage controller establishes a desired field current set point for a proportional current controller. The integrator of the PI controller has a follow-up input to match its signal to the present field current. Power system stabilizer models used in conjunction with this excitation system model: PssELIN2, PssIEEE2B, Pss2B.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcHU', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Hungarian Excitation System Model, with built-in voltage transducer.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEAC1A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type AC1A model. The model represents the field-controlled alternator-rectifier excitation systems designated Type AC1A. These excitation systems consist of an alternator main exciter with non-controlled rectifiers. Reference: IEEE Standard 421.5-2005 Section 6.1.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEAC2A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type AC2A model. The model represents a high initial response field-controlled alternator-rectifier excitation system. The alternator main exciter is used with non-controlled rectifiers. The Type AC2A model is similar to that of Type AC1A except for the inclusion of exciter time constant compensation and exciter field current limiting elements. Reference: IEEE Standard 421.5-2005 Section 6.2.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEAC3A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type AC3A model. The model represents the field-controlled alternator-rectifier excitation systems designated Type AC3A. These excitation systems include an alternator main exciter with non-controlled rectifiers. The exciter employs self-excitation, and the voltage regulator power is derived from the exciter output voltage. Therefore, this system has an additional nonlinearity, simulated by the use of a multiplier whose inputs are the voltage regulator command signal, <b>Va</b>, and the exciter output voltage, <b>Efd</b>, times <b>K</b><b><sub>R</sub></b>. This model is applicable to excitation systems employing static voltage regulators. Reference: IEEE Standard 421.5-2005 Section 6.3.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEAC4A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type AC4A model. The model represents type AC4A alternator-supplied controlled-rectifier excitation system which is quite different from the other type ac systems. This high initial response excitation system utilizes a full thyristor bridge in the exciter output circuit. The voltage regulator controls the firing of the thyristor bridges. The exciter alternator uses an independent voltage regulator to control its output voltage to a constant value. These effects are not modeled; however, transient loading effects on the exciter alternator are included. Reference: IEEE Standard 421.5-2005 Section 6.4.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEAC5A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type AC5A model. The model represents a simplified model for brushless excitation systems. The regulator is supplied from a source, such as a permanent magnet generator, which is not affected by system disturbances. Unlike other ac models, this model uses loaded rather than open circuit exciter saturation data in the same way as it is used for the dc models. Because the model has been widely implemented by the industry, it is sometimes used to represent other types of systems when either detailed data for them are not available or simplified models are required. Reference: IEEE Standard 421.5-2005 Section 6.5.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEAC6A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type AC6A model. The model represents field-controlled alternator-rectifier excitation systems with system-supplied electronic voltage regulators. The maximum output of the regulator, <b><i>V</i></b><b><i><sub>R</sub></i></b>, is a function of terminal voltage, <b><i>V</i></b><b><i><sub>T</sub></i></b>. The field current limiter included in the original model AC6A remains in the 2005 update. Reference: IEEE Standard 421.5-2005 Section 6.6.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEAC7B', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type AC7B model. The model represents excitation systems which consist of an ac alternator with either stationary or rotating rectifiers to produce the dc field requirements. It is an upgrade to earlier ac excitation systems, which replace only the controls but retain the ac alternator and diode rectifier bridge. Reference: IEEE Standard 421.5-2005 Section 6.7. <b>Note: </b>In the IEEE Standard 421.5  2005, the [1 / sT<sub>E</sub>] block is shown as [1 / (1 + sT<sub>E</sub>)], which is incorrect.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEAC8B', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type AC8B model. This model represents a PID voltage regulator with either a brushless exciter or dc exciter. The AVR in this model consists of PID control, with separate constants for the proportional (<b>K</b><b><sub>PR</sub></b>), integral (<b>K</b><b><sub>IR</sub></b>), and derivative (<b>K</b><b><sub>DR</sub></b>) gains. The representation of the brushless exciter (<b>T</b><b><sub>E</sub></b>, <b>K</b><b><sub>E</sub></b>, <b>S</b><b><sub>E</sub></b>, <b>K</b><b><sub>C</sub></b>, <b>K</b><b><sub>D</sub></b>) is similar to the model Type AC2A. The Type AC8B model can be used to represent static voltage regulators applied to brushless excitation systems. Digitally based voltage regulators feeding dc rotating main exciters can be represented with the AC Type AC8B model with the parameters <b>K</b><b><sub>C</sub></b> and <b>K</b><b><sub>D</sub></b> set to 0. For thyristor power stages fed from the generator terminals, the limits <b>V</b><b><sub>RMAX</sub></b> and <b>V</b><b><sub>RMIN</sub></b> should be a function of terminal voltage: <b>V</b><b><sub>T</sub></b> * <b>V</b><b><sub>RMAX</sub></b><sub> </sub>and <b>V</b><b><sub>T</sub></b> * <b>V</b><b><sub>RMIN</sub></b>. Reference: IEEE Standard 421.5-2005 Section 6.8.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEDC1A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type DC1A model. This model represents field-controlled dc commutator exciters with continuously acting voltage regulators (especially the direct-acting rheostatic, rotating amplifier, and magnetic amplifier types). Because this model has been widely implemented by the industry, it is sometimes used to represent other types of systems when detailed data for them are not available or when a simplified model is required. Reference: IEEE Standard 421.5-2005 Section 5.1.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEDC2A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type DC2A model. This model represents represent field-controlled dc commutator exciters with continuously acting voltage regulators having supplies obtained from the generator or auxiliary bus. It differs from the Type DC1A model only in the voltage regulator output limits, which are now proportional to terminal voltage <b>V</b><b><sub>T</sub></b>. It is representative of solid-state replacements for various forms of older mechanical and rotating amplifier regulating equipment connected to dc commutator exciters. Reference: IEEE Standard 421.5-2005 Section 5.2.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEDC3A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type DC3A model. This model represents represent older systems, in particular those dc commutator exciters with non-continuously acting regulators that were commonly used before the development of the continuously acting varieties. These systems respond at basically two different rates, depending upon the magnitude of voltage error. For small errors, adjustment is made periodically with a signal to a motor-operated rheostat. Larger errors cause resistors to be quickly shorted or inserted and a strong forcing signal applied to the exciter. Continuous motion of the motor-operated rheostat occurs for these larger error signals, even though it is bypassed by contactor action. Reference: IEEE Standard 421.5-2005 Section 5.3.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEDC4B', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type DC4B model. These excitation systems utilize a field-controlled dc commutator exciter with a continuously acting voltage regulator having supplies obtained from the generator or auxiliary bus. Reference: IEEE Standard 421.5-2005 Section 5.4.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEST1A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type ST1A model. This model represents systems in which excitation power is supplied through a transformer from the generator terminals (or the units auxiliary bus) and is regulated by a controlled rectifier. The maximum exciter voltage available from such systems is directly related to the generator terminal voltage. Reference: IEEE Standard 421.5-2005 Section 7.1.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEST1AUELselectorKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEST2A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type ST2A model. Some static systems utilize both current and voltage sources (generator terminal quantities) to comprise the power source. The regulator controls the exciter output through controlled saturation of the power transformer components. These compound-source rectifier excitation systems are designated Type ST2A and are represented by ExcIEEEST2A. Reference: IEEE Standard 421.5-2005 Section 7.2.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEST3A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type ST3A model. Some static systems utilize a field voltage control loop to linearize the exciter control characteristic. This also makes the output independent of supply source variations until supply limitations are reached. These systems utilize a variety of controlled-rectifier designs: full thyristor complements or hybrid bridges in either series or shunt configurations. The power source may consist of only a potential source, either fed from the machine terminals or from internal windings. Some designs may have compound power sources utilizing both machine potential and current. These power sources are represented as phasor combinations of machine terminal current and voltage and are accommodated by suitable parameters in model Type ST3A which is represented by ExcIEEEST3A. Reference: IEEE Standard 421.5-2005 Section 7.3.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEST4B', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type ST4B model. This model is a variation of the Type ST3A model, with a proportional plus integral (PI) regulator block replacing the lag-lead regulator characteristic that is in the ST3A model. Both potential and compound source rectifier excitation systems are modeled. The PI regulator blocks have non-windup limits that are represented. The voltage regulator of this model is typically implemented digitally. Reference: IEEE Standard 421.5-2005 Section 7.4.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEST5B', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type ST5B model. The Type ST5B excitation system is a variation of the Type ST1A model, with alternative overexcitation and underexcitation inputs and additional limits. Reference: IEEE Standard 421.5-2005 Section 7.5. Note: the block diagram in the IEEE 421.5 standard has input signal Vc and does not indicate the summation point with Vref. The implementation of the ExcIEEEST5B shall consider summation point with Vref.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEST6B', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type ST6B model. This model consists of a PI voltage regulator with an inner loop field voltage regulator and pre-control. The field voltage regulator implements a proportional control. The pre-control and the delay in the feedback circuit increase the dynamic response. Reference: IEEE Standard 421.5-2005 Section 7.6.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcIEEEST7B', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type ST7B model. This model is representative of static potential-source excitation systems. In this system, the AVR consists of a PI voltage regulator. A phase lead-lag filter in series allows introduction of a derivative function, typically used with brushless excitation systems. In that case, the regulator is of the PID type. In addition, the terminal voltage channel includes a phase lead-lag filter. The AVR includes the appropriate inputs on its reference for overexcitation limiter (OEL1), underexcitation limiter (UEL), stator current limiter (SCL), and current compensator (DROOP). All these limitations, when they work at voltage reference level, keep the PSS (VS signal from Type PSS1A, PSS2A, or PSS2B) in operation. However, the UEL limitation can also be transferred to the high value (HV) gate acting on the output signal. In addition, the output signal passes through a low value (LV) gate for a ceiling overexcitation limiter (OEL2). Reference: IEEE Standard 421.5-2005 Section 7.7.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcOEX3T', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Modified IEEE Type ST1 Excitation System with semi-continuous and acting terminal voltage limiter.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcPIC', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Proportional/Integral Regulator Excitation System Model. This model can be used to represent excitation systems with a proportional-integral (PI) voltage regulator controller.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcREXS', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'General Purpose Rotating Excitation System Model. This model can be used to represent a wide range of excitation systems whose DC power source is an AC or DC generator. It encompasses IEEE type AC1, AC2, DC1, and DC2 excitation system models.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcREXSFeedbackSignalKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ExcSCRX', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Simple excitation system model representing generic characteristics of many excitation systems; intended for use where negative field current may be a problem.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcSEXS', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Simplified Excitation System Model.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcSK', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Slovakian Excitation System Model. UEL and secondary voltage control are included in this model. When this model is used, there cannot be a separate underexcitation limiter or VAr controller model.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcST1A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Modification of an old IEEE ST1A static excitation system without overexcitation limiter (OEL) and underexcitation limiter (UEL).', 'schema/cim/IEC_CIM.ttl'),
  ('ExcST2A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Modified IEEE ST2A static excitation system - another lead-lag block added to match the model defined by WECC.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcST3A', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Modified IEEE ST3A static excitation system with added speed multiplier.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcST4B', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Modified IEEE ST4B static excitation system with maximum inner loop feedback gain <b>Vgmax</b>.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcST6B', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Modified IEEE ST6B static excitation system with PID controller and optional inner feedbacks loop.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcST6BOELselectorKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ExcST7B', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Modified IEEE ST7B static excitation system without stator current limiter (SCL) and current compensator (DROOP) inputs.', 'schema/cim/IEC_CIM.ttl'),
  ('ExcST7BOELselectorKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ExcST7BUELselectorKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ExcitationSystemDynamics', 'DynamicsFunctionBlock', 'http://www.iec.ch/TC57/CIM#', false, 'Excitation system function block whose behavior is described by reference to a standard model <font color="#0f0f0f">or by definition of a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('ExcitationSystemUserDefined', 'ExcitationSystemDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Excitation system function block whose dynamic behaviour is described by <font color="#0f0f0f">a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('Excitation_System', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ExecutionType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ExpectedEnergy', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Model Expected Energy from Market Clearing, interval based', 'schema/cim/IEC_CIM.ttl'),
  ('ExpectedEnergyValues', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Model Expected Energy from Market Clearing', 'schema/cim/IEC_CIM.ttl'),
  ('ExternalCustomerAgreement', 'Agreement', 'http://www.iec.ch/TC57/CIM#', false, 'A type of customer agreement involving an external agency. For example, a customer may form a contracts with an Energy Service Supplier if Direct Access is permitted.', 'schema/cim/IEC_CIM.ttl'),
  ('ExternalNetworkInjection', 'RegulatingCondEq', 'http://www.iec.ch/TC57/CIM#', false, 'This class represents external network and it is used for IEC 60909 calculations.', 'schema/cim/IEC_CIM.ttl'),
  ('FACTSDevice', 'Asset', 'http://www.iec.ch/TC57/CIM#', false, 'FACTS device asset.', 'schema/cim/IEC_CIM.ttl'),
  ('FACTSDeviceKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('FTR', 'Agreement', 'http://www.iec.ch/TC57/CIM#', false, 'Financial Transmission Rights (FTR) regarding transmission capacity at a flowgate.', 'schema/cim/IEC_CIM.ttl'),
  ('Facility', 'AssetContainer', 'http://www.iec.ch/TC57/CIM#', false, 'A facility may contain buildings, storage facilities, switching facilities, power generation, manufacturing facilities, maintenance facilities, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('FailureEvent', 'ActivityRecord', 'http://www.iec.ch/TC57/CIM#', false, 'An event where an asset has failed to perform its functions within specified parameters.', 'schema/cim/IEC_CIM.ttl'),
  ('FailureIsolationMethodKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Fault', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Abnormal condition causing current flow through conducting equipment, such as caused by equipment failure or short circuits from objects not typically modeled (for example, a tree falling on a line).', 'schema/cim/IEC_CIM.ttl'),
  ('FaultCauseType', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Type of cause of the fault.', 'schema/cim/IEC_CIM.ttl'),
  ('FaultImpedance', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Impedance description for the fault.', 'schema/cim/IEC_CIM.ttl'),
  ('FaultIndicator', 'AuxiliaryEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'A FaultIndicator is typically only an indicator (which may or may not be remotely monitored), and not a piece of equipment that actually initiates a protection event. It is used for FLISR (Fault Location, Isolation and Restoration) purposes, assisting with the dispatch of crews to "most likely" part of the network (i.e. assists with determining circuit section where the fault most likely happened).', 'schema/cim/IEC_CIM.ttl'),
  ('FaultIndicatorInfo', 'AssetInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Parameters of fault indicator asset.', 'schema/cim/IEC_CIM.ttl'),
  ('FaultIndicatorResetKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('FieldSafetySupervisor', 'CrewMember', 'http://www.iec.ch/TC57/CIM#', false, 'Crew member on work site responsible for all local safety measures for the work crew doing maintenance, construction and repair in a substation or on a power line/cable.', 'schema/cim/IEC_CIM.ttl'),
  ('FinancialInfo', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Various current financial properties associated with a particular asset. Historical properties may be determined by ActivityRecords associated with the asset.', 'schema/cim/IEC_CIM.ttl'),
  ('FiveMinAuxiliaryData', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Models 5-Minutes Auxillary Data', 'schema/cim/IEC_CIM.ttl'),
  ('FlagTypeRMR', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('FloatQuantity', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Quantity with float value and associated unit information.', 'schema/cim/IEC_CIM.ttl'),
  ('FlowDirection', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'The coded identification of the direction of energy flow.', 'schema/cim/IEC_CIM.ttl'),
  ('FlowDirectionKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('FlowDirectionType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('FlowSensor', 'ConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'Represents a two terminal and power conducting device of negligible impedance that senses flow through the device.', 'schema/cim/IEC_CIM.ttl'),
  ('Flowgate', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'A flowgate, is single or group of transmission elements intended to model MW flow impact relating to transmission limitations and transmission service usage.', 'schema/cim/IEC_CIM.ttl'),
  ('FlowgatePartner', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Flowgate defined partner', 'schema/cim/IEC_CIM.ttl'),
  ('FlowgateRelief', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'IDC (Interchange Distribution Calulator) sends data for a TLR (Transmission Loading Relief).', 'schema/cim/IEC_CIM.ttl'),
  ('FlowgateValue', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Day Ahead, Network Native Load, Economic Dispatch, values used for calculation of Network Native Load (NNL) Determinator process.', 'schema/cim/IEC_CIM.ttl'),
  ('ForbiddenRegion', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Forbbiden region is operating ranges where the units are unable to maintain steady operation without causing equipment damage. The four attributes that define a forbidden region are the low MW, the High MW, the crossing time, and the crossing cost.', 'schema/cim/IEC_CIM.ttl'),
  ('FormerReference', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Used to indicate former references to the same piece of equipment. The ID, name, and effectivity dates are utilized.', 'schema/cim/IEC_CIM.ttl'),
  ('FossilFuel', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The fossil fuel consumed by the non-nuclear thermal generating unit. For example, coal, oil, gas, etc. This a the specific fuels that the generating unit can consume.', 'schema/cim/IEC_CIM.ttl'),
  ('FossilSteamSupply', 'SteamSupply', 'http://www.iec.ch/TC57/CIM#', false, 'Fossil fueled boiler (e.g., coal, oil, gas).', 'schema/cim/IEC_CIM.ttl'),
  ('Frame', 'FrameworkPart', 'http://www.iec.ch/TC57/CIM#', false, 'A region isolated by boundaries.', 'schema/cim/IEC_CIM.ttl'),
  ('FrameworkPart', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The type of alternate model frame. For example, it could be generator group used to represent generators in state estimator, planning, planning dynamics, short circuit, or real-time dynamics etc., but does not specifically represent any one alternative model. This need to know what objects to be removed in the realization of any one alternate model.', 'schema/cim/IEC_CIM.ttl'),
  ('FrancisGovernorControlKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Frequency', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Cycles per second.', 'schema/cim/IEC_CIM.ttl'),
  ('FrequencyConverter', 'RegulatingCondEq', 'http://www.iec.ch/TC57/CIM#', false, 'A device to convert from one frequency to another (e.g., frequency F1 to F2) comprises a pair of FrequencyConverter instances. One converts from F1 to DC, the other converts the DC to F2.', 'schema/cim/IEC_CIM.ttl'),
  ('FuelAllocationSchedule', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'The amount of fuel of a given type which is allocated for consumption over a specified period of time.', 'schema/cim/IEC_CIM.ttl'),
  ('FuelCostCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Relationship between unit fuel cost in $/kWh(Y-axis) and unit output in MW (X-axis).', 'schema/cim/IEC_CIM.ttl'),
  ('FuelRegion', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Indication of region for fuel inventory purposes', 'schema/cim/IEC_CIM.ttl'),
  ('FuelSource', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('FuelType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Fuse', 'Switch', 'http://www.iec.ch/TC57/CIM#', false, 'An overcurrent protective device with a circuit opening fusible part that is heated and severed by the passage of overcurrent through it. A fuse is considered a switching device because it breaks current.', 'schema/cim/IEC_CIM.ttl'),
  ('GasPrice', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Price of gas in monetary units', 'schema/cim/IEC_CIM.ttl'),
  ('Gate', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Logical gate than support logical operation based on the input.', 'schema/cim/IEC_CIM.ttl'),
  ('GateInputPin', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Input pin for a logical gate. The condition described in the input pin will give a logical true or false. Result from measurement and calculation are converted to a true or false.', 'schema/cim/IEC_CIM.ttl'),
  ('GateLogicKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('GenDistributionFactor', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'This class models the generation distribution factors. This class needs to be used along with the AggregatedPnode and the IndividualPnode to show the distriubtion of each individual party.', 'schema/cim/IEC_CIM.ttl'),
  ('GenICompensationForGenJ', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'This class provides the resistive and reactive components of compensation for the generator associated with the IEEE Type 2 voltage compensator for current flow out of one of the other generators in the interconnection.', 'schema/cim/IEC_CIM.ttl'),
  ('GenUnitOpCostCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Relationship between unit operating cost (Y-axis) and unit output active power (X-axis). The operating cost curve for thermal units is derived from heat input and fuel costs. The operating cost curve for hydro units is derived from water flow rates and equivalent water costs.', 'schema/cim/IEC_CIM.ttl'),
  ('GenUnitOpSchedule', 'RegularIntervalSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'The generating unit''s Operator-approved current operating schedule (or plan), typically produced with the aid of unit commitment type analyses. The X-axis represents absolute time. The Y1-axis represents the status (0=off-line and unavailable: 1=available: 2=must run: 3=must run at fixed power value: etc.). The Y2-axis represents the must run fixed power value where required.', 'schema/cim/IEC_CIM.ttl'),
  ('GeneralClearing', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Model of clearing result of the market run at the market level. Identifies interval', 'schema/cim/IEC_CIM.ttl'),
  ('GeneralClearingResults', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Provides the adjusted load forecast value on a load forecast zone basis.', 'schema/cim/IEC_CIM.ttl'),
  ('GeneratingBid', 'ResourceBid', 'http://www.iec.ch/TC57/CIM#', false, 'Offer to supply energy/ancillary services from a generating unit or resource', 'schema/cim/IEC_CIM.ttl'),
  ('GeneratingUnit', 'Equipment', 'http://www.iec.ch/TC57/CIM#', false, 'A single or set of synchronous machines for converting mechanical power into alternating-current power. For example, individual machines within a set may be defined for scheduling purposes while a single control signal is derived for the set. In this case there would be a GeneratingUnit for each member of the set and an additional GeneratingUnit corresponding to the set.', 'schema/cim/IEC_CIM.ttl'),
  ('GeneratingUnitDynamicValues', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Optimal Power Flow or State Estimator Unit Data for Operator Training Simulator. This is used for RealTime, Study and Maintenance Users', 'schema/cim/IEC_CIM.ttl'),
  ('GenerationProvider', 'Organisation', 'http://www.iec.ch/TC57/CIM#', false, 'The energy seller in the energy marketplace.', 'schema/cim/IEC_CIM.ttl'),
  ('GeneratorControlMode', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('GeneratorControlSource', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('GeneratorTypeAsset', 'GenericAssetModel', 'http://www.iec.ch/TC57/CIM#', false, 'Generic generation equipment that may be used for various purposes such as work planning. It defines both the Real and Reactive power properties (modelled at the PSR level as a GeneratingUnit + SynchronousMachine).', 'schema/cim/IEC_CIM.ttl'),
  ('GenericAction', 'SwitchingStep', 'http://www.iec.ch/TC57/CIM#', false, 'An arbitrary switching step.', 'schema/cim/IEC_CIM.ttl'),
  ('GenericAssetModel', 'AssetModel', 'http://www.iec.ch/TC57/CIM#', false, 'Generic asset that may be used for planning, work or design purposes.', 'schema/cim/IEC_CIM.ttl'),
  ('GenericConstraints', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Generic constraints can represent secure areas, voltage profile, transient stability and voltage collapse limits. The generic constraints can be one of the following forms: a) Thermal MW limit constraints type b) Group line flow constraint type', 'schema/cim/IEC_CIM.ttl'),
  ('GenericNonLinearLoadModelKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('GeographicalRegion', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A geographical region of a power system network model.', 'schema/cim/IEC_CIM.ttl'),
  ('GovCT1', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'General model for any prime mover with a PID governor, used primarily for combustion turbine and combined cycle units. This model can be used to represent a variety of prime movers controlled by PID governors. It is suitable, for example, for representation of <ul> <li>gas turbine and single shaft combined cycle turbines </li> </ul> <ul> <li>diesel engines with modern electronic or digital governors </li> </ul> <ul> <li>steam turbines where steam is supplied from a large boiler drum or a large header whose pressure is substantially constant over the period under study </li> <li>simple hydro turbines in dam configurations where the water column length is short and water inertia effects are minimal. </li> </ul> Additional information on this model is available in the 2012 IEEE report, <i><u>Dynamic Models for Turbine-Governors in Power System Studies</u></i>, section 3.1.2.3 page 3-4 (GGOV1).', 'schema/cim/IEC_CIM.ttl'),
  ('GovCT2', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'General governor model with frequency-dependent fuel flow limit. This model is a modification of the GovCT1<b> </b>model in order to represent the frequency-dependent fuel flow limit of a specific gas turbine manufacturer.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Single shaft gas turbine.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST1', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Modified single shaft gas turbine.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST2', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Gas turbine model.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST3', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Generic turbogas with acceleration and temperature controller.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST4', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Generic turbogas.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGASTWD', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Woodward Gas turbine governor model.', 'schema/cim/IEC_CIM.ttl'),
  ('GovHydro1', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Basic Hydro turbine governor model.', 'schema/cim/IEC_CIM.ttl'),
  ('GovHydro2', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'IEEE hydro turbine governor model represents plants with straightforward penstock configurations and hydraulic-dashpot governors.', 'schema/cim/IEC_CIM.ttl'),
  ('GovHydro3', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Modified IEEE Hydro Governor-Turbine Model. This model differs from that defined in the IEEE modeling guideline paper in that the limits on gate position and velocity do not permit "wind up" of the upstream signals.', 'schema/cim/IEC_CIM.ttl'),
  ('GovHydro4', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Hydro turbine and governor. Represents plants with straight-forward penstock configurations and hydraulic governors of traditional ''dashpot'' type. This model can be used to represent simple, Francis, Pelton or Kaplan turbines.', 'schema/cim/IEC_CIM.ttl'),
  ('GovHydroDD', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Double derivative hydro governor and turbine.', 'schema/cim/IEC_CIM.ttl'),
  ('GovHydroFrancis', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Detailed hydro unit - Francis model. This model can be used to represent three types of governors. A schematic of the hydraulic system of detailed hydro unit models, like Francis and Pelton, is provided in the DetailedHydroModelHydraulicSystem diagram.', 'schema/cim/IEC_CIM.ttl'),
  ('GovHydroIEEE0', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'IEEE Simplified Hydro Governor-Turbine Model. Used for Mechanical-Hydraulic and Electro-Hydraulic turbine governors, with our without steam feedback. Typical values given are for Mechanical-Hydraulic. Ref<font color="#0f0f0f">erence: IEEE Transactions on Power Apparatus and Systems</font> <font color="#0f0f0f">November/December 1973, Volume PAS-92, Number 6</font> <font color="#0f0f0f"><i><u>Dynamic Models for Steam and Hydro Turbines in Power System Studies</u></i>, Page 1904.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('GovHydroIEEE2', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'IEEE hydro turbine governor model represents plants with straightforward penstock configurations and hydraulic-dashpot governors. Ref<font color="#0f0f0f">erence: IEEE Transactions on Power Apparatus and Systems</font> <font color="#0f0f0f">November/December 1973, Volume PAS-92, Number 6</font> <font color="#0f0f0f"><i><u>Dynamic Models for Steam and Hydro Turbines in Power System Studies</u></i>, Page 1904.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('GovHydroPID', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'PID governor and turbine.', 'schema/cim/IEC_CIM.ttl'),
  ('GovHydroPID2', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Hydro turbine and governor. Represents plants with straight forward penstock configurations and "three term" electro-hydraulic governors (i.e. Woodard electronic).', 'schema/cim/IEC_CIM.ttl'),
  ('GovHydroPelton', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Detailed hydro unit - Pelton model. This model can be used to represent the dynamic related to water tunnel and surge chamber. A schematic of the hydraulic system of detailed hydro unit models, like Francis and Pelton, is located under the GovHydroFrancis class.', 'schema/cim/IEC_CIM.ttl'),
  ('GovHydroR', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Fourth order lead-lag governor and hydro turbine.', 'schema/cim/IEC_CIM.ttl'),
  ('GovHydroWEH', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Woodward Electric Hydro Governor Model.', 'schema/cim/IEC_CIM.ttl'),
  ('GovHydroWPID', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Woodward PID Hydro Governor.', 'schema/cim/IEC_CIM.ttl'),
  ('GovSteam0', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'A simplified steam turbine governor model.', 'schema/cim/IEC_CIM.ttl'),
  ('GovSteam1', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Steam turbine governor model, based on the GovSteamIEEE1 model (with optional deadband and nonlinear valve gain added).', 'schema/cim/IEC_CIM.ttl'),
  ('GovSteam2', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Simplified governor model.', 'schema/cim/IEC_CIM.ttl'),
  ('GovSteamCC', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Cross compound turbine governor model.', 'schema/cim/IEC_CIM.ttl'),
  ('GovSteamEU', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Simplified model of boiler and steam turbine with PID governor.', 'schema/cim/IEC_CIM.ttl'),
  ('GovSteamFV2', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Steam turbine governor with reheat time constants and modeling of the effects of fast valve closing to reduce mechanical power.', 'schema/cim/IEC_CIM.ttl'),
  ('GovSteamFV3', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Simplified GovSteamIEEE1 Steam turbine governor model with Prmax limit and fast valving.', 'schema/cim/IEC_CIM.ttl'),
  ('GovSteamFV4', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Detailed electro-hydraulic governor for steam unit.', 'schema/cim/IEC_CIM.ttl'),
  ('GovSteamIEEE1', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'IEEE steam turbine governor model. Ref<font color="#0f0f0f">erence: IEEE Transactions on Power Apparatus and Systems</font> <font color="#0f0f0f">November/December 1973, Volume PAS-92, Number 6</font> <font color="#0f0f0f"><i><u>Dynamic Models for Steam and Hydro Turbines in Power System Studies</u></i>, Page 1904.</font> <b>Parameter Notes:</b> <ol> <li>Per unit parameters are on base of <b>MWbase</b>, which is normally the MW capability of the turbine.</li> <li><b>T3</b> must be greater than zero. All other time constants may be zero.</li> <li>For a tandem-compound turbine the parameters <b>K2</b>, <b>K4</b>, <b>K6</b>, and <b>K8</b> are ignored. For a cross-compound turbine, two generators are connected to this turbine-governor model.</li> <li>Each generator must be represented in the load flow by data on its own MVA base. The values of <b>K1</b>, <b>K3</b>, <b>K5</b>, <b>K7</b> must be specified to describe the proportionate development of power on the first turbine shaft. <b>K2</b>, <b>K4</b>, <b>K6</b>, <b>K8</b> must describe the second turbine shaft. Normally <b>K1</b> + <b>K3</b> + <b>K5</b> + <b>K7</b> = 1.0 and <b>K2</b> + <b>K4</b> + <b>K6</b> + <b>K8</b> = 1.0 (if second generator is present).</li> <li>The division of power between the two shafts is in proportion to the values of MVA bases of the two generators. The initial condition load flow should, therefore, have the two generators loaded to the same fraction of each ones MVA base.</li> </ol>', 'schema/cim/IEC_CIM.ttl'),
  ('GovSteamSGO', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Simplified Steam turbine governor model.', 'schema/cim/IEC_CIM.ttl'),
  ('GrossToNetActivePowerCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Relationship between the generating unit''s gross active power output on the X-axis (measured at the terminals of the machine(s)) and the generating unit''s net active power output on the Y-axis (based on utility-defined measurements at the power station). Station service loads, when modeled, should be treated as non-conforming bus loads. There may be more than one curve, depending on the auxiliary equipment that is in service.', 'schema/cim/IEC_CIM.ttl'),
  ('Ground', 'ConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'A point where the system is grounded used for connecting conducting equipment to ground. The power system model can have any number of grounds.', 'schema/cim/IEC_CIM.ttl'),
  ('GroundAction', 'SwitchingStep', 'http://www.iec.ch/TC57/CIM#', false, 'Action on ground as a switching step.', 'schema/cim/IEC_CIM.ttl'),
  ('GroundDisconnector', 'Switch', 'http://www.iec.ch/TC57/CIM#', false, 'A manually operated or motor operated mechanical switching device used for isolating a circuit or equipment from ground.', 'schema/cim/IEC_CIM.ttl'),
  ('GroundingImpedance', 'EarthFaultCompensator', 'http://www.iec.ch/TC57/CIM#', false, 'A fixed impedance device used for grounding.', 'schema/cim/IEC_CIM.ttl'),
  ('Hazard', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'An object or a condition that is a danger for causing loss or perils to an asset and/or people.', 'schema/cim/IEC_CIM.ttl'),
  ('HeatInputCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Relationship between unit heat input in energy per time for main fuel (Y1-axis) and supplemental fuel (Y2-axis) versus unit output in active power (X-axis). The quantity of main fuel used to sustain generation at this output level is prorated for throttling between definition points. The quantity of supplemental fuel used at this output level is fixed and not prorated.', 'schema/cim/IEC_CIM.ttl'),
  ('HeatRate', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Heat generated, in energy pertime unit of elapsed time.', 'schema/cim/IEC_CIM.ttl'),
  ('HeatRateCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Relationship between unit heat rate per active power (Y-axis) and unit output (X-axis). The heat input is from all fuels.', 'schema/cim/IEC_CIM.ttl'),
  ('HeatRecoveryBoiler', 'FossilSteamSupply', 'http://www.iec.ch/TC57/CIM#', false, 'The heat recovery system associated with combustion turbines in order to produce steam for combined cycle plants.', 'schema/cim/IEC_CIM.ttl'),
  ('HostControlArea', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'A HostControlArea has a set of tie points and a set of generator controls (i.e., AGC). It also has a total load, including transmission and distribution losses.', 'schema/cim/IEC_CIM.ttl'),
  ('HourlyPreDispatchSchedule', 'BidHourlySchedule', 'http://www.iec.ch/TC57/CIM#', false, 'An indicator specifying that a resource shall have an Hourly Pre-Dispatch. The resource could be a RegisteredGenerator or a RegisteredInterTie. This schedule is assocated with the hourly parameters in a resource bid.', 'schema/cim/IEC_CIM.ttl'),
  ('Hours', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Time specified in hours.', 'schema/cim/IEC_CIM.ttl'),
  ('HydroEnergyConversionKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('HydroGeneratingEfficiencyCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Relationship between unit efficiency in percent and unit output active power for a given net head in meters. The relationship between efficiency, discharge, head, and power output is expressed as follows: E =KP/HQ Where: (E=percentage) (P=active power) (H=height) (Q=volume/time unit) (K=constant) For example, a curve instance for a given net head could relate efficiency (Y-axis) versus active power output (X-axis) or versus discharge on the X-axis.', 'schema/cim/IEC_CIM.ttl'),
  ('HydroGeneratingUnit', 'GeneratingUnit', 'http://www.iec.ch/TC57/CIM#', false, 'A generating unit whose prime mover is a hydraulic turbine (e.g., Francis, Pelton, Kaplan).', 'schema/cim/IEC_CIM.ttl'),
  ('HydroPlantStorageKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('HydroPowerPlant', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'A hydro power station which can generate or pump. When generating, the generator turbines receive water from an upper reservoir. When pumping, the pumps receive their water from a lower reservoir.', 'schema/cim/IEC_CIM.ttl'),
  ('HydroPump', 'Equipment', 'http://www.iec.ch/TC57/CIM#', false, 'A synchronous motor-driven pump, typically associated with a pumped storage plant.', 'schema/cim/IEC_CIM.ttl'),
  ('HydroPumpOpSchedule', 'RegularIntervalSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'The hydro pump''s Operator-approved current operating schedule (or plan), typically produced with the aid of unit commitment type analyses.The unit''s operating schedule status is typically given as: (0=unavailable) (1=avilable to startup or shutdown) (2=must pump).', 'schema/cim/IEC_CIM.ttl'),
  ('HydroTurbine', 'PrimeMover', 'http://www.iec.ch/TC57/CIM#', false, 'A water driven prime mover. Typical turbine types are: Francis, Kaplan, and Pelton.', 'schema/cim/IEC_CIM.ttl'),
  ('ICCPCommandPoint', 'ICCPControlPoint', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ICCPControlPoint', 'ICCPPoint', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ICCPControlPointDeviceClass', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ICCPIndicationPoint', 'ICCPPoint', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ICCPIndicationPointType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ICCPInformationMessage', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'This class represents the TASE.2 Information Message Object. The IdentifiedObject.name attribute must be non-null. The value of the attribute shall be used as the TASE.2 Information Reference, as specified by 60870-6-503.', 'schema/cim/IEC_CIM.ttl'),
  ('ICCPPScope', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ICCPPoint', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The IdentifiedObject.name attribute must have a value. The name attribute shall be used as the DataValue name used for the exchange.', 'schema/cim/IEC_CIM.ttl'),
  ('ICCPSetPoint', 'ICCPControlPoint', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ICCPSetPointType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('IEC61968', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('IEC61968CIMVersion', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'IEC 61968 version number assigned to this UML model.', 'schema/cim/IEC_CIM.ttl'),
  ('IEC61970', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('IEC61970CIMVersion', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'This is the IEC 61970 CIM version number assigned to this UML model.', 'schema/cim/IEC_CIM.ttl'),
  ('IEC62325', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('IEC62325CIMVersion', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'IEC 62325 version number assigned to this UML model.', 'schema/cim/IEC_CIM.ttl'),
  ('IPAccessPoint', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('IPAddressType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ISOAPAddressing', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ISOUpperLayer', 'TCPAcessPoint', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('IdentifiedObject', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'This is a root class to provide common identification for all classes needing identification and naming attributes.', 'schema/cim/IEC_CIM.ttl'),
  ('IfdBaseKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Impedance', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Ratio of voltage to current.', 'schema/cim/IEC_CIM.ttl'),
  ('InadvertentAccount', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'An account for tracking inadvertent interchange versus time for each control area. A control area may have more than one inadvertent account in order to track inadvertent over one or more specific tie points in addition to the usual overall net inadvertent. Separate accounts would also be used to track designated time periods, such as on-peak and off-peak.', 'schema/cim/IEC_CIM.ttl'),
  ('Incident', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Description of a problem in the field that may be reported in a trouble ticket or come from another source. It may have to do with an outage.', 'schema/cim/IEC_CIM.ttl'),
  ('IncidentHazard', 'Hazard', 'http://www.iec.ch/TC57/CIM#', false, 'Hazardous situation associated with an incident. Examples are line down, gas leak, fire, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('IncrementalCIMDataObject', 'CIMDataObject', 'http://www.iec.ch/TC57/CIM#', false, 'A CRUD style CIM data object.', 'schema/cim/IEC_CIM.ttl'),
  ('IncrementalDataset', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Describes a set of changes that can be applied in different situations. A given registered MRID may only be referenced once by the contained data objects, except a precondition may also reference the same registered MRID.', 'schema/cim/IEC_CIM.ttl'),
  ('IncrementalDatasetArg', 'ModelOperationArg', 'http://www.iec.ch/TC57/CIM#', false, 'A generic model operation argument referencing an incremental change description.', 'schema/cim/IEC_CIM.ttl'),
  ('IncrementalDatasetArgDescription', 'ModelOperationArgDescription', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('IncrementalHeatRateCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Relationship between unit incremental heat rate in (delta energy/time) per (delta active power) and unit output in active power. The IHR curve represents the slope of the HeatInputCurve. Note that the "incremental heat rate" and the "heat rate" have the same engineering units.', 'schema/cim/IEC_CIM.ttl'),
  ('IndividualPnode', 'Pnode', 'http://www.iec.ch/TC57/CIM#', false, 'Individual pricing node based on Pnode', 'schema/cim/IEC_CIM.ttl'),
  ('Inductance', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Inductive part of reactance (imaginary part of impedance), at rated frequency.', 'schema/cim/IEC_CIM.ttl'),
  ('InductancePerLength', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Inductance per unit of length.', 'schema/cim/IEC_CIM.ttl'),
  ('InflowForecast', 'RegularIntervalSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'Natural water inflow to a reservoir, usually forecasted from predicted rain and snowmelt. Typically in one hour increments for up to 10 days. The forecast is given in average cubic meters per second over the time increment.', 'schema/cim/IEC_CIM.ttl'),
  ('InfoQuestion', 'WorkDocument', 'http://www.iec.ch/TC57/CIM#', false, 'Questions and answers associated with a type of document for purposes of clarification. Questions may be predefined or ad hoc.', 'schema/cim/IEC_CIM.ttl'),
  ('InputSignalKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('InspectionDataSet', 'ProcedureDataSet', 'http://www.iec.ch/TC57/CIM#', false, 'Documents the result of one inspection, for a given attribute of an asset.', 'schema/cim/IEC_CIM.ttl'),
  ('InstructionClearing', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Model of market clearing, relating to commitment instructions. Identifies interval', 'schema/cim/IEC_CIM.ttl'),
  ('InstructionClearingDOP', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Model of market clearing, related to Dispatch Operating Point. Identifies interval', 'schema/cim/IEC_CIM.ttl'),
  ('InstructionClearingDOT', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Model of market clearing, related to Dispatch Operating Target (model of anticipatory dispatch). Identifies interval', 'schema/cim/IEC_CIM.ttl'),
  ('Instructions', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Provides the necessary information (on a resource basis) to capture the Startup/Shutdown instruction results. This information is relevant to the DA Market (RUC only) as well as the RT Market (HASP, Pre-dispatch, and Interval).', 'schema/cim/IEC_CIM.ttl'),
  ('IntSchedAgreement', 'Agreement', 'http://www.iec.ch/TC57/CIM#', false, 'A type of agreement that provides the default method by which interchange schedules are to be integrated to obtain hourly MWh schedules for accounting.', 'schema/cim/IEC_CIM.ttl'),
  ('IntegerQuantity', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Quantity with integer value and associated unit information.', 'schema/cim/IEC_CIM.ttl'),
  ('InterTieBid', 'ResourceBid', 'http://www.iec.ch/TC57/CIM#', false, 'This class represents the inter tie bid', 'schema/cim/IEC_CIM.ttl'),
  ('InterTieClearing', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Model of market clearing related to results at the inter-ties. Identifies interval', 'schema/cim/IEC_CIM.ttl'),
  ('InterTieDirection', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('InterTieDispatchResponse', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Response from an intertie resource acknowleging receipt of dispatch instructions', 'schema/cim/IEC_CIM.ttl'),
  ('InterTieResults', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Provides the tie point specific output from the market applications. Currently, this is defined as the loop flow compensation MW value.', 'schema/cim/IEC_CIM.ttl'),
  ('InterchangeETCData', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Existing Transmission Contract data for an interchange schedule', 'schema/cim/IEC_CIM.ttl'),
  ('InterchangeSchedule', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Interchange schedule class to hold information for interchange schedules such as import export type, energy type, and etc.', 'schema/cim/IEC_CIM.ttl'),
  ('IntermittentResourceEligibility', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Indicates whether unit is eligible for treatment as a intermittent variable renewable resource', 'schema/cim/IEC_CIM.ttl'),
  ('InternalControlArea', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'There is one internal control area in the system, which is the single control area in the primary network company. Real time generation control affects only the internal control area.', 'schema/cim/IEC_CIM.ttl'),
  ('IntervalBlock', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Time sequence of readings of the same reading type. Contained interval readings may need conversion through the application of an offset and a scalar defined in associated pending.', 'schema/cim/IEC_CIM.ttl'),
  ('IntervalReading', 'BaseReading', 'http://www.iec.ch/TC57/CIM#', false, 'Data captured at regular intervals of time. Interval data could be captured as incremental data, absolute data, or relative data. The source for the data is usually a tariff quantity or an engineering quantity. Data is typically captured in time-tagged, uniform, fixed-length intervals of 5 min, 10 min, 15 min, 30 min, or 60 min. Note: Interval Data is sometimes also called "Interval Data Readings" (IDR).', 'schema/cim/IEC_CIM.ttl'),
  ('IrregularIntervalSchedule', 'BasicIntervalSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'The schedule has time points where the time between them varies.', 'schema/cim/IEC_CIM.ttl'),
  ('IrregularTimePoint', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'TimePoints for a schedule where the time between the points varies.', 'schema/cim/IEC_CIM.ttl'),
  ('Issuer', 'DocumentPersonRole', 'http://www.iec.ch/TC57/CIM#', false, 'Person who issued the document and is responsible for its content.', 'schema/cim/IEC_CIM.ttl'),
  ('JobFlagType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('JobScheduleType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('JobStartEndType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Joint', 'Asset', 'http://www.iec.ch/TC57/CIM#', false, 'Joint connects two or more cables. It includes the portion of cable under wipes, welds, or other seals.', 'schema/cim/IEC_CIM.ttl'),
  ('JointConfigurationKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('JointFillKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Jumper', 'Switch', 'http://www.iec.ch/TC57/CIM#', false, 'A short section of conductor with negligible impedance which can be manually removed and replaced if the circuit is de-energized. Note that zero-impedance branches can potentially be modeled by other equipment types.', 'schema/cim/IEC_CIM.ttl'),
  ('JumperAction', 'SwitchingStep', 'http://www.iec.ch/TC57/CIM#', false, 'Action on jumper as a switching step.', 'schema/cim/IEC_CIM.ttl'),
  ('Junction', 'Connector', 'http://www.iec.ch/TC57/CIM#', false, 'A point where one or more conducting equipments are connected with zero resistance.', 'schema/cim/IEC_CIM.ttl'),
  ('KiloActivePower', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Active power in kilowatts.', 'schema/cim/IEC_CIM.ttl'),
  ('LFCResourceType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('LaborItem', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Labor used for work order.', 'schema/cim/IEC_CIM.ttl'),
  ('LandProperty', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Information about a particular piece of (land) property such as its use. Ownership of the property may be determined through associations to Organisations and/or ErpPersons.', 'schema/cim/IEC_CIM.ttl'),
  ('LandPropertyKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Legend', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Length', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Unit of length. Never negative.', 'schema/cim/IEC_CIM.ttl'),
  ('LevelVsVolumeCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Relationship between reservoir volume and reservoir level. The volume is at the y-axis and the reservoir level at the x-axis.', 'schema/cim/IEC_CIM.ttl'),
  ('LifecycleDate', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Dates for lifecycle events of an asset.', 'schema/cim/IEC_CIM.ttl'),
  ('Limit', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Specifies one limit value for a Measurement. A Measurement typically has several limits that are kept together by the LimitSet class. The actual meaning and use of a Limit instance (i.e., if it is an alarm or warning limit or if it is a high or low limit) is not captured in the Limit class. However the name of a Limit instance may indicate both meaning and use.', 'schema/cim/IEC_CIM.ttl'),
  ('LimitDependency', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A limit calculation model used to compute an operational limit based on external input such as temperature. These are intended to be shared among operational limits with the same calculation form that apply to a piece of equipment..', 'schema/cim/IEC_CIM.ttl'),
  ('LimitScalingLimit', 'LimitDependency', 'http://www.iec.ch/TC57/CIM#', false, 'Specifies an operational limit is calculated by scaling another operational limit.', 'schema/cim/IEC_CIM.ttl'),
  ('LimitSet', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Specifies a set of Limits that are associated with a Measurement. A Measurement may have several LimitSets corresponding to seasonal or other changing conditions. The condition is captured in the name and description attributes. The same LimitSet may be used for several Measurements. In particular percentage limits are used this way.', 'schema/cim/IEC_CIM.ttl'),
  ('Line', 'EquipmentContainer', 'http://www.iec.ch/TC57/CIM#', false, 'Contains equipment beyond a substation belonging to a power transmission line.', 'schema/cim/IEC_CIM.ttl'),
  ('LineDetail', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Details on an amount line, with rounding, date and note.', 'schema/cim/IEC_CIM.ttl'),
  ('LineFault', 'Fault', 'http://www.iec.ch/TC57/CIM#', false, 'A fault that occurs on an AC line segment at some point along the length.', 'schema/cim/IEC_CIM.ttl'),
  ('LinearAssets', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('LinearShuntCompensator', 'ShuntCompensator', 'http://www.iec.ch/TC57/CIM#', false, 'A linear shunt compensator has banks or sections with equal admittance values.', 'schema/cim/IEC_CIM.ttl'),
  ('LinearShuntCompensatorPhase', 'ShuntCompensatorPhase', 'http://www.iec.ch/TC57/CIM#', false, 'A per phase linear shunt compensator has banks or sections with equal admittance values.', 'schema/cim/IEC_CIM.ttl'),
  ('LoadAggregate', 'LoadDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Standard aggregate load model comprised of static and/or dynamic components. A static load model represents the sensitivity of the real and reactive power consumed by the load to the amplitude and frequency of the bus voltage. A dynamic load model can used to represent the aggregate response of the motor components of the load.', 'schema/cim/IEC_CIM.ttl'),
  ('LoadAggregationPoint', 'AggregateNode', 'http://www.iec.ch/TC57/CIM#', false, 'A specialized class of type AggregatedNode type. Defines Load Aggregation Points.', 'schema/cim/IEC_CIM.ttl'),
  ('LoadArea', 'EnergyArea', 'http://www.iec.ch/TC57/CIM#', false, 'The class is the root or first level in a hierarchical structure for grouping of loads for the purpose of load flow load scaling.', 'schema/cim/IEC_CIM.ttl'),
  ('LoadBid', 'ResourceBid', 'http://www.iec.ch/TC57/CIM#', false, 'Offer to supply energy/ancillary services from a load resource (participating load reduces consumption)', 'schema/cim/IEC_CIM.ttl'),
  ('LoadBreakSwitch', 'ProtectedSwitch', 'http://www.iec.ch/TC57/CIM#', false, 'A mechanical switching device capable of making, carrying, and breaking currents under normal operating conditions.', 'schema/cim/IEC_CIM.ttl'),
  ('LoadComposite', 'LoadDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'This models combines static load and induction motor load effects. The dynamics of the motor are simplified by linearizing the induction machine equations.', 'schema/cim/IEC_CIM.ttl'),
  ('LoadDistributionFactor', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'This class models the load distribution factors. This class should be used in one of two ways: Use it along with the AggregatedPnode and the IndividualPnode to show the distriubtion of each individual party OR Use it with Mkt_EnergyConsumer to represent the current MW/Mvar distribution within it''s parnet load group.', 'schema/cim/IEC_CIM.ttl'),
  ('LoadDynamics', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Load whose behaviour is described by reference to a standard model <font color="#0f0f0f">or by definition of a user-defined model.</font> A standard feature of dynamic load behaviour modelling is the ability to associate the same behaviour to multiple energy consumers by means of a single aggregate load definition. Aggregate loads are used to represent all or part of the real and reactive load from one or more loads in the static (power flow) data. This load is usually the aggregation of many individual load devices and the load model is approximate representation of the aggregate response of the load devices to system disturbances. The load model is always applied to individual bus loads (energy consumers) but a single set of load model parameters can used for all loads in the grouping.', 'schema/cim/IEC_CIM.ttl'),
  ('LoadFollowingCapacityType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('LoadFollowingInst', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Metered SubSystem Load Following Instruction', 'schema/cim/IEC_CIM.ttl'),
  ('LoadFollowingOperatorInput', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Model of load following capabilities that are entered by operators on a temporary basis. Related to Registered Resources in Metered Subsystems', 'schema/cim/IEC_CIM.ttl'),
  ('LoadForecastType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('LoadGenericNonLinear', 'LoadDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'These load models (known also as generic non-linear dynamic (GNLD) load models) can be used in mid-term and long-term voltage stability simulations (i.e., to study voltage collapse), as they can replace a more detailed representation of aggregate load, including induction motors, thermostatically controlled and static loads.', 'schema/cim/IEC_CIM.ttl'),
  ('LoadGroup', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The class is the third level in a hierarchical structure for grouping of loads for the purpose of load flow load scaling.', 'schema/cim/IEC_CIM.ttl'),
  ('LoadMotor', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Aggregate induction motor load. This model is used to represent a fraction of an ordinary load as "induction motor load". It allows load that is treated as ordinary constant power in power flow analysis to be represented by an induction motor in dynamic simulation. If <b>Lpp</b> = 0. or <b>Lpp</b> = <b>Lp</b>, or <b>Tppo</b> = 0., only one cage is represented. Magnetic saturation is not modelled. Either a "one-cage" or "two-cage" model of the induction machine can be modelled. Magnetic saturation is not modelled. This model is intended for representation of aggregations of many motors dispersed through a load represented at a high voltage bus but where there is no information on the characteristics of individual motors. This model treats a fraction of the constant power part of a load as a motor. During initialisation, the initial power drawn by the motor is set equal to <b>Pfrac</b> times the constant <b>P</b> part of the static load. The remainder of the load is left as static load. The reactive power demand of the motor is calculated during initialisation as a function of voltage at the load bus. This reactive power demand may be less than or greater than the constant <b>Q</b> component of the load. If the motor''s reactive demand is greater than the constant <b>Q</b> component of the load, the model inserts a shunt capacitor at the terminal of the motor to bring its reactive demand down to equal the constant <b>Q</b> reactive load. If a motor model and a static load model are both present for a load, the motor <b>Pfrac</b> is assumed to be subtracted from the power flow constant <b>P</b> load before the static load model is applied. The remainder of the load, if any, is then represented by the static load model.', 'schema/cim/IEC_CIM.ttl'),
  ('LoadRatio', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Representing the ratio of the load share for the associated SC.', 'schema/cim/IEC_CIM.ttl'),
  ('LoadReductionPriceCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'This is the price sensitivity that bidder expresses for allowing market load interruption. Relationship between price (Y1-axis) vs. MW (X-axis).', 'schema/cim/IEC_CIM.ttl'),
  ('LoadReductionTimeCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'This is the cureve that describes the load reduction time. Relationship between time (Y1-axis) vs. MW (X-axis).', 'schema/cim/IEC_CIM.ttl'),
  ('LoadResponseCharacteristic', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Models the characteristic response of the load demand due to changes in system conditions such as voltage and frequency. This is not related to demand response. If LoadResponseCharacteristic.exponentModel is True, the voltage exponents are specified and used as to calculate: Active power component = Pnominal * (Voltage/cim:BaseVoltage.nominalVoltage) ** cim:LoadResponseCharacteristic.pVoltageExponent Reactive power component = Qnominal * (Voltage/cim:BaseVoltage.nominalVoltage)** cim:LoadResponseCharacteristic.qVoltageExponent Where * means "multiply" and ** is "raised to power of".', 'schema/cim/IEC_CIM.ttl'),
  ('LoadStatic', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'General static load model representing the sensitivity of the real and reactive power consumed by the load to the amplitude and frequency of the bus voltage.', 'schema/cim/IEC_CIM.ttl'),
  ('LoadUserDefined', 'LoadDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Load whose dynamic behaviour is described by a user-defined model.', 'schema/cim/IEC_CIM.ttl'),
  ('LocalReliabilityArea', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Allows definition of reliablity areas (eg load pockets) within the ISO/RTO', 'schema/cim/IEC_CIM.ttl'),
  ('Location', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The place, scene, or point of something where someone or something has been, is, and/or will be at a given moment in time. It can be defined with one or more postition points (coordinates) in a given coordinate system.', 'schema/cim/IEC_CIM.ttl'),
  ('LocationGrant', 'Agreement', 'http://www.iec.ch/TC57/CIM#', false, 'A grant provides a right, as defined by type, for a parcel of land. Note that the association to Location, Asset, Organisation, etc. for the Grant is inherited from Agreement, a type of Document.', 'schema/cim/IEC_CIM.ttl'),
  ('LossClearing', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'RT only and is published on 5 minute intervals for the previous RT time interval results.', 'schema/cim/IEC_CIM.ttl'),
  ('LossClearingResults', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Provides the MW loss for RUC Zones, subcontrol areas, and the total loss.', 'schema/cim/IEC_CIM.ttl'),
  ('LossProfile', 'Profile', 'http://www.iec.ch/TC57/CIM#', false, 'LossProfile is associated with an EnerrgyTransaction and must be completely contained within the time frame of the EnergyProfile associated with this EnergyTransaction.', 'schema/cim/IEC_CIM.ttl'),
  ('LossSensitivity', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Loss sensitivity applied to a ConnectivityNode for a given time interval.', 'schema/cim/IEC_CIM.ttl'),
  ('MPMClearing', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Model of results of Market Power tests, and possible mitigation. Interval based', 'schema/cim/IEC_CIM.ttl'),
  ('MPMResourceStatus', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Model of results of Market Power tests, gives status of resource for the associated interval', 'schema/cim/IEC_CIM.ttl'),
  ('MPMTestCategory', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Provides a reference to the Market Power Mitigation test identifiers and methods for the results of the DA or RT markets. Specific data is the test identifier (Price, Conduct, or Impact) and the test method (System MPM, Local MPM, Alternate System MPM, or Alternate Local MPM).', 'schema/cim/IEC_CIM.ttl'),
  ('MPMTestIdentifierType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MPMTestMethodType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MPMTestOutcome', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MPMTestResults', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Provides the outcome and margin percent (as appropriate) result data for the MPM tests. There are relationships to Zone for Designated Congestion Area Tests, CurveSchedData for bid segment tests, to the SubControlArea for the system wide level tests, and Pnodes for the LMPM impact tests.', 'schema/cim/IEC_CIM.ttl'),
  ('MPMTestThreshold', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Market Power Mitigation (MPM) test thresholds for resource as well as designated congestion areas (DCAs)', 'schema/cim/IEC_CIM.ttl'),
  ('MQSCHGType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl');
INSERT INTO metadata.cim_ref_classes (name, parent_name, namespace, is_abstract, description, source) VALUES
  ('MQSDELType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MQSInstructionSource', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MSSAggregation', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Metered Sub-System aggregation of MSS Zones.', 'schema/cim/IEC_CIM.ttl'),
  ('MSSZone', 'AggregateNode', 'http://www.iec.ch/TC57/CIM#', false, 'Model to define a zone within a Metered Sub System', 'schema/cim/IEC_CIM.ttl'),
  ('MWLimitSchedule', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Maximum MW and optionally Minimum MW (Y1 and Y2, respectively)', 'schema/cim/IEC_CIM.ttl'),
  ('MacroPeriodKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Maintainer', 'AssetOrganisationRole', 'http://www.iec.ch/TC57/CIM#', false, 'Organisation that maintains assets.', 'schema/cim/IEC_CIM.ttl'),
  ('MaintenanceDataSet', 'ProcedureDataSet', 'http://www.iec.ch/TC57/CIM#', false, 'The result of a maintenance activity, a type of Procedure, for a given attribute of an asset.', 'schema/cim/IEC_CIM.ttl'),
  ('MaintenanceLocation', 'WorkLocation', 'http://www.iec.ch/TC57/CIM#', false, 'Location where to perform maintenance work.', 'schema/cim/IEC_CIM.ttl'),
  ('MajorChargeGroup', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A Major Charge Group is the same as Invocie Type which provides the highest level of grouping for charge types configration. Examples as Market, FERC, RMR,', 'schema/cim/IEC_CIM.ttl'),
  ('Manufacturer', 'OrganisationRole', 'http://www.iec.ch/TC57/CIM#', false, 'Organisation that manufactures asset products.', 'schema/cim/IEC_CIM.ttl'),
  ('Market', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Market (e.g. Day Ahead Market, RealTime Market) with a description of the the Market operation control parameters.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketActualEvent', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'This class represent the actual instance of an event.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketAgreement', 'MarketDocument', 'http://www.iec.ch/TC57/CIM#', false, 'An identification or eventually the contents of an agreement between two or more parties.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketCaseClearing', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Market case clearing results are posted for a given settlement period.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketDocument', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Electronic document containing the information necessary to satisfy a given business process set of requirements.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketEvaluationPoint', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The identification of an entity where energy products are measured or computed.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketEventStatusKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MarketFactors', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Aggregation of market information relative for a specific time interval.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketInvoice', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'A roll up of invoice line items. The whole invoice has a due date and amount to be paid, with information such as customer, banks etc. being obtained through associations. The invoice roll up is based on individual line items that each contain amounts and descriptions for specific services or products.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketInvoiceLineItem', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'An individual line item on an invoice.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketLedger', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'In accounting transactions, a ledger is a book containing accounts to which debits and credits are posted from journals, where transactions are initially recorded. Journal entries are periodically posted to the ledger. Ledger Actual represents actual amounts by account within ledger within company or business area. Actual amounts may be generated in a source application and then loaded to a specific ledger within the enterprise general ledger or budget application.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketLedgerEntry', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Details of an individual entry in a ledger, which was posted from a journal on the posted date.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketObjectStatus', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'The condition or position of an object with regard to its standing.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketParticipant', 'Organisation', 'http://www.iec.ch/TC57/CIM#', false, 'An identification of a party acting in a electricity market business process. This class is used to identify organizations that can participate in market management and/or market operations.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketPerson', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'General purpose information for name and other information to contact people.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketPlan', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'This class identifies a set of planned markets. This class is a container of these planned markets', 'schema/cim/IEC_CIM.ttl'),
  ('MarketProduct', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A product traded by an RTO (e.g. energy, 10 minute spinning reserve).Ancillary service product examples include:Regulation UpRegulation DnSpinning ReserveNon-Spinning ReserveOperating Reserve', 'schema/cim/IEC_CIM.ttl'),
  ('MarketProductSelfSchedType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MarketProductType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MarketProductTypeAsReq', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MarketQualificationRequirement', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Certain skills are required and shall be certified in order for a person (typically a member of a crew) to be qualified to work on types of equipment.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketRegion', 'AggregateNode', 'http://www.iec.ch/TC57/CIM#', false, 'A specialized class of AggregatedNode type. Defines the MarketRegions. Regions could be system Market Regions, Energy Regions or Ancillary Service Regions.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketRegionResults', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Provides all Region Ancillary Service results for the DA and RT markets. The specific data is commodity type (Regulation Up, Regulation Down, Spinning Reserve, Non-spinning Reserve, or Total Up reserves) based for the cleared MW, cleared price, and total capacity required for the region.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketResults', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'This class holds elements that are single values for the entire market time horizon. That is, for the Day Ahead market, there is 1 value for each element, not hourly based. Is a summary of the market run', 'schema/cim/IEC_CIM.ttl'),
  ('MarketRole', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The external intended behaviour played by a party within the electricity market.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketRoleKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MarketRun', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'This class represent an actual instance of a planned market. For example, a Day Ahead market opens with the Bid Submission, ends with the closing of the Bid Submission. The market run represent the whole process. MarketRuns can be defined for markets such as Day Ahead Market, Real Time Market, Hour Ahead Market, Week Ahead Market,...', 'schema/cim/IEC_CIM.ttl'),
  ('MarketScheduleServices', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MarketScheduledEvent', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Signifies an event to trigger one or more activities, such as reading a meter, recalculating a bill, requesting work, when generating units shall be scheduled for maintenance, when a transformer is scheduled to be refurbished, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketSkill', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Proficiency level of a craft, which is required to operate or maintain a particular type of asset and/or perform certain types of work.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketStatement', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'A statement is a roll up of statement line items. Each statement along with its line items provide the details of specific charges at any given time. Used by Billing and Settlement', 'schema/cim/IEC_CIM.ttl'),
  ('MarketStatementDescription', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MarketStatementDocStatus', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MarketStatementDocType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MarketStatementLineItem', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'An individual line item on a statement.', 'schema/cim/IEC_CIM.ttl'),
  ('MarketStatementLineItemAliasName', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MarketType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Marketer', 'Organisation', 'http://www.iec.ch/TC57/CIM#', false, 'Matches buyers and sellers, and secures transmission (and other ancillary services) needed to complete the energy transaction.', 'schema/cim/IEC_CIM.ttl'),
  ('MaterialItem', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The physical consumable supply used for work and other purposes. It includes items such as nuts, bolts, brackets, glue, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('MaxStartUpCostCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'The maximum Startup costs and time as a function of down time. Relationship between unit startup cost (Y1-axis) vs. unit elapsed down time (X-axis). This is used to validate the information provided in the Bid.', 'schema/cim/IEC_CIM.ttl'),
  ('Measure', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A Measurement represents any measured, calculated or non-measured non-calculated quantity. Any piece of equipment may contain Measurements, e.g. a substation may have temperature measurements and door open indications, a transformer may have oil temperature and tank pressure measurements, a bay may contain a number of power flow measurements and a Breaker may contain a switch status measurement. The PSR - Measurement association is intended to capture this use of Measurement and is included in the naming hierarchy based on EquipmentContainer. The naming hierarchy typically has Measurements as leafs, e.g. Substation-VoltageLevel-Bay-Switch-Measurement. Some Measurements represent quantities related to a particular sensor location in the network, e.g. a voltage transformer (PT) at a busbar or a current transformer (CT) at the bar between a breaker and an isolator. The sensing position is not captured in the PSR - Measurement association. Instead it is captured by the Measurement - Terminal association that is used to define the sensing location in the network topology. The location is defined by the connection of the Terminal to ConductingEquipment. If both a Terminal and PSR are associated, and the PSR is of type ConductingEquipment, the associated Terminal should belong to that ConductingEquipment instance. When the sensor location is needed both Measurement-PSR and Measurement-Terminal are used. The Measurement-Terminal association is never used alone.', 'schema/cim/IEC_CIM.ttl'),
  ('MeasurementCalculator', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Result of a calculation of one or more measurement.', 'schema/cim/IEC_CIM.ttl'),
  ('MeasurementCalculatorInput', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Input to measurement calculation. Support Analog, Discrete and Accumulator.', 'schema/cim/IEC_CIM.ttl'),
  ('MeasurementKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MeasurementTypeEMS', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MeasurementValue', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The current state for a measurement. A state value is an instance of a measurement from a specific source. Measurements can be associated with many state values, each representing a different source for the measurement.', 'schema/cim/IEC_CIM.ttl'),
  ('MeasurementValueQuality', 'Quality61850', 'http://www.iec.ch/TC57/CIM#', false, 'Measurement quality flags. Bits 0-10 are defined for substation automation in draft IEC 61850 part 7-3. Bits 11-15 are reserved for future expansion by that document. Bits 16-31 are reserved for EMS applications.', 'schema/cim/IEC_CIM.ttl'),
  ('MeasurementValueSource', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'MeasurementValueSource describes the alternative sources updating a MeasurementValue. User conventions for how to use the MeasurementValueSource attributes are described in the introduction to IEC 61970-301.', 'schema/cim/IEC_CIM.ttl'),
  ('MeasuringPeriodKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MechLoad1', 'MechanicalLoadDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Mechanical load model type 1.', 'schema/cim/IEC_CIM.ttl'),
  ('MechanicalLoadDynamics', 'DynamicsFunctionBlock', 'http://www.iec.ch/TC57/CIM#', false, 'Mechanical load function block whose behavior is described by reference to a standard model <font color="#0f0f0f">or by definition of a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('MechanicalLoadUserDefined', 'MechanicalLoadDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Mechanical load function block whose dynamic behaviour is described by <font color="#0f0f0f">a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('Medium', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A substance that either (1) provides the means of transmission of a force or effect, such as hydraulic fluid, or (2) is used for a surrounding or enveloping substance, such as oil in a transformer or circuit breaker.', 'schema/cim/IEC_CIM.ttl'),
  ('MediumKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MerchantAccount', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'The operating account controlled by merchant agreement, against which the vendor may vend tokens or receipt payments. Transactions via vendor shift debit the account and bank deposits via bank statement credit the account.', 'schema/cim/IEC_CIM.ttl'),
  ('MerchantAgreement', 'Agreement', 'http://www.iec.ch/TC57/CIM#', false, 'A formal controlling contractual agreement between supplier and merchant, in terms of which the merchant is authorised to vend tokens and receipt payments on behalf of the supplier. The merchant is accountable to the supplier for revenue collected at point of sale.', 'schema/cim/IEC_CIM.ttl'),
  ('Meter', 'EndDevice', 'http://www.iec.ch/TC57/CIM#', false, 'Physical asset that performs the metering role of the usage point. Used for measuring consumption and detection of events.', 'schema/cim/IEC_CIM.ttl'),
  ('MeterMultiplier', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Multiplier applied at the meter.', 'schema/cim/IEC_CIM.ttl'),
  ('MeterMultiplierKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MeterReading', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Set of values obtained from the meter.', 'schema/cim/IEC_CIM.ttl'),
  ('MeterWorkTask', 'WorkTask', 'http://www.iec.ch/TC57/CIM#', false, 'Work task involving meters.', 'schema/cim/IEC_CIM.ttl'),
  ('MeteredSubSystem', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A metered subsystem', 'schema/cim/IEC_CIM.ttl'),
  ('MetrologyRequirement', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A specification of the metering requirements for a particular point within a network.', 'schema/cim/IEC_CIM.ttl'),
  ('Minutes', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Time in minutes.', 'schema/cim/IEC_CIM.ttl'),
  ('MiscCostItem', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Various cost items that are not associated with compatible units. Examples include rental equipment, labor, materials, contractor costs, permits - anything not covered in a CU.', 'schema/cim/IEC_CIM.ttl'),
  ('MitigatedBid', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Mitigated bid results posted for a given settlement period.', 'schema/cim/IEC_CIM.ttl'),
  ('MitigatedBidClearing', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Model of market power mitigation through reference or mitigated bids. Interval based.', 'schema/cim/IEC_CIM.ttl'),
  ('MitigatedBidSegment', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Model of mitigated bid. Indicates segment of piece-wise linear bid, that has been mitigated', 'schema/cim/IEC_CIM.ttl'),
  ('MktACLineSegment', 'ACLineSegment', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61970:Wires:ACLineSegment', 'schema/cim/IEC_CIM.ttl'),
  ('MktAccountKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MktActivityRecord', 'ActivityRecord', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61968: Common:ActivityRecord', 'schema/cim/IEC_CIM.ttl'),
  ('MktAnalogLimit', 'AnalogLimit', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61970:Meas:AnalogLimit', 'schema/cim/IEC_CIM.ttl'),
  ('MktAnalogLimitSet', 'AnalogLimitSet', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61970:Meas:AnalogLimitSet', 'schema/cim/IEC_CIM.ttl'),
  ('MktAnalogValue', 'AnalogValue', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61970:Meas:AnalogValue', 'schema/cim/IEC_CIM.ttl'),
  ('MktBillMediaKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MktCombinedCyclePlant', 'CombinedCyclePlant', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of Production: CombinedCyclePlant from IEC61970 package. A set of combustion turbines and steam turbines where the exhaust heat from the combustion turbines is recovered to make steam for the steam turbines, resulting in greater overall plant efficiency', 'schema/cim/IEC_CIM.ttl'),
  ('MktConductingEquipment', 'ConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61970:Core:ConductingEquipment', 'schema/cim/IEC_CIM.ttl'),
  ('MktConnectivityNode', 'ConnectivityNode', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61970:Topology:ConnectivityNode', 'schema/cim/IEC_CIM.ttl'),
  ('MktContingency', 'Contingency', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61970:Contingency', 'schema/cim/IEC_CIM.ttl'),
  ('MktControlArea', 'ControlArea', 'http://www.iec.ch/TC57/CIM#', false, 'Market subclass of IEC61970:ControlArea', 'schema/cim/IEC_CIM.ttl'),
  ('MktDiscreteValue', 'DiscreteValue', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61970:Meas:DiscreteValue', 'schema/cim/IEC_CIM.ttl'),
  ('MktEnergyConsumer', 'EnergyConsumer', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61970:Wires:EnergyConsumer', 'schema/cim/IEC_CIM.ttl'),
  ('MktGeneratingUnit', 'GeneratingUnit', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61970:Production:GeneratingUnit', 'schema/cim/IEC_CIM.ttl'),
  ('MktHeatRateCurve', 'HeatRateCurve', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61970: Generation: Production:HeatRateCurve', 'schema/cim/IEC_CIM.ttl'),
  ('MktInvoiceLineItemKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MktLine', 'Line', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass for IEC61970:Wires:Line', 'schema/cim/IEC_CIM.ttl'),
  ('MktLoadArea', 'LoadArea', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61970:LoadModel: LoadArea', 'schema/cim/IEC_CIM.ttl'),
  ('MktMeasurement', 'Measure', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61970:Meas:Measurement', 'schema/cim/IEC_CIM.ttl'),
  ('MktOrganisation', 'Organisation', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61968:Core2:TopLevel:Organisation', 'schema/cim/IEC_CIM.ttl'),
  ('MktPSRType', 'PSRType', 'http://www.iec.ch/TC57/CIM#', false, 'The type of a power system resource.', 'schema/cim/IEC_CIM.ttl'),
  ('MktPowerTransformer', 'PowerTransformer', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61970:Wires:PowerTransformer', 'schema/cim/IEC_CIM.ttl'),
  ('MktSeriesCompensator', 'SeriesCompensator', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61970:Wires:SeriesCompensator', 'schema/cim/IEC_CIM.ttl'),
  ('MktShuntCompensator', 'ShuntCompensator', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61970:Wires:ShuntCompensator', 'schema/cim/IEC_CIM.ttl'),
  ('MktSubClassType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('MktSwitch', 'Switch', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61970:Wires:Switch', 'schema/cim/IEC_CIM.ttl'),
  ('MktTapChanger', 'TapChanger', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61970:Wires:TapChanger', 'schema/cim/IEC_CIM.ttl'),
  ('MktTerminal', 'Terminal', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61970:Core:Terminal', 'schema/cim/IEC_CIM.ttl'),
  ('MktThermalGeneratingUnit', 'ThermalGeneratingUnit', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of ThermalGeneratingUnit from Production Package in IEC61970.', 'schema/cim/IEC_CIM.ttl'),
  ('MktUserAttribute', 'UserAttribute', 'http://www.iec.ch/TC57/CIM#', false, 'Subclass of IEC61968:Domain2:UserAttribute', 'schema/cim/IEC_CIM.ttl'),
  ('Model', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The part of a model that is versioned. There is a source, a specific kind of data included but it could be modified and versioned or have alternatives.', 'schema/cim/IEC_CIM.ttl'),
  ('ModelFrameType', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Examples would be "Boundary" or "Region" type of frame.', 'schema/cim/IEC_CIM.ttl'),
  ('ModelOperation', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'An operation performed on models.', 'schema/cim/IEC_CIM.ttl'),
  ('ModelOperationArg', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Describes the role a dataset plays in a model operation. The role is applicable only in the context of a single operation.', 'schema/cim/IEC_CIM.ttl'),
  ('ModelOperationArgDescription', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The type of custom operation dataset role for an operation description.', 'schema/cim/IEC_CIM.ttl'),
  ('ModelOperationDescription', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The type of model operation. This class is referenced by model operations and defines the kind of operation.', 'schema/cim/IEC_CIM.ttl'),
  ('ModelOperationSequence', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A concrete sequence of operations. For example, this may be used to describe a specific audit trail, a script or other specific set of actions on specific datasets.', 'schema/cim/IEC_CIM.ttl'),
  ('ModelPartVersion', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Versioned instance of a model part.', 'schema/cim/IEC_CIM.ttl'),
  ('ModelSpecification', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The type of model. For example, state estimator, planning, planning dynamics, short circuit, or real-time dynamics etc. The model must conform to a profile.', 'schema/cim/IEC_CIM.ttl'),
  ('Money', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Amount of money.', 'schema/cim/IEC_CIM.ttl'),
  ('MonthDay', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'MonthDay format as "--mm-dd", which conforms with XSD data type gMonthDay.', 'schema/cim/IEC_CIM.ttl'),
  ('MonthDayInterval', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Interval between two times specified as mont and date.', 'schema/cim/IEC_CIM.ttl'),
  ('MutualCoupling', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'This class represents the zero sequence line mutual coupling.', 'schema/cim/IEC_CIM.ttl'),
  ('Name', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'The Name class provides the means to define any number of human readable names for an object. A name is <b>not</b> to be used for defining inter-object relationships. For inter-object relationships instead use the object identification ''mRID''.', 'schema/cim/IEC_CIM.ttl'),
  ('NameType', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Type of name. Possible values for attribute ''name'' are implementation dependent but standard profiles may specify types. An enterprise may have multiple IT systems each having its own local name for the same object, e.g. a planning system may have different names from an EMS. An object may also have different names within the same IT system, e.g. localName as defined in CIM version 14. The definition from CIM14 is: The localName is a human readable name of the object. It is a free text name local to a node in a naming hierarchy similar to a file directory structure. A power system related naming hierarchy may be: Substation, VoltageLevel, Equipment etc. Children of the same parent in such a hierarchy have names that typically are unique among them.', 'schema/cim/IEC_CIM.ttl'),
  ('NameTypeAuthority', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Authority responsible for creation and management of names of a given type; typically an organization or an enterprise system.', 'schema/cim/IEC_CIM.ttl'),
  ('NoLoadTest', 'TransformerTest', 'http://www.iec.ch/TC57/CIM#', false, 'No-load test results determine core admittance parameters. They include exciting current and core loss measurements from applying voltage to one winding. The excitation may be positive sequence or zero sequence. The test may be repeated at different voltages to measure saturation.', 'schema/cim/IEC_CIM.ttl'),
  ('NodeConstraintTerm', 'ConstraintTerm', 'http://www.iec.ch/TC57/CIM#', false, 'To be used only to constrain a quantity that cannot be associated with a terminal. For example, a registered generating unit that is not electrically connected to the network.', 'schema/cim/IEC_CIM.ttl'),
  ('NonConformLoad', 'EnergyConsumer', 'http://www.iec.ch/TC57/CIM#', false, 'NonConformLoad represent loads that do not follow a daily load change pattern and changes are not correlated with the daily load change pattern.', 'schema/cim/IEC_CIM.ttl'),
  ('NonConformLoadGroup', 'LoadGroup', 'http://www.iec.ch/TC57/CIM#', false, 'Loads that do not follow a daily and seasonal load variation pattern.', 'schema/cim/IEC_CIM.ttl'),
  ('NonConformLoadSchedule', 'SeasonDayTypeSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'An active power (Y1-axis) and reactive power (Y2-axis) schedule (curves) versus time (X-axis) for non-conforming loads, e.g., large industrial load or power station service (where modeled).', 'schema/cim/IEC_CIM.ttl'),
  ('NonStandardItem', 'WorkDocument', 'http://www.iec.ch/TC57/CIM#', false, 'This document provides information for non-standard items like customer contributions (e.g., customer digs trench), vouchers (e.g., credit), and contractor bids.', 'schema/cim/IEC_CIM.ttl'),
  ('NonlinearShuntCompensator', 'ShuntCompensator', 'http://www.iec.ch/TC57/CIM#', false, 'A non linear shunt compensator has bank or section admittance values that differs.', 'schema/cim/IEC_CIM.ttl'),
  ('NonlinearShuntCompensatorPhase', 'ShuntCompensatorPhase', 'http://www.iec.ch/TC57/CIM#', false, 'A per phase non linear shunt compensator has bank or section admittance values that differs.', 'schema/cim/IEC_CIM.ttl'),
  ('NonlinearShuntCompensatorPhasePoint', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'A per phase non linear shunt compensator bank or section admittance value.', 'schema/cim/IEC_CIM.ttl'),
  ('NonlinearShuntCompensatorPoint', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'A non linear shunt compensator bank or section admittance value.', 'schema/cim/IEC_CIM.ttl'),
  ('NotificationTimeCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Notification time curve as a function of down time. Relationship between crew notification time (Y1-axis) and unit startup time (Y2-axis) vs. unit elapsed down time (X-axis).', 'schema/cim/IEC_CIM.ttl'),
  ('NotificationTriggerKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('NuclearGeneratingUnit', 'GeneratingUnit', 'http://www.iec.ch/TC57/CIM#', false, 'A nuclear generating unit.', 'schema/cim/IEC_CIM.ttl'),
  ('OASISBidReportType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('OASISDataItems', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('OASISErrCode', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('OASISErrDescription', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('OASISIntervalType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('OASISMarketType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('OASISMasterType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('OASISMeasType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('OASISReportType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('OASISStatusType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('OilPreservationKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('OilPrice', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Price of oil in monetary units', 'schema/cim/IEC_CIM.ttl'),
  ('OldCrew', 'Crew', 'http://www.iec.ch/TC57/CIM#', false, 'A crew is a group of people with specific skills, tools, and vehicles.', 'schema/cim/IEC_CIM.ttl'),
  ('OldPerson', 'Person', 'http://www.iec.ch/TC57/CIM#', false, 'General purpose information for name and other information to contact people.', 'schema/cim/IEC_CIM.ttl'),
  ('OldSwitchInfo', 'SwitchInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Properties of switch assets.', 'schema/cim/IEC_CIM.ttl'),
  ('OldTransformerEndInfo', 'TransformerEndInfo', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('OldTransformerTankInfo', 'TransformerTankInfo', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('OldWorkTask', 'WorkTask', 'http://www.iec.ch/TC57/CIM#', false, 'A set of tasks is required to implement a design.', 'schema/cim/IEC_CIM.ttl'),
  ('OnOff', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('OneCallRequest', 'WorkDocument', 'http://www.iec.ch/TC57/CIM#', false, 'A request for other utilities to mark their underground facilities prior to commencement of construction and/or maintenance.', 'schema/cim/IEC_CIM.ttl'),
  ('OpenAccessProduct', 'Agreement', 'http://www.iec.ch/TC57/CIM#', false, 'Contracts for services offered commercially.', 'schema/cim/IEC_CIM.ttl'),
  ('OpenCircuitTest', 'TransformerTest', 'http://www.iec.ch/TC57/CIM#', false, 'Open-circuit test results verify winding turn ratios and phase shifts. They include induced voltage and phase shift measurements on open-circuit windings, with voltage applied to the energised end. For three-phase windings, the excitation can be a positive sequence (the default) or a zero sequence.', 'schema/cim/IEC_CIM.ttl'),
  ('OpenTieSchedule', 'BidHourlySchedule', 'http://www.iec.ch/TC57/CIM#', false, 'Result of bid validation against conditions that may exist on an interchange that becomes disconnected or is heavily discounted with respect the MW flow. This schedule is assocated with the hourly parameters in a resource bid.', 'schema/cim/IEC_CIM.ttl'),
  ('OperatingParticipant', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'An operator of multiple power system resource objects. Note multple operating participants may operate the same power system resource object. This can be used for modeling jointly owned units where each owner operates as a contractual share.', 'schema/cim/IEC_CIM.ttl'),
  ('OperatingShare', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Specifies the operations contract relationship between a power system resource and a contract participant.', 'schema/cim/IEC_CIM.ttl'),
  ('OperationPersonRole', 'PersonRole', 'http://www.iec.ch/TC57/CIM#', false, 'Person role in the context of utility operations.', 'schema/cim/IEC_CIM.ttl'),
  ('OperationalLimit', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A value associated with a specific kind of limit. The sub class value attribute shall be positive. The sub class value attribute is inversely proportional to OperationalLimitType.acceptableDuration (acceptableDuration for short). A pair of value_x and acceptableDuration_x are related to each other as follows: if value_1 &gt; value_2 &gt; value_3 &gt;... then acceptableDuration_1 &lt; acceptableDuration_2 &lt; acceptableDuration_3 &lt; ... A value_x with direction="high" shall be greater than a value_y with direction="low".', 'schema/cim/IEC_CIM.ttl'),
  ('OperationalLimitDirectionKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('OperationalLimitSet', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A set of limits associated with equipment. Sets of limits might apply to a specific temperature, or season for example. A set of limits may contain different severities of limit levels that would apply to the same equipment. The set may contain limits of different types such as apparent power and current limits or high and low voltage limits that are logically applied together as a set.', 'schema/cim/IEC_CIM.ttl'),
  ('OperationalLimitType', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The operational meaning of a category of limits.', 'schema/cim/IEC_CIM.ttl'),
  ('OperationalRestriction', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'A document that can be associated with equipment to describe any sort of restrictions compared with the original manufacturer''s specification or with the usual operational practice e.g. temporary maximum loadings, maximum switching current, do not operate if bus couplers are open, etc. In the UK, for example, if a breaker or switch ever mal-operates, this is reported centrally and utilities use their asset systems to identify all the installed devices of the same manufacturer''s type. They then apply operational restrictions in the operational systems to warn operators of potential problems. After appropriate inspection and maintenance, the operational restrictions may be removed.', 'schema/cim/IEC_CIM.ttl'),
  ('OperationalTag', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Operational tag placed on a power system resource or asset in the context of switching plan execution or other work in the field.', 'schema/cim/IEC_CIM.ttl'),
  ('OperationalUpdatedRating', 'OperationalRestriction', 'http://www.iec.ch/TC57/CIM#', false, 'Lowered capability because of deterioration or inadequacy (sometimes referred to as derating or partial outage) or other kind of operational rating change.', 'schema/cim/IEC_CIM.ttl'),
  ('OperationsSafetySupervisor', 'Operator', 'http://www.iec.ch/TC57/CIM#', false, 'Operator with responsibility that the work in high voltage installation is executed in a safe manner and according to safety regulation.', 'schema/cim/IEC_CIM.ttl'),
  ('OperatonalLimitTypeScaling', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'One operational limit type scales values of another operational limit type when under the same operational limit set. This applies to any operational limit assigned to the target operational limit type and without other limit dependency models.', 'schema/cim/IEC_CIM.ttl'),
  ('Operator', 'OperationPersonRole', 'http://www.iec.ch/TC57/CIM#', false, 'Control room operator.', 'schema/cim/IEC_CIM.ttl'),
  ('OrgOrgRole', 'OrganisationRole', 'http://www.iec.ch/TC57/CIM#', false, 'Roles played between Organisations and other Organisations. This includes role ups for ogranisations, cost centers, profit centers, regulatory reporting, etc. Note that the parent and child relationship is indicated by the name on each end of the association.', 'schema/cim/IEC_CIM.ttl'),
  ('OrgPnodeAllocation', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'This class models the allocation between asset owners and pricing nodes', 'schema/cim/IEC_CIM.ttl'),
  ('OrgResOwnership', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'This class model the ownership percent and type of ownership between resource and organisation', 'schema/cim/IEC_CIM.ttl'),
  ('Organisation', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Organisation that might have roles as utility, contractor, supplier, manufacturer, customer, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('OrganisationCode', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('OrganisationRole', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Identifies a way in which an organisation may participate in the utility enterprise (e.g., customer, manufacturer, etc).', 'schema/cim/IEC_CIM.ttl'),
  ('OrganisationType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('OrientationKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Outage', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Document describing details of an active or planned outage in a part of the electrical network. A non-planned outage may be created upon: - a breaker trip, - a fault indicator status change, - a meter event indicating customer outage, - a reception of one or more customer trouble calls, or - an operator command, reflecting information obtained from the field crew. Outage restoration may be performed using a switching plan which complements the outage information with detailed switching activities, including the relationship to the crew and work. A planned outage may be created upon: - a request for service, maintenance or construction work in the field, or - an operator-defined outage for what-if/contingency network analysis.', 'schema/cim/IEC_CIM.ttl'),
  ('OutageSchedule', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Document containing the definition of planned outages of equipment and/or service (delivery) points (sometimes referred to as customers). It is used as specification for producing switching plans.', 'schema/cim/IEC_CIM.ttl'),
  ('OverexcLim2', 'OverexcitationLimiterDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Different from LimIEEEOEL, LimOEL2 has a fixed pickup threshold and reduces the excitation set-point by mean of non-windup integral regulator. Irated is the rated machine excitation current (calculated from nameplate conditions: V<sub>nom</sub>, P<sub>nom</sub>, CosPhi<sub>nom</sub>).', 'schema/cim/IEC_CIM.ttl'),
  ('OverexcLimIEEE', 'OverexcitationLimiterDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The over excitation limiter model is intended to represent the significant features of OELs necessary for some large-scale system studies. It is the result of a pragmatic approach to obtain a model that can be widely applied with attainable data from generator owners. An attempt to include all variations in the functionality of OELs and duplicate how they interact with the rest of the excitation systems would likely result in a level of application insufficient for the studies for which they are intended. Reference: IEEE OEL 421.5-2005 Section 9.', 'schema/cim/IEC_CIM.ttl'),
  ('OverexcLimX1', 'OverexcitationLimiterDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Field voltage over excitation limiter.', 'schema/cim/IEC_CIM.ttl'),
  ('OverexcLimX2', 'OverexcitationLimiterDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Field Voltage or Current overexcitation limiter designed to protect the generator field of an AC machine with automatic excitation control from overheating due to prolonged overexcitation.', 'schema/cim/IEC_CIM.ttl'),
  ('OverexcitationLimiterDynamics', 'DynamicsFunctionBlock', 'http://www.iec.ch/TC57/CIM#', false, '<font color="#0f0f0f">O</font>Overexcitation limiter function block whose behaviour is described by reference to a standard model <font color="#0f0f0f">or by definition of a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('OverexcitationLimiterUserDefined', 'OverexcitationLimiterDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Overexcitation limiter system function block whose dynamic behaviour is described by <font color="#0f0f0f">a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('OverheadCost', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Overhead cost applied to work order.', 'schema/cim/IEC_CIM.ttl'),
  ('OverheadWireInfo', 'WireInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Overhead wire data.', 'schema/cim/IEC_CIM.ttl'),
  ('Ownership', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Ownership of e.g. asset.', 'schema/cim/IEC_CIM.ttl'),
  ('PFVArControllerType1Dynamics', 'DynamicsFunctionBlock', 'http://www.iec.ch/TC57/CIM#', false, 'Power Factor or VAr controller Type I function block whose behaviour is described by reference to a standard model <font color="#0f0f0f">or by definition of a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('PFVArControllerType1UserDefined', 'PFVArControllerType1Dynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Power Factor or VAr controller Type I function block whose dynamic behaviour is described by <font color="#0f0f0f">a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('PFVArControllerType2Dynamics', 'DynamicsFunctionBlock', 'http://www.iec.ch/TC57/CIM#', false, 'Power Factor or VAr controller Type II function block whose behaviour is described by reference to a standard model <font color="#0f0f0f">or by definition of a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('PFVArControllerType2UserDefined', 'PFVArControllerType2Dynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Power Factor or VAr controller Type II function block whose dynamic behaviour is described by <font color="#0f0f0f">a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('PFVArType1IEEEPFController', 'PFVArControllerType1Dynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE PF Controller Type 1 which operates by moving the voltage reference directly. Reference: IEEE Standard 421.5-2005 Section 11.2.', 'schema/cim/IEC_CIM.ttl'),
  ('PFVArType1IEEEVArController', 'PFVArControllerType1Dynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE VAR Controller Type 1 which operates by moving the voltage reference directly. Reference: IEEE Standard 421.5-2005 Section 11.3.', 'schema/cim/IEC_CIM.ttl'),
  ('PFVArType2Common1', 'PFVArControllerType2Dynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Power factor / Reactive power regulator. This model represents the power factor or reactive power controller such as the Basler SCP-250. The controller measures power factor or reactive power (PU on generator rated power) and compares it with the operator''s set point.', 'schema/cim/IEC_CIM.ttl'),
  ('PFVArType2IEEEPFController', 'PFVArControllerType2Dynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE PF Controller Type 2 which is a summing point type controller and makes up the outside loop of a two-loop system. This controller is implemented as a slow PI type controller. The voltage regulator forms the inner loop and is implemented as a fast controller. Reference: IEEE Standard 421.5-2005 Section 11.4.', 'schema/cim/IEC_CIM.ttl'),
  ('PFVArType2IEEEVArController', 'PFVArControllerType2Dynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE VAR Controller Type 2 which is a summing point type controller. It makes up the outside loop of a two-loop system. This controller is implemented as a slow PI type controller, and the voltage regulator forms the inner loop and is implemented as a fast controller. Reference: IEEE Standard 421.5-2005 Section 11.5.', 'schema/cim/IEC_CIM.ttl'),
  ('PSREvent', 'ActivityRecord', 'http://www.iec.ch/TC57/CIM#', false, 'Event recording the change in operational status of a power system resource; may be for an event that has already occurred or for a planned activity.', 'schema/cim/IEC_CIM.ttl'),
  ('PSREventKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('PSRType', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Classifying instances of the same class, e.g. overhead and underground ACLineSegments. This classification mechanism is intended to provide flexibility outside the scope of this standard, i.e. provide customisation that is non standard.', 'schema/cim/IEC_CIM.ttl'),
  ('PU', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Per Unit - a positive or negative value referred to a defined base. Values typically range from -10 to +10.', 'schema/cim/IEC_CIM.ttl'),
  ('PWRSteamSupply', 'SteamSupply', 'http://www.iec.ch/TC57/CIM#', false, 'Pressurized water reactor used as a steam supply to a steam turbine.', 'schema/cim/IEC_CIM.ttl'),
  ('PackageDependenciesCIMVersion', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'The version of dependencies description among top level subpackages of the combined CIM model. This is not the same as the combined packages version.', 'schema/cim/IEC_CIM.ttl'),
  ('PanDemandResponse', 'EndDeviceAction', 'http://www.iec.ch/TC57/CIM#', false, 'PAN control used to issue action/command to PAN devices during a demand response/load control event.', 'schema/cim/IEC_CIM.ttl'),
  ('PanDisplay', 'EndDeviceAction', 'http://www.iec.ch/TC57/CIM#', false, 'PAN action/command used to issue the displaying of text messages on PAN devices.', 'schema/cim/IEC_CIM.ttl'),
  ('PanPricing', 'EndDeviceAction', 'http://www.iec.ch/TC57/CIM#', false, 'PAN action/command used to issue pricing information to a PAN device.', 'schema/cim/IEC_CIM.ttl'),
  ('PanPricingDetail', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Detail for a single price command/action.', 'schema/cim/IEC_CIM.ttl'),
  ('Participation', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Participation level of a given Pnode in a given AggregatePnode.', 'schema/cim/IEC_CIM.ttl'),
  ('ParticipationCategoryMPM', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('PassIndicatorType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('PassThroughBill', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Pass Through Bill is used for: 1)Two sided charge transactions with or without ISO involvement (hence the ?pass thru?) 2) Specific direct charges or payments that are calculated outside or provided directly to settlements 3) Specific charge bill determinants that are externally supplied and used in charge calculations', 'schema/cim/IEC_CIM.ttl'),
  ('PendingCalculation', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'When present, a scalar conversion that needs to be applied to every IntervalReading.value contained in IntervalBlock. This conversion results in a new associated ReadingType, reflecting the true dimensions of IntervalReading values after the conversion.', 'schema/cim/IEC_CIM.ttl'),
  ('PenstockLossCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Relationship between penstock head loss (in meters) and total discharge through the penstock (in cubic meters per second). One or more turbines may be connected to the same penstock.', 'schema/cim/IEC_CIM.ttl'),
  ('PerCent', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Percentage on a defined base. For example, specify as 100 to indicate at the defined base.', 'schema/cim/IEC_CIM.ttl'),
  ('PerLengthDCLineParameter', 'PerLengthLineParameter', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('PerLengthImpedance', 'PerLengthLineParameter', 'http://www.iec.ch/TC57/CIM#', false, 'Common type for per-length impedance electrical catalogues.', 'schema/cim/IEC_CIM.ttl'),
  ('PerLengthLineParameter', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Common type for per-length electrical catalogues describing line parameters.', 'schema/cim/IEC_CIM.ttl'),
  ('PerLengthPhaseImpedance', 'PerLengthImpedance', 'http://www.iec.ch/TC57/CIM#', false, 'Impedance and admittance parameters per unit length for n-wire unbalanced lines, in matrix form.', 'schema/cim/IEC_CIM.ttl'),
  ('PerLengthSequenceImpedance', 'PerLengthImpedance', 'http://www.iec.ch/TC57/CIM#', false, 'Sequence impedance and admittance parameters per unit length, for transposed lines of 1, 2, or 3 phases. For 1-phase lines, define x=x0=xself. For 2-phase lines, define x=xs-xm and x0=xs+xm.', 'schema/cim/IEC_CIM.ttl'),
  ('Period', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'An identification of a time interval that may have a given resolution.', 'schema/cim/IEC_CIM.ttl'),
  ('Person', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'General purpose information for name and other information to contact people.', 'schema/cim/IEC_CIM.ttl'),
  ('PersonOrganisationRole', 'OrganisationRole', 'http://www.iec.ch/TC57/CIM#', false, 'Role an organisation plays with respect to persons.', 'schema/cim/IEC_CIM.ttl'),
  ('PersonPropertyRole', 'Role', 'http://www.iec.ch/TC57/CIM#', false, 'The role of a person relative to a given piece of property. Examples of roles include: owner, renter, contractor, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('PersonRole', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('PetersenCoil', 'EarthFaultCompensator', 'http://www.iec.ch/TC57/CIM#', false, 'A tunable impedance device normally used to offset line charging during single line faults in an ungrounded section of network.', 'schema/cim/IEC_CIM.ttl'),
  ('PetersenCoilModeKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('PhaseCode', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('PhaseConnectedFaultKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('PhaseImpedanceData', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Triplet of resistance, reactance, and susceptance matrix element values.', 'schema/cim/IEC_CIM.ttl'),
  ('PhaseShuntConnectionKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('PhaseTapChanger', 'TapChanger', 'http://www.iec.ch/TC57/CIM#', false, 'A transformer phase shifting tap model that controls the phase angle difference across the power transformer and potentially the active power flow through the power transformer. This phase tap model may also impact the voltage magnitude.', 'schema/cim/IEC_CIM.ttl'),
  ('PhaseTapChangerAsymmetrical', 'PhaseTapChangerNonLinear', 'http://www.iec.ch/TC57/CIM#', false, 'Describes the tap model for an asymmetrical phase shifting transformer in which the difference voltage vector adds to the primary side voltage. The angle between the primary side voltage and the difference voltage is named the winding connection angle. The phase shift depends on both the difference voltage magnitude and the winding connection angle.', 'schema/cim/IEC_CIM.ttl'),
  ('PhaseTapChangerLinear', 'PhaseTapChanger', 'http://www.iec.ch/TC57/CIM#', false, 'Describes a tap changer with a linear relation between the tap step and the phase angle difference across the transformer. This is a mathematical model that is an approximation of a real phase tap changer. The phase angle is computed as stepPhaseShitfIncrement times the tap position. The secondary side voltage magnitude is the same as at the primary side.', 'schema/cim/IEC_CIM.ttl'),
  ('PhaseTapChangerNonLinear', 'PhaseTapChanger', 'http://www.iec.ch/TC57/CIM#', false, 'The non-linear phase tap changer describes the non-linear behavior of a phase tap changer. This is a base class for the symmetrical and asymmetrical phase tap changer models. The details of these models can be found in the IEC 61970-301 document.', 'schema/cim/IEC_CIM.ttl'),
  ('PhaseTapChangerSymmetrical', 'PhaseTapChangerNonLinear', 'http://www.iec.ch/TC57/CIM#', false, 'Describes a symmetrical phase shifting transformer tap model in which the secondary side voltage magnitude is the same as at the primary side. The difference voltage magnitude is the base in an equal-sided triangle where the sides corresponds to the primary and secondary voltages. The phase angle difference corresponds to the top angle and can be expressed as twice the arctangent of half the total difference voltage.', 'schema/cim/IEC_CIM.ttl'),
  ('PhaseTapChangerTable', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Describes a tabular curve for how the phase angle difference and impedance varies with the tap step.', 'schema/cim/IEC_CIM.ttl'),
  ('PhaseTapChangerTablePoint', 'TapChangerTablePoint', 'http://www.iec.ch/TC57/CIM#', false, 'Describes each tap step in the phase tap changer tabular curve.', 'schema/cim/IEC_CIM.ttl'),
  ('PhaseTapChangerTabular', 'PhaseTapChanger', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('PinBranchGroup', 'GateInputPin', 'http://www.iec.ch/TC57/CIM#', false, 'Value associated with branch group is used as compare.', 'schema/cim/IEC_CIM.ttl'),
  ('PinBranchGroupKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('PinEquipment', 'GateInputPin', 'http://www.iec.ch/TC57/CIM#', false, 'Value associated with Equipment is used as compare.', 'schema/cim/IEC_CIM.ttl'),
  ('PinEquipmentKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('PinGate', 'GateInputPin', 'http://www.iec.ch/TC57/CIM#', false, 'An output from one gate represent an input to another gate.', 'schema/cim/IEC_CIM.ttl'),
  ('PinMeasurement', 'GateInputPin', 'http://www.iec.ch/TC57/CIM#', false, 'Gate input pin that is associated with a Measurement or a calculation of Measurement.', 'schema/cim/IEC_CIM.ttl'),
  ('PinTerminal', 'GateInputPin', 'http://www.iec.ch/TC57/CIM#', false, 'Value associated with Terminal is used as compare.', 'schema/cim/IEC_CIM.ttl'),
  ('PinTerminalKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('PlannedMarket', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Represent a planned market. For example an planned DA/HA/RT market.', 'schema/cim/IEC_CIM.ttl'),
  ('PlannedMarketEvent', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'This class represents planned events. Used to model the various planned events in a market (closing time, clearing time, etc).', 'schema/cim/IEC_CIM.ttl'),
  ('Plant', 'EquipmentContainer', 'http://www.iec.ch/TC57/CIM#', false, 'A Plant is a collection of equipment for purposes of generation.', 'schema/cim/IEC_CIM.ttl'),
  ('Pnode', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A pricing node is directly associated with a connectivity node. It is a pricing location for which market participants submit their bids, offers, buy/sell CRRs, and settle.', 'schema/cim/IEC_CIM.ttl'),
  ('PnodeClearing', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Pricing node clearing results posted for a given settlement period.', 'schema/cim/IEC_CIM.ttl'),
  ('PnodeDistributionFactor', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'This class allows SC to input different distribution factors for pricing node', 'schema/cim/IEC_CIM.ttl'),
  ('PnodeResults', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Provides the total price, the cost component, the loss component, and the congestion component for Pnodes for the forward and real time markets. There are several prices produced based on the run type (MPM, RUC, Pricing, or Scheduling/Dispatch).', 'schema/cim/IEC_CIM.ttl'),
  ('Point', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'An identification of a set of values beeing adressed within a specific interval of time.', 'schema/cim/IEC_CIM.ttl'),
  ('PointOfSale', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Logical point where transactions take place with operational interaction between cashier and the payment system; in certain cases the point of sale interacts directly with the end customer, in which case the cashier might not be a real person: for example a self-service kiosk or over the internet.', 'schema/cim/IEC_CIM.ttl'),
  ('Pole', 'Structure', 'http://www.iec.ch/TC57/CIM#', false, 'Pole asset.', 'schema/cim/IEC_CIM.ttl'),
  ('PoleBaseKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('PolePreservativeKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('PoleTreatmentKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('PositionPoint', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Set of spatial coordinates that determine a point, defined in the coordinate system specified in ''Location.CoordinateSystem''. Use a single position point instance to desribe a point-oriented location. Use a sequence of position points to describe a line-oriented object (physical location of non-point oriented objects like cables or lines), or area of an object (like a substation or a geographical zone - in this case, have first and last position point with the same values).', 'schema/cim/IEC_CIM.ttl'),
  ('PostLineSensor', 'Sensor', 'http://www.iec.ch/TC57/CIM#', false, 'A sensor used mainly in overhead distribution networks as the source of both current and voltage measurements.', 'schema/cim/IEC_CIM.ttl'),
  ('PotentialTransformer', 'Sensor', 'http://www.iec.ch/TC57/CIM#', false, 'Instrument transformer (also known as Voltage Transformer) used to measure electrical qualities of the circuit that is being protected and/or monitored. Typically used as voltage transducer for the purpose of metering, protection, or sometimes auxiliary substation supply. A typical secondary voltage rating would be 120V.', 'schema/cim/IEC_CIM.ttl'),
  ('PotentialTransformerInfo', 'AssetInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Properties of potential transformer asset.', 'schema/cim/IEC_CIM.ttl'),
  ('PotentialTransformerKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('PowerCutZone', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'An area or zone of the power system which is used for load shedding purposes.', 'schema/cim/IEC_CIM.ttl'),
  ('PowerQualityPricing', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Pricing can be based on power quality.', 'schema/cim/IEC_CIM.ttl'),
  ('PowerSystemProject', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Meta-data for the change set that describe the status and the planned implementation of the changes into the as-build model. A Power System Project can consist of other Power System Projects', 'schema/cim/IEC_CIM.ttl'),
  ('PowerSystemProjectLifecycle', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Represent the base lifecycle of a functional model change that could be a construction of new elements.', 'schema/cim/IEC_CIM.ttl'),
  ('PowerSystemResource', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A power system resource can be an item of equipment such as a switch, an equipment container containing many individual items of equipment such as a substation, or an organisational entity such as sub-control area. Power system resources can have measurements associated.', 'schema/cim/IEC_CIM.ttl'),
  ('PowerSystemStabilizerDynamics', 'DynamicsFunctionBlock', 'http://www.iec.ch/TC57/CIM#', false, 'Power system stabilizer function block whose behaviour is described by reference to a standard model <font color="#0f0f0f">or by definition of a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('PowerSystemStabilizerUserDefined', 'PowerSystemStabilizerDynamics', 'http://www.iec.ch/TC57/CIM#', false, '<font color="#0f0f0f">Power system stabilizer</font> function block whose dynamic behaviour is described by <font color="#0f0f0f">a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('PowerTransformer', 'ConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'An electrical device consisting of two or more coupled windings, with or without a magnetic core, for introducing mutual coupling between electric circuits. Transformers can be used to control voltage and phase shift (active power flow). A power transformer may be composed of separate transformer tanks that need not be identical. A power transformer can be modeled with or without tanks and is intended for use in both balanced and unbalanced representations. A power transformer typically has two terminals, but may have one (grounding), three or more terminals. The inherited association ConductingEquipment.BaseVoltage should not be used. The association from TransformerEnd to BaseVoltage should be used instead.', 'schema/cim/IEC_CIM.ttl'),
  ('PowerTransformerEnd', 'TransformerEnd', 'http://www.iec.ch/TC57/CIM#', false, 'A PowerTransformerEnd is associated with each Terminal of a PowerTransformer. The impedance values r, r0, x, and x0 of a PowerTransformerEnd represents a star equivalent as follows 1) for a two Terminal PowerTransformer the high voltage PowerTransformerEnd has non zero values on r, r0, x, and x0 while the low voltage PowerTransformerEnd has zero values for r, r0, x, and x0. 2) for a three Terminal PowerTransformer the three PowerTransformerEnds represents a star equivalent with each leg in the star represented by r, r0, x, and x0 values. 3) for a PowerTransformer with more than three Terminals the PowerTransformerEnd impedance values cannot be used. Instead use the TransformerMeshImpedance or split the transformer into multiple PowerTransformers.', 'schema/cim/IEC_CIM.ttl'),
  ('PowerTransformerInfo', 'AssetInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Set of power transformer data, from an equipment library.', 'schema/cim/IEC_CIM.ttl'),
  ('PreconditionCIMDataObject', 'IncrementalCIMDataObject', 'http://www.iec.ch/TC57/CIM#', false, 'Used to specify precondition properties for a preconditioned update.', 'schema/cim/IEC_CIM.ttl'),
  ('Pressure', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Pressure in Pascal.', 'schema/cim/IEC_CIM.ttl'),
  ('Price', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'The cost corresponding to a specific measure and expressed in a currency.', 'schema/cim/IEC_CIM.ttl'),
  ('PriceSetFlag', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('PricingStructure', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Grouping of pricing components and prices used in the creation of customer charges and the eligibility criteria under which these terms may be offered to a customer. The reasons for grouping include state, customer classification, site characteristics, classification (i.e. fee price structure, deposit price structure, electric service price structure, etc.) and accounting requirements.', 'schema/cim/IEC_CIM.ttl'),
  ('PrimeMover', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'The machine used to develop mechanical energy used to drive a generator.', 'schema/cim/IEC_CIM.ttl'),
  ('Priority', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Priority definition.', 'schema/cim/IEC_CIM.ttl'),
  ('Procedure', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Documented procedure for various types of work or work tasks on assets.', 'schema/cim/IEC_CIM.ttl'),
  ('ProcedureDataSet', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'A data set recorded each time a procedure is executed. Observed results are captured in associated measurement values and/or values for properties relevant to the type of procedure performed.', 'schema/cim/IEC_CIM.ttl'),
  ('ProcedureKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Process', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The formal specification of a set of business transactions having the same business goal.', 'schema/cim/IEC_CIM.ttl'),
  ('ProductAssetModel', 'AssetModel', 'http://www.iec.ch/TC57/CIM#', false, 'Asset model by a specific manufacturer.', 'schema/cim/IEC_CIM.ttl'),
  ('ProductBid', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Component of a bid that pertains to one market product.', 'schema/cim/IEC_CIM.ttl'),
  ('Profile', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A profile is a simpler curve type.', 'schema/cim/IEC_CIM.ttl'),
  ('ProfileData', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Data for profile.', 'schema/cim/IEC_CIM.ttl'),
  ('Project', 'WorkDocument', 'http://www.iec.ch/TC57/CIM#', false, 'A collection of related work. For construction projects and maintenance projects, multiple phases may be performed.', 'schema/cim/IEC_CIM.ttl'),
  ('PropertyOrganisationRole', 'OrganisationRole', 'http://www.iec.ch/TC57/CIM#', false, 'Role an organisation plays with respect to property (for example, the organisation may be the owner, renter, occupier, taxiing authority, etc.).', 'schema/cim/IEC_CIM.ttl'),
  ('PropertyUnit', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Unit of property for reporting purposes.', 'schema/cim/IEC_CIM.ttl'),
  ('ProprietaryParameterDynamics', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Supports definition of one or more parameters of several different datatypes for use by proprietary user-defined models. NOTE: This class does not inherit from IdentifiedObject since it is not intended that a single instance of it be referenced by more than one proprietary user-defined model instance.', 'schema/cim/IEC_CIM.ttl'),
  ('ProtectedSwitch', 'Switch', 'http://www.iec.ch/TC57/CIM#', false, 'A ProtectedSwitch is a switching device that can be operated by ProtectionEquipment.', 'schema/cim/IEC_CIM.ttl'),
  ('ProtectionEquipment', 'Equipment', 'http://www.iec.ch/TC57/CIM#', false, 'An electrical device designed to respond to input conditions in a prescribed manner and after specified conditions are met to cause contact operation or similar abrupt change in associated electric control circuits, or simply to display the detected condition. Protection equipment are associated with conducting equipment and usually operate circuit breakers.', 'schema/cim/IEC_CIM.ttl'),
  ('ProtectionEquipmentInfo', 'AssetInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Properties of protection equipment asset.', 'schema/cim/IEC_CIM.ttl'),
  ('ProtectiveAction', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A protective action for supporting the integrity of the power system.', 'schema/cim/IEC_CIM.ttl'),
  ('ProtectiveActionAdjustment', 'ProtectiveAction', 'http://www.iec.ch/TC57/CIM#', false, 'Protective actions on non-switching equipment. The operating condition is adjusted.', 'schema/cim/IEC_CIM.ttl'),
  ('ProtectiveActionAdjustmentKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ProtectiveActionCollection', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A collection of protective actions to protect the integrity of the power system.', 'schema/cim/IEC_CIM.ttl'),
  ('ProtectiveActionEquipment', 'ProtectiveAction', 'http://www.iec.ch/TC57/CIM#', false, 'Protective action to put an Equipment in-service/out-of-service.', 'schema/cim/IEC_CIM.ttl'),
  ('ProtectiveActionRegulation', 'ProtectiveAction', 'http://www.iec.ch/TC57/CIM#', false, 'Protective action to change regulation to Equipment.', 'schema/cim/IEC_CIM.ttl'),
  ('Pss1', 'PowerSystemStabilizerDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Italian PSS - three input PSS (speed, frequency, power).', 'schema/cim/IEC_CIM.ttl'),
  ('Pss1A', 'PowerSystemStabilizerDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Single input power system stabilizer. It is a modified version in order to allow representation of various vendors'' implementations on PSS type 1A.', 'schema/cim/IEC_CIM.ttl'),
  ('Pss2B', 'PowerSystemStabilizerDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Modified IEEE PSS2B Model. Extra lead/lag (or rate) block added at end (up to 4 lead/lags total).', 'schema/cim/IEC_CIM.ttl'),
  ('Pss2ST', 'PowerSystemStabilizerDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'PTI Microprocessor-Based Stabilizer type 1.', 'schema/cim/IEC_CIM.ttl'),
  ('Pss5', 'PowerSystemStabilizerDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Italian PSS - Detailed PSS.', 'schema/cim/IEC_CIM.ttl'),
  ('PssELIN2', 'PowerSystemStabilizerDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Power system stabilizer typically associated with ExcELIN2 (though PssIEEE2B or Pss2B can also be used).', 'schema/cim/IEC_CIM.ttl'),
  ('PssIEEE1A', 'PowerSystemStabilizerDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type PSS1A power system stabilizer model. PSS1A is the generalized form of a PSS with a single input. Some common stabilizer input signals are speed, frequency, and power. Reference: IEEE 1A 421.5-2005 Section 8.1.', 'schema/cim/IEC_CIM.ttl'),
  ('PssIEEE2B', 'PowerSystemStabilizerDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type PSS2B power system stabilizer model. This stabilizer model is designed to represent a variety of dual-input stabilizers, which normally use combinations of power and speed or frequency to derive the stabilizing signal. Reference: IEEE 2B 421.5-2005 Section 8.2.', 'schema/cim/IEC_CIM.ttl'),
  ('PssIEEE3B', 'PowerSystemStabilizerDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type PSS3B power system stabilizer model. The PSS model PSS3B has dual inputs of electrical power and rotor angular frequency deviation. The signals are used to derive an equivalent mechanical power signal. Reference: IEEE 3B 421.5-2005 Section 8.3.', 'schema/cim/IEC_CIM.ttl'),
  ('PssIEEE4B', 'PowerSystemStabilizerDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Std 421.5-2005 type PSS2B power system stabilizer model. The PSS4B model represents a structure based on multiple working frequency bands. Three separate bands, respectively dedicated to the low-, intermediate- and high-frequency modes of oscillations, are used in this delta-omega (speed input) PSS. Reference: IEEE 4B 421.5-2005 Section 8.4.', 'schema/cim/IEC_CIM.ttl'),
  ('PssPTIST1', 'PowerSystemStabilizerDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'PTI Microprocessor-Based Stabilizer type 1.', 'schema/cim/IEC_CIM.ttl'),
  ('PssPTIST3', 'PowerSystemStabilizerDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'PTI Microprocessor-Based Stabilizer type 3.', 'schema/cim/IEC_CIM.ttl'),
  ('PssSB4', 'PowerSystemStabilizerDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Power sensitive stabilizer model.', 'schema/cim/IEC_CIM.ttl'),
  ('PssSH', 'PowerSystemStabilizerDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Model for Siemens H infinity power system stabilizer with generator electrical power input.', 'schema/cim/IEC_CIM.ttl'),
  ('PssSK', 'PowerSystemStabilizerDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'PSS Slovakian type  three inputs.', 'schema/cim/IEC_CIM.ttl'),
  ('PssWECC', 'PowerSystemStabilizerDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Dual input Power System Stabilizer, based on IEEE type 2, with modified output limiter defined by WECC (Western Electricity Coordinating Council, USA).', 'schema/cim/IEC_CIM.ttl'),
  ('PumpingCostSchedule', 'BidHourlyProductSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'The operating cost of a Pump Storage Hydro Unit operating as a hydro pump. This schedule is assocated with the hourly parameters in a resource bid associated with a specific product within the bid.', 'schema/cim/IEC_CIM.ttl'),
  ('PumpingLevelSchedule', 'BidHourlyProductSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'The fixed operating level of a Pump Storage Hydro Unit operating as a hydro pump. Associated with the energy market product type. This schedule is assocated with the hourly parameters in a resource bid associated with a specific product within the bid.', 'schema/cim/IEC_CIM.ttl'),
  ('PumpingShutDownCostSchedule', 'BidHourlyProductSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'The cost to shutdown a Pump Storage Hydro Unit (in pump mode) or a pump. This schedule is assocated with the hourly parameters in a resource bid associated with a specific product within the bid.', 'schema/cim/IEC_CIM.ttl'),
  ('PurposeFlagType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('QualificationRequirement', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Certain skills are required and must be certified in order for a person (typically a member of a crew) to be qualified to work on types of equipment.', 'schema/cim/IEC_CIM.ttl'),
  ('Quality61850', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Quality flags in this class are as defined in IEC 61850, except for estimatorReplaced, which has been included in this class for convenience.', 'schema/cim/IEC_CIM.ttl'),
  ('Quantity', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Description of quantities needed in the data exchange. The type of the quantity is described either by the role of the association or the type attribute. The quality attribute provides the information about the quality of the quantity (measured, estimated, etc.).', 'schema/cim/IEC_CIM.ttl'),
  ('RMRDetermination', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Indicates whether unit is a reliablity must run unit: required to be on to satisfy Grid Code Reliablitiy criteria, load demand, or voltage support.', 'schema/cim/IEC_CIM.ttl'),
  ('RMRHeatRateCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Model to support processing of reliability must run units.', 'schema/cim/IEC_CIM.ttl'),
  ('RMROperatorInput', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'RMR Operator''s entry of the RMR requirement per market interval.', 'schema/cim/IEC_CIM.ttl'),
  ('RMRStartUpCostCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Model to support processing of reliability must run units.', 'schema/cim/IEC_CIM.ttl'),
  ('RMRStartUpEnergyCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Model to support processing of reliability must run units.', 'schema/cim/IEC_CIM.ttl'),
  ('RMRStartUpFuelCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Model to support processing of reliability must run units.', 'schema/cim/IEC_CIM.ttl'),
  ('RMRStartUpTimeCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Model to support processing of reliability must run units.', 'schema/cim/IEC_CIM.ttl'),
  ('RTO', 'MktOrganisation', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('RUCAwardInstruction', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'This class models the information about the RUC awards', 'schema/cim/IEC_CIM.ttl'),
  ('RUCZone', 'AggregateNode', 'http://www.iec.ch/TC57/CIM#', false, 'A specialized class of type AggregatedNode type. Defines RUC Zones. A forecast region represents a collection of Nodes for which the Market operator has developed sufficient historical demand and relevant weather data to perform a demand forecast for such area. The Market Operator may further adjust this forecast to ensure that the Reliability Unit Commitment produces adequate local capacity procurement.', 'schema/cim/IEC_CIM.ttl'),
  ('RaiseLowerCommand', 'AnalogControl', 'http://www.iec.ch/TC57/CIM#', false, 'An analog control that increase or decrease a set point value with pulses.', 'schema/cim/IEC_CIM.ttl'),
  ('RampCurveType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('RampModeType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('RampRateCondition', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('RampRateCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Ramp rate as a function of resource MW output', 'schema/cim/IEC_CIM.ttl'),
  ('RampRateType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('RandomisationKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Ratio', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Fraction specified explicitly with a numerator and denominator, which can be used to calculate the quotient.', 'schema/cim/IEC_CIM.ttl'),
  ('RatioTapChanger', 'TapChanger', 'http://www.iec.ch/TC57/CIM#', false, 'A tap changer that changes the voltage ratio impacting the voltage magnitude but not the phase angle across the transformer.', 'schema/cim/IEC_CIM.ttl'),
  ('RatioTapChangerTable', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Describes a curve for how the voltage magnitude and impedance varies with the tap step.', 'schema/cim/IEC_CIM.ttl'),
  ('RatioTapChangerTablePoint', 'TapChangerTablePoint', 'http://www.iec.ch/TC57/CIM#', false, 'Describes each tap step in the ratio tap changer tabular curve.', 'schema/cim/IEC_CIM.ttl'),
  ('RationalNumber', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Rational number = ''numerator'' / ''denominator''.', 'schema/cim/IEC_CIM.ttl'),
  ('Reactance', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Reactance (imaginary part of impedance), at rated frequency.', 'schema/cim/IEC_CIM.ttl'),
  ('ReactancePerLength', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Reactance (imaginary part of impedance) per unit of length, at rated frequency.', 'schema/cim/IEC_CIM.ttl'),
  ('ReactiveCapabilityCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Reactive power rating envelope versus the synchronous machine''s active power, in both the generating and motoring modes. For each active power value there is a corresponding high and low reactive power limit value. Typically there will be a separate curve for each coolant condition, such as hydrogen pressure. The Y1 axis values represent reactive minimum and the Y2 axis values represent reactive maximum.', 'schema/cim/IEC_CIM.ttl'),
  ('ReactivePower', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Product of RMS value of the voltage and the RMS value of the quadrature component of the current.', 'schema/cim/IEC_CIM.ttl'),
  ('Reading', 'BaseReading', 'http://www.iec.ch/TC57/CIM#', false, 'Specific value measured by a meter or other asset, or calculated by a system. Each Reading is associated with a specific ReadingType.', 'schema/cim/IEC_CIM.ttl'),
  ('ReadingInterharmonic', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Interharmonics are represented as a rational number ''numerator'' / ''denominator'', and harmonics are represented using the same mechanism and identified by ''denominator''=1.', 'schema/cim/IEC_CIM.ttl'),
  ('ReadingQuality', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Quality of a specific reading value or interval reading value. Note that more than one quality may be applicable to a given reading. Typically not used unless problems or unusual conditions occur (i.e., quality for each reading is assumed to be good unless stated otherwise in associated reading quality type). It can also be used with the corresponding reading quality type to indicate that the validation has been performed and succeeded.', 'schema/cim/IEC_CIM.ttl'),
  ('ReadingQualityType', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Detailed description for a quality of a reading value, produced by an end device or a system. Values in attributes allow for creation of the recommended codes to be used for identifying reading value quality codes as follows: &lt;systemId&gt;.&lt;category&gt;.&lt;subCategory&gt;.', 'schema/cim/IEC_CIM.ttl'),
  ('ReadingReasonKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ReadingType', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Detailed description for a type of a reading value. Values in attributes allow for the creation of recommended codes to be used for identifying reading value types as follows: &lt;macroPeriod&gt;.&lt;aggregate&gt;.&lt;measuringPeriod&gt;.&lt;accumulation&gt;.&lt;flowDirection&gt;.&lt;commodity&gt;.&lt;measurementKind&gt;.&lt;interharmonic.numerator&gt;.&lt;interharmonic.denominator&gt;.&lt;argument.numerator&gt;.&lt;argument.denominator&gt;.&lt;tou&gt;.&lt;cpp&gt;.&lt;consumptionTier&gt;.&lt;phases&gt;.&lt;multiplier&gt;.&lt;unit&gt;.&lt;currency&gt;.', 'schema/cim/IEC_CIM.ttl'),
  ('RealEnergy', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Real electrical energy.', 'schema/cim/IEC_CIM.ttl'),
  ('Reason', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'The motivation of an act.', 'schema/cim/IEC_CIM.ttl'),
  ('Receipt', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Record of total receipted payment from customer.', 'schema/cim/IEC_CIM.ttl'),
  ('RecloseSequence', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A reclose sequence (open and close) is defined for each possible reclosure of a breaker.', 'schema/cim/IEC_CIM.ttl'),
  ('Recloser', 'ProtectedSwitch', 'http://www.iec.ch/TC57/CIM#', false, 'Pole-mounted fault interrupter with built-in phase and ground relays, current transformer (CT), and supplemental controls.', 'schema/cim/IEC_CIM.ttl'),
  ('RecloserInfo', 'OldSwitchInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Properties of recloser assets.', 'schema/cim/IEC_CIM.ttl'),
  ('Reconditioning', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Reconditioning information for an asset.', 'schema/cim/IEC_CIM.ttl'),
  ('RedLine', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'This class is used for handling the accompanying annotations, time stamp, author, etc. of designs, drawings and maps. A red line can be associated with any Location object.', 'schema/cim/IEC_CIM.ttl'),
  ('Register', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A device that indicates or records units of the commodity or other quantity measured.', 'schema/cim/IEC_CIM.ttl'),
  ('RegisteredGenerator', 'RegisteredResource', 'http://www.iec.ch/TC57/CIM#', false, 'Model of a generator that is registered to participate in the market', 'schema/cim/IEC_CIM.ttl'),
  ('RegisteredInterTie', 'RegisteredResource', 'http://www.iec.ch/TC57/CIM#', false, 'This class represents the inter tie resource.', 'schema/cim/IEC_CIM.ttl'),
  ('RegisteredLoad', 'RegisteredResource', 'http://www.iec.ch/TC57/CIM#', false, 'Model of a load that is registered to participate in the market (demand reduction)', 'schema/cim/IEC_CIM.ttl'),
  ('RegisteredResource', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'A resource that is registered through the market participant registration system. Examples include generating unit, load, and non-physical generator or load.', 'schema/cim/IEC_CIM.ttl'),
  ('RegularIntervalSchedule', 'BasicIntervalSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'The schedule has time points where the time between them is constant.', 'schema/cim/IEC_CIM.ttl'),
  ('RegularTimePoint', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Time point for a schedule where the time between the consecutive points is constant.', 'schema/cim/IEC_CIM.ttl'),
  ('RegulatingCondEq', 'ConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'A type of conducting equipment that can regulate a quantity (i.e. voltage or flow) at a specific point in the network.', 'schema/cim/IEC_CIM.ttl'),
  ('RegulatingControl', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'Specifies a set of equipment that works together to control a power system quantity such as voltage or flow. Remote bus voltage control is possible by specifying the controlled terminal located at some place remote from the controlling equipment. In case multiple equipment, possibly of different types, control same terminal there must be only one RegulatingControl at that terminal. The most specific subtype of RegulatingControl shall be used in case such equipment participate in the control, e.g. TapChangerControl for tap changers. For flow control load sign convention is used, i.e. positive sign means flow out from a TopologicalNode (bus) into the conducting equipment.', 'schema/cim/IEC_CIM.ttl'),
  ('RegulatingControlModeKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('RegulatingLimit', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'This class represents the physical characteristc of a generator regarding the regulating limit', 'schema/cim/IEC_CIM.ttl'),
  ('Regulation', 'WorkDocument', 'http://www.iec.ch/TC57/CIM#', false, 'Special requirements and/or regulations may pertain to certain types of assets or work. For example, fire protection and scaffolding.', 'schema/cim/IEC_CIM.ttl'),
  ('RegulationBranchKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('RegulationSchedule', 'SeasonDayTypeSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'A pre-established pattern over time for a controlled variable, e.g., busbar voltage.', 'schema/cim/IEC_CIM.ttl'),
  ('ReliabilityInfo', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Information regarding the experienced and expected reliability of a specific asset, type of asset, or asset model.', 'schema/cim/IEC_CIM.ttl'),
  ('RemedialActionScheme', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'Remedial Action Scheme (RAS), Special Protection Schemes (SPS), System Protection Schemes (SPS) or System Integrity Protection Schemes (SIPS).', 'schema/cim/IEC_CIM.ttl'),
  ('RemedialActionSchemeKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('RemoteConnectDisconnectInfo', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Details of remote connect and disconnect function.', 'schema/cim/IEC_CIM.ttl'),
  ('RemoteControl', 'RemotePoint', 'http://www.iec.ch/TC57/CIM#', false, 'Remote controls are ouputs that are sent by the remote unit to actuators in the process.', 'schema/cim/IEC_CIM.ttl'),
  ('RemoteInputSignal', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Supports connection to a terminal associated with a remote bus from which an input signal of a specific type is coming.', 'schema/cim/IEC_CIM.ttl'),
  ('RemotePoint', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'For a RTU remote points correspond to telemetered values or control outputs. Other units (e.g. control centers) usually also contain calculated values.', 'schema/cim/IEC_CIM.ttl'),
  ('RemoteSignalKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('RemoteSource', 'RemotePoint', 'http://www.iec.ch/TC57/CIM#', false, 'Remote sources are state variables that are telemetered or calculated within the remote unit.', 'schema/cim/IEC_CIM.ttl'),
  ('RemoteUnit', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'A remote unit can be a RTU, IED, substation control system, control center etc. The communication with the remote unit can be through various standard protocols (e.g. IEC 61870, IEC 61850) or non standard protocols (e.g. DNP, RP570 etc.). A remote unit contain remote data points that might be telemetered, collected or calculated. The RemoteUnit class inherit PowerSystemResource. The intention is to allow RemotUnits to have Measurements. These Measurements can be used to model unit status as operational, out of service, unit failure etc.', 'schema/cim/IEC_CIM.ttl'),
  ('RemoteUnitType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ReportingGroup', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A reporting group is used for various ad-hoc groupings used for reporting.', 'schema/cim/IEC_CIM.ttl'),
  ('ReportingSuperGroup', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A reporting super group, groups reporting groups for a higher level report.', 'schema/cim/IEC_CIM.ttl'),
  ('RequestorRmrTest', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ReserveDemandCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Reserve demand curve. Models maximum quantities of reserve required per Market Region and models a reserve demand curve for the minimum quantities of reserve. The ReserveDemandCurve is a relationship between unit operating reserve price in $/MWhr (Y-axis) and unit reserves in MW (X-axis).', 'schema/cim/IEC_CIM.ttl');
INSERT INTO metadata.cim_ref_classes (name, parent_name, namespace, is_abstract, description, source) VALUES
  ('ReserveReq', 'ResourceGroupReq', 'http://www.iec.ch/TC57/CIM#', false, 'Requirements for minimum amount of reserve and/or regulation to be supplied by a set of qualified resources.', 'schema/cim/IEC_CIM.ttl'),
  ('ReserveReqCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'A curve relating reserve requirement versus time, showing the values of a specific reserve requirement for each unit of the period covered. The curve can be based on "absolute" time or on "normalized'' time. X is time, typically expressed in absolute time Y1 is reserve requirement, typically expressed in MW', 'schema/cim/IEC_CIM.ttl'),
  ('ReserveRequirementType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Reservoir', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'A water storage facility within a hydro system, including: ponds, lakes, lagoons, and rivers. The storage is usually behind some type of dam.', 'schema/cim/IEC_CIM.ttl'),
  ('Resistance', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Resistance (real part of impedance).', 'schema/cim/IEC_CIM.ttl'),
  ('ResistancePerLength', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Resistance (real part of impedance) per unit of length.', 'schema/cim/IEC_CIM.ttl'),
  ('ResourceAncillaryServiceQualification', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Ancillary Services that a resource is qualified to provide.', 'schema/cim/IEC_CIM.ttl'),
  ('ResourceAncillaryServiceType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ResourceAssnType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ResourceAwardClearing', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Models details of bid and offer market clearing. Class indicates whether a contingency is active and whether the automatic dispatching system is active for this interval of the market solution', 'schema/cim/IEC_CIM.ttl'),
  ('ResourceAwardInstruction', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Model of market results, instruction for resource. Contains details of award as attributes', 'schema/cim/IEC_CIM.ttl'),
  ('ResourceBid', 'Bid', 'http://www.iec.ch/TC57/CIM#', false, 'Energy bid for generation, load, or virtual type for the whole of the market-trading period (i.e., one day in day ahead market or one hour in the real time market)', 'schema/cim/IEC_CIM.ttl'),
  ('ResourceCapacity', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'This class model the various capacities of a resource. A resource may have numbers of capacities related to operating, ancillary services, energy trade and so forth. The types are but not limited to: Ancillary Service Regulation Up Regulation Dn Spinning Reserve Non-Spinning Reserve Operating Reserve RUC Energy Trade', 'schema/cim/IEC_CIM.ttl'),
  ('ResourceCapacityType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ResourceCertification', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'This class represent the resource certification for a specific product type. For example, a resource is certified for Non-Spinning reserve for RTM.', 'schema/cim/IEC_CIM.ttl'),
  ('ResourceCertificationCategory', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ResourceCertificationType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ResourceClearing', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Model of market results, including cleaing result of resources. Associated with ResourceDispatchResults.', 'schema/cim/IEC_CIM.ttl'),
  ('ResourceDispatchResults', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'The ResourceDispatchResults class provides market results that can be provided to a SC. The specific data provided consists of several indicators such as contingency flags, blocked start up, and RMR dispatch. It also provides the projected overall and the regulating status of the resource.', 'schema/cim/IEC_CIM.ttl'),
  ('ResourceGroup', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A logical grouping of resources that are used to model location of types of requirements for ancillary services such as spinning reserve zones, regulation zones, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('ResourceGroupReq', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Ancillary service requirements for a market.', 'schema/cim/IEC_CIM.ttl'),
  ('ResourceLimitIndicator', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ResourceLoadFollowingInst', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Model of market clearing results for resources that bid to follow load', 'schema/cim/IEC_CIM.ttl'),
  ('ResourceOperationMaintenanceCost', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'To model the Operation and Maintenance (O and M) costs of a generation resource.', 'schema/cim/IEC_CIM.ttl'),
  ('ResourceRegistrationStatus', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ResourceStartupCost', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'To model the startup costs of a generation resource.', 'schema/cim/IEC_CIM.ttl'),
  ('ResourceVerifiableCosts', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'This class is defined to describe the verifiable costs associated with a generation resource.', 'schema/cim/IEC_CIM.ttl'),
  ('ResultsConstraintType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('RevenueKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('RightOfWay', 'Agreement', 'http://www.iec.ch/TC57/CIM#', false, 'A right-of-way (ROW) is for land where it is lawful to use for a public road, an electric power line, etc. Note that the association to Location, Asset, Organisation, etc. for the Grant is inherited from Agreement, a type of Document.', 'schema/cim/IEC_CIM.ttl'),
  ('Role', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Enumeration of potential roles that might be played by one object relative to another.', 'schema/cim/IEC_CIM.ttl'),
  ('RotatingMachine', 'RegulatingCondEq', 'http://www.iec.ch/TC57/CIM#', false, 'A rotating machine which may be used as a generator or motor.', 'schema/cim/IEC_CIM.ttl'),
  ('RotatingMachineDynamics', 'DynamicsFunctionBlock', 'http://www.iec.ch/TC57/CIM#', false, 'Abstract parent class for all synchronous and asynchronous machine standard models.', 'schema/cim/IEC_CIM.ttl'),
  ('RotationSpeed', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Number of revolutions per second.', 'schema/cim/IEC_CIM.ttl'),
  ('RotorKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Route', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Route that is followed, for example by service crews.', 'schema/cim/IEC_CIM.ttl'),
  ('SCADAInformation', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Contains information about the update from SCADA', 'schema/cim/IEC_CIM.ttl'),
  ('SVC', 'ShuntCompensator', 'http://www.iec.ch/TC57/CIM#', false, 'SVC asset allows the capacitive and inductive ratings for each phase to be specified individually if required.', 'schema/cim/IEC_CIM.ttl'),
  ('SVCControlMode', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SafetyDocument', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Document restricting or authorising works on electrical equipment (for example a permit to work, sanction for test, limitation of access, or certificate of isolation), defined based upon organisational practices.', 'schema/cim/IEC_CIM.ttl'),
  ('SchedClassType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ScheduledActivePowerLimitValue', 'ScheduledLimitValue', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ScheduledApparentPowerLimitValue', 'ScheduledLimitValue', 'http://www.iec.ch/TC57/CIM#', false, 'A time scheduled value for apparent power limit.', 'schema/cim/IEC_CIM.ttl'),
  ('ScheduledCurrentLimitValue', 'ScheduledLimitValue', 'http://www.iec.ch/TC57/CIM#', false, 'A current limit that is scheduled.', 'schema/cim/IEC_CIM.ttl'),
  ('ScheduledEvent', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'An event to trigger one or more activities, such as reading a meter, recalculating a bill, requesting work, when generating units must be scheduled for maintenance, when a transformer is scheduled to be refurbished, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('ScheduledEventData', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Schedule parameters for an activity that is to occur, is occurring, or has completed.', 'schema/cim/IEC_CIM.ttl'),
  ('ScheduledLimitDependency', 'LimitDependency', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ScheduledLimitValue', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A limit that is applicable during a scheduled time period.', 'schema/cim/IEC_CIM.ttl'),
  ('ScheduledVoltageLimitValue', 'ScheduledLimitValue', 'http://www.iec.ch/TC57/CIM#', false, 'A voltage limit value for a scheduled time.', 'schema/cim/IEC_CIM.ttl'),
  ('SchedulingCoordinator', 'MktOrganisation', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SchedulingCoordinatorUser', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Describing users of a Scheduling Coordinator', 'schema/cim/IEC_CIM.ttl'),
  ('SchedulingPoint', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Connection to other organizations at the boundary of the ISO/RTO.', 'schema/cim/IEC_CIM.ttl'),
  ('Seal', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Physically controls access to AssetContainers.', 'schema/cim/IEC_CIM.ttl'),
  ('SealConditionKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SealKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Season', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A specified time period of the year.', 'schema/cim/IEC_CIM.ttl'),
  ('SeasonDayTypeSchedule', 'RegularIntervalSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'A time schedule covering a 24 hour period, with curve data for a specific type of season and day.', 'schema/cim/IEC_CIM.ttl'),
  ('Seconds', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Time, in seconds.', 'schema/cim/IEC_CIM.ttl'),
  ('Sectionaliser', 'Switch', 'http://www.iec.ch/TC57/CIM#', false, 'Automatic switch that will lock open to isolate a faulted section. It may, or may not, have load breaking capability. Its primary purpose is to provide fault sectionalising at locations where the fault current is either too high, or too low, for proper coordination of fuses.', 'schema/cim/IEC_CIM.ttl'),
  ('SecurityConstraintSum', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Typically provided by RTO systems, constraints identified in both base case and critical contingency cases have to be transferred. A constraint has N (&gt;=1) constraint terms. A term is represented by an instance of TerminalConstraintTerm. The constraint expression is: minValue &lt;= c1*x1 + c2*x2 + .... cn*xn + k &lt;= maxValue where: - cn is ConstraintTerm.factor - xn is the flow at the terminal Flow into the associated equipment is positive for the purpose of ConnectivityNode NodeConstraintTerm k is SecurityConstraintsLinear.resourceMW The units of k are assumed to be same as the units of the flows, xn. The constants, cn, are dimensionless. With these conventions, cn and k are all positive for a typical constraint such as "weighted sum of generation shall be less than limit". Furthermore, cn are all 1.0 for a case such as "interface flow shall be less than limit", assuming the terminals are chosen on the importing side of the interface.', 'schema/cim/IEC_CIM.ttl'),
  ('SecurityConstraints', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Typical for regional transmission operators (RTOs), these constraints include transmission as well as generation group constraints identified in both base case and critical contingency cases.', 'schema/cim/IEC_CIM.ttl'),
  ('SecurityConstraintsClearing', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Binding security constrained clearing results posted for a given settlement period.', 'schema/cim/IEC_CIM.ttl'),
  ('SegmentCurveType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SelfSchedReferenceType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SelfSchedTypeCleanBid', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SelfSchedTypeRawBid', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SelfScheduleBreakdown', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Model of Self Schedules Results. Includes self schedule MW,and type of self schedule for each self schedule type included in total self schedule MW value found in ResourceAwardInstruction.', 'schema/cim/IEC_CIM.ttl'),
  ('SelfScheduleBreakdownType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SelfScheduleType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SelfScheduleTypeMB', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SensitivityPriceCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Optionally, this curve expresses elasticity of the associated requirement. For example, used to reduce requirements when clearing price exceeds reasonable values when the supply quantity becomes scarce. For example, a single point value of $1000/MW for a spinning reserve will cause a reduction in the required spinning reserve. X axis is constrained quantity (e.g., MW) Y1 axis is money per constrained quantity', 'schema/cim/IEC_CIM.ttl'),
  ('Sensor', 'AuxiliaryEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'This class describe devices that transform a measured quantity into signals that can be presented at displays, used in control or be recorded.', 'schema/cim/IEC_CIM.ttl'),
  ('SeriesCompensator', 'ConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'A Series Compensator is a series capacitor or reactor or an AC transmission line without charging susceptance. It is a two terminal device.', 'schema/cim/IEC_CIM.ttl'),
  ('SeriesEquipmentDependentLimit', 'LimitDependency', 'http://www.iec.ch/TC57/CIM#', false, 'Limit based on most restrictive series equipment limit. A specification of of equipment that determines the calculated operational limit values based upon other equipment and their ratings. The most restrictive limit connected in series within the group is used. The physical connection based on switch status for example may also impact which elements in the group are considered. Any equipment in the group that are presently connected in series with the equipment of the directly associated operational limit are used. This provides a means to indicate which potentially series equipment limits are considered for a computed operational limit. The operational limit of the same operational limit type is assumed to be used from the grouped equipment. It is also possible to make assumptions or calculations regarding how flow might split if the equipment is not simply in series.', 'schema/cim/IEC_CIM.ttl'),
  ('ServiceCategory', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Category of service provided to the customer.', 'schema/cim/IEC_CIM.ttl'),
  ('ServiceGuarantee', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'A service guarantee, often imposed by a regulator, defines conditions that, if not satisfied, will result in the utility making a monetary payment to the customer. Note that guarantee''s identifier is in the ''name'' attribute and the status of the guarantee is in the ''Status.status'' attribute. Example service requirements include: 1) If power is not restored within 24 hours, customers can claim $50 for residential customers or $100 for commercial and industrial customers. In addition for each extra period of 12 hours the customer''s supply has not been activated, the customer can claim $25. 2) If a customer has a question about their electricity bill, the utility will investigate and respond to the inquiry within 15 working days. If utility fails to meet its guarantee, utility will automatically pay the customer $50.', 'schema/cim/IEC_CIM.ttl'),
  ('ServiceKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ServiceLocation', 'WorkLocation', 'http://www.iec.ch/TC57/CIM#', false, 'A real estate location, commonly referred to as premises.', 'schema/cim/IEC_CIM.ttl'),
  ('ServiceMultiplier', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Multiplier applied at the usage point.', 'schema/cim/IEC_CIM.ttl'),
  ('ServiceMultiplierKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ServicePoint', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The defined termination points of a transmission path. Service points are defined from the viewpoint of the transmission service. Each service point is contained within (or on the boundary of) an interchange area. A service point is source or destination of a transaction.', 'schema/cim/IEC_CIM.ttl'),
  ('ServicePointOutageSummary', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Summary counts of service points affected by an outage. These counts are sometimes referred to as total and critical customer count.', 'schema/cim/IEC_CIM.ttl'),
  ('ServiceSupplier', 'OrganisationRole', 'http://www.iec.ch/TC57/CIM#', false, 'Organisation that provides services to customers.', 'schema/cim/IEC_CIM.ttl'),
  ('SetPoint', 'AnalogControl', 'http://www.iec.ch/TC57/CIM#', false, 'An analog control that issue a set point value.', 'schema/cim/IEC_CIM.ttl'),
  ('Settlement', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Specifies a settlement run.', 'schema/cim/IEC_CIM.ttl'),
  ('Shift', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Generally referring to a period of operation or work performed. Whether the shift is open/closed can be derived from attributes ''activityInterval.start'' and ''activityInterval.end''. The grand total for receipts (i.e., cumulative total of all actual receipted amounts during this shift; bankable + non-bankable; excludes rounding error totals) can be derived from receipt: =sum(''Receipt.receiptAmount''); includes bankable and non-bankable receipts. It also has to be reconciled against: =sum(''receiptsGrandTotalBankable'' + ''receiptsGrandTotalNonBankable'') and against receipt summary: =sum(''ReceiptSummary.receiptsTotal''). The attributes with "GrandTotal" defined in this class may need to be used when the source data is periodically flushed from the system and then these cannot be derived.', 'schema/cim/IEC_CIM.ttl'),
  ('ShiftPattern', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The patterns of shifts worked by people or crews.', 'schema/cim/IEC_CIM.ttl'),
  ('ShortCircuitRotorKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ShortCircuitTest', 'TransformerTest', 'http://www.iec.ch/TC57/CIM#', false, 'Short-circuit test results determine mesh impedance parameters. They include load losses and leakage impedances. For three-phase windings, the excitation can be a positive sequence (the default) or a zero sequence. There shall be at least one grounded winding.', 'schema/cim/IEC_CIM.ttl'),
  ('ShuntCompensator', 'RegulatingCondEq', 'http://www.iec.ch/TC57/CIM#', false, 'A shunt capacitor or reactor or switchable bank of shunt capacitors or reactors. A section of a shunt compensator is an individual capacitor or reactor. A negative value for reactivePerSection indicates that the compensator is a reactor. ShuntCompensator is a single terminal device. Ground is implied.', 'schema/cim/IEC_CIM.ttl'),
  ('ShuntCompensatorControl', 'RegulatingControl', 'http://www.iec.ch/TC57/CIM#', false, 'Distribution capacitor bank control settings.', 'schema/cim/IEC_CIM.ttl'),
  ('ShuntCompensatorDynamicData', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Optimal Power Flow or State Estimator Filter Bank Data for OTS. This is used for RealTime, Study and Maintenance Users', 'schema/cim/IEC_CIM.ttl'),
  ('ShuntCompensatorInfo', 'AssetInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Properties of shunt capacitor, shunt reactor or switchable bank of shunt capacitor or reactor assets.', 'schema/cim/IEC_CIM.ttl'),
  ('ShuntCompensatorPhase', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'Single phase of a multi-phase shunt compensator when its attributes might be different per phase.', 'schema/cim/IEC_CIM.ttl'),
  ('ShuntImpedanceControlKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ShuntImpedanceLocalControlKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ShutdownCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Relationship between the rate in gross active power/minute (Y-axis) at which a unit should be shutdown and its present gross MW output (X-axis).', 'schema/cim/IEC_CIM.ttl'),
  ('SimpleEndDeviceFunction', 'EndDeviceFunction', 'http://www.iec.ch/TC57/CIM#', false, 'Simple end device function distinguished by ''kind''. Use this class for instances that cannot be represented by another end device function specialisations.', 'schema/cim/IEC_CIM.ttl'),
  ('SinglePhaseKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Skill', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Proficiency level of a craft, which is required to operate or maintain a particular type of asset and/or perform certain types of work.', 'schema/cim/IEC_CIM.ttl'),
  ('SkillLevelKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SolarGeneratingUnit', 'GeneratingUnit', 'http://www.iec.ch/TC57/CIM#', false, 'A solar thermal generating unit.', 'schema/cim/IEC_CIM.ttl'),
  ('Source', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SourceSinkFlag', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SourceSinkType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Specification', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Specification can be used for various purposes relative to an asset, a logical device (PowerSystemResource), location, etc. Examples include documents supplied by manufacturers such as asset installation instructions, asset maintenance instructions, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('Specification_Layer', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Speed', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Distance per unit of time.', 'schema/cim/IEC_CIM.ttl'),
  ('SpinningEventNameType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SpinningEventType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Stage', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Stage of a remedial action scheme.', 'schema/cim/IEC_CIM.ttl'),
  ('StageTrigger', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Condition that is triggered either by TriggerCondition of by gate condition within a stage and has remedial action-s.', 'schema/cim/IEC_CIM.ttl'),
  ('StandardIndustryCode', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'The Standard Industrial Classification (SIC) are the codes that identify the type of products/service an industry is involved in, and used for statutory reporting purposes. For example, in the USA these codes are located by the federal government, and then published in a book entitled "The Standard Industrial Classification Manual". The codes are arranged in a hierarchical structure. Note that Residential Service Agreements are not classified according to the SIC codes.', 'schema/cim/IEC_CIM.ttl'),
  ('StartIgnFuelCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'The quantity of ignition fuel (Y-axis) used to restart and repay the auxiliary power consumed versus the number of hours (X-axis) the unit was off line.', 'schema/cim/IEC_CIM.ttl'),
  ('StartMainFuelCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'The quantity of main fuel (Y-axis) used to restart and repay the auxiliary power consumed versus the number of hours (X-axis) the unit was off line.', 'schema/cim/IEC_CIM.ttl'),
  ('StartRampCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Rate in gross active power/minute (Y-axis) at which a unit can be loaded versus the number of hours (X-axis) the unit was off line.', 'schema/cim/IEC_CIM.ttl'),
  ('StartUpCostCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Startup costs and time as a function of down time. Relationship between unit startup cost (Y1-axis) vs. unit elapsed down time (X-axis).', 'schema/cim/IEC_CIM.ttl'),
  ('StartUpEnergyCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'The energy consumption of a generating resource to complete a start-up from the StartUpEnergyCurve. Definition of the StartUpEnergyCurve includes, xvalue as the cooling time and y1value as the MW value.', 'schema/cim/IEC_CIM.ttl'),
  ('StartUpFuelCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'The fuel consumption of a Generating Resource to complete a Start-Up.(x=cooling time) Form Startup Fuel Curve. xAxisData -&gt; cooling time, y1AxisData -&gt; MBtu', 'schema/cim/IEC_CIM.ttl'),
  ('StartUpTimeCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Startup time curve as a function of down time, where time is specified in minutes. Relationship between unit startup time (Y1-axis) vs. unit elapsed down time (X-axis).', 'schema/cim/IEC_CIM.ttl'),
  ('StartupModel', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Unit start up characteristics depending on how long the unit has been off line.', 'schema/cim/IEC_CIM.ttl'),
  ('StateVariable', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'An abstract class for state variables.', 'schema/cim/IEC_CIM.ttl'),
  ('StaticLoadModelKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('StaticVarCompensator', 'RegulatingCondEq', 'http://www.iec.ch/TC57/CIM#', false, 'A facility for providing variable and controllable shunt reactive power. The SVC typically consists of a stepdown transformer, filter, thyristor-controlled reactor, and thyristor-switched capacitor arms. The SVC may operate in fixed MVar output mode or in voltage control mode. When in voltage control mode, the output of the SVC will be proportional to the deviation of voltage at the controlled bus from the voltage setpoint. The SVC characteristic slope defines the proportion. If the voltage at the controlled bus is equal to the voltage setpoint, the SVC MVar output is zero.', 'schema/cim/IEC_CIM.ttl'),
  ('StationSupply', 'EnergyConsumer', 'http://www.iec.ch/TC57/CIM#', false, 'Station supply with load derived from the station output.', 'schema/cim/IEC_CIM.ttl'),
  ('Status', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Current status information relevant to an entity.', 'schema/cim/IEC_CIM.ttl'),
  ('SteamSendoutSchedule', 'RegularIntervalSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'The cogeneration plant''s steam sendout schedule in volume per time unit.', 'schema/cim/IEC_CIM.ttl'),
  ('SteamSupply', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'Steam supply for steam turbine.', 'schema/cim/IEC_CIM.ttl'),
  ('SteamTurbine', 'PrimeMover', 'http://www.iec.ch/TC57/CIM#', false, 'Steam turbine.', 'schema/cim/IEC_CIM.ttl'),
  ('StreetAddress', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'General purpose street and postal address information.', 'schema/cim/IEC_CIM.ttl'),
  ('StreetDetail', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Street details, in the context of address.', 'schema/cim/IEC_CIM.ttl'),
  ('Streetlight', 'Asset', 'http://www.iec.ch/TC57/CIM#', false, 'Streetlight asset.', 'schema/cim/IEC_CIM.ttl'),
  ('StreetlightLampKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('StringMeasurement', 'Measure', 'http://www.iec.ch/TC57/CIM#', false, 'StringMeasurement represents a measurement with values of type string.', 'schema/cim/IEC_CIM.ttl'),
  ('StringMeasurementValue', 'MeasurementValue', 'http://www.iec.ch/TC57/CIM#', false, 'StringMeasurementValue represents a measurement value of type string.', 'schema/cim/IEC_CIM.ttl'),
  ('StringQuantity', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Quantity with string value (when it is not important whether it is an integral or a floating point number) and associated unit information.', 'schema/cim/IEC_CIM.ttl'),
  ('Structure', 'AssetContainer', 'http://www.iec.ch/TC57/CIM#', false, 'Construction holding assets such as conductors, transformers, switchgear, etc. Where applicable, number of conductors can be derived from the number of associated wire spacing instances.', 'schema/cim/IEC_CIM.ttl'),
  ('StructureMaterialKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('StructureSupport', 'Asset', 'http://www.iec.ch/TC57/CIM#', false, 'Support for structure assets.', 'schema/cim/IEC_CIM.ttl'),
  ('StructureSupportKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SubControlArea', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'An area defined for the purpose of tracking interchange with surrounding areas via tie points; may or may not serve as a control area.', 'schema/cim/IEC_CIM.ttl'),
  ('SubGeographicalRegion', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A subset of a geographical region of a power system network model.', 'schema/cim/IEC_CIM.ttl'),
  ('SubLoadArea', 'EnergyArea', 'http://www.iec.ch/TC57/CIM#', false, 'The class is the second level in a hierarchical structure for grouping of loads for the purpose of load flow load scaling.', 'schema/cim/IEC_CIM.ttl'),
  ('Subcritical', 'FossilSteamSupply', 'http://www.iec.ch/TC57/CIM#', false, 'Once-through subcritical boiler.', 'schema/cim/IEC_CIM.ttl'),
  ('SubscribePowerCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Price curve for specifying the cost of energy (X) at points in time (y1) according to a prcing structure, which is based on a tariff.', 'schema/cim/IEC_CIM.ttl'),
  ('Substation', 'EquipmentContainer', 'http://www.iec.ch/TC57/CIM#', false, 'A collection of equipment for purposes other than generation or utilization, through which electric energy in bulk is passed for the purposes of switching or modifying its characteristics.', 'schema/cim/IEC_CIM.ttl'),
  ('SubstitutionResourceList', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'List of resources that can be substituted for within the bounds of a Contract definition. This class has a precedence and a resource.', 'schema/cim/IEC_CIM.ttl'),
  ('Supercritical', 'FossilSteamSupply', 'http://www.iec.ch/TC57/CIM#', false, 'Once-through supercritical boiler.', 'schema/cim/IEC_CIM.ttl'),
  ('SupplierKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SurgeArrester', 'AuxiliaryEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'Shunt device, installed on the network, usually in the proximity of electrical equipment in order to protect the said equipment against transient voltage transients caused by lightning or switching activity.', 'schema/cim/IEC_CIM.ttl'),
  ('SurgeArresterInfo', 'AssetInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Properties of surge arrester.', 'schema/cim/IEC_CIM.ttl'),
  ('Susceptance', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Imaginary part of admittance.', 'schema/cim/IEC_CIM.ttl'),
  ('SusceptancePerLength', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Imaginary part of admittance per unit of length.', 'schema/cim/IEC_CIM.ttl'),
  ('SvInjection', 'StateVariable', 'http://www.iec.ch/TC57/CIM#', false, 'The SvInjection is reporting the calculated bus injection minus the sum of the terminal flows. The terminal flow is positive out from the bus (load sign convention) and bus injection has positive flow into the bus. SvInjection may have the remainder after state estimation or slack after power flow calculation.', 'schema/cim/IEC_CIM.ttl'),
  ('SvPowerFlow', 'StateVariable', 'http://www.iec.ch/TC57/CIM#', false, 'State variable for power flow. Load convention is used for flow direction. This means flow out from the TopologicalNode into the equipment is positive.', 'schema/cim/IEC_CIM.ttl'),
  ('SvShuntCompensatorSections', 'StateVariable', 'http://www.iec.ch/TC57/CIM#', false, 'State variable for the number of sections in service for a shunt compensator.', 'schema/cim/IEC_CIM.ttl'),
  ('SvStatus', 'StateVariable', 'http://www.iec.ch/TC57/CIM#', false, 'State variable for status.', 'schema/cim/IEC_CIM.ttl'),
  ('SvTapStep', 'StateVariable', 'http://www.iec.ch/TC57/CIM#', false, 'State variable for transformer tap step. This class is to be used for taps of LTC (load tap changing) transformers, not fixed tap transformers.', 'schema/cim/IEC_CIM.ttl'),
  ('SvVoltage', 'StateVariable', 'http://www.iec.ch/TC57/CIM#', false, 'State variable for voltage.', 'schema/cim/IEC_CIM.ttl'),
  ('Switch', 'ConductingEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'A generic device designed to close, or open, or both, one or more electric circuits. All switches are two terminal devices including grounding switches.', 'schema/cim/IEC_CIM.ttl'),
  ('SwitchAction', 'SwitchingStep', 'http://www.iec.ch/TC57/CIM#', false, 'Action on switch as a switching step.', 'schema/cim/IEC_CIM.ttl'),
  ('SwitchActionKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SwitchInfo', 'AssetInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Switch data.', 'schema/cim/IEC_CIM.ttl'),
  ('SwitchPhase', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'Single phase of a multi-phase switch when its attributes might be different per phase.', 'schema/cim/IEC_CIM.ttl'),
  ('SwitchSchedule', 'SeasonDayTypeSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'A schedule of switch positions. If RegularTimePoint.value1 is 0, the switch is open. If 1, the switch is closed.', 'schema/cim/IEC_CIM.ttl'),
  ('SwitchStatus', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Optimal Power Flow or State Estimator Circuit Breaker Status.', 'schema/cim/IEC_CIM.ttl'),
  ('SwitchStatusType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SwitchingPlan', 'SwitchingStepGroup', 'http://www.iec.ch/TC57/CIM#', false, 'A sequence of grouped or atomic steps intended to: - de-energise equipment or part of the network for safe work, and/or - bring back in service previously de-energised equipment or part of the network.', 'schema/cim/IEC_CIM.ttl'),
  ('SwitchingStep', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Atomic switching step; can be part of a switching step group, or part of a switching plan.', 'schema/cim/IEC_CIM.ttl'),
  ('SwitchingStepGroup', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'A logical step, grouping atomic switching steps that are important to distinguish when they may change topology (e.g. placing a jumper between two cuts).', 'schema/cim/IEC_CIM.ttl'),
  ('SynchrocheckRelay', 'ProtectionEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'A device that operates when two AC circuits are within the desired limits of frequency, phase angle, and voltage, to permit or to cause the paralleling of these two circuits. Used to prevent the paralleling of non-synchronous topological islands.', 'schema/cim/IEC_CIM.ttl'),
  ('SynchronousMachine', 'RotatingMachine', 'http://www.iec.ch/TC57/CIM#', false, 'An electromechanical device that operates with shaft rotating synchronously with the network. It is a single machine operating either as a generator or synchronous condenser or pump.', 'schema/cim/IEC_CIM.ttl'),
  ('SynchronousMachineDetailed', 'SynchronousMachineDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'All synchronous machine detailed types use a subset of the same data parameters and input/output variables. The several variations differ in the following ways: <ul> <li>The number of equivalent windings that are included</li> <li>The way in which saturation is incorporated into the model.</li> <li>Whether or not subtransient saliency (<b>X''''q</b> not = <b>X''''d</b>) is represented.</li> </ul> <b>Note:</b> It is not necessary for each simulation tool to have separate models for each of the model types. The same model can often be used for several types by alternative logic within the model. Also, differences in saturation representation may not result in significant model performance differences so model substitutions are often acceptable.', 'schema/cim/IEC_CIM.ttl'),
  ('SynchronousMachineDynamics', 'RotatingMachineDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Synchronous machine whose behaviour is described by reference to a standard model expressed in one of the following forms: <ul> <li>simplified (or classical), where a group of generators or motors is not modelled in detail</li> </ul> <ul> <li>detailed, in equivalent circuit form</li> <li>detailed, in time constant reactance form</li> </ul> <font color="#0f0f0f">or by definition of a user-defined model.</font> <font color="#0f0f0f"> </font><font color="#0f0f0f"><b>Note:</b> It is a common practice to represent small generators by a negative load rather than by a dynamic generator model when performing dynamics simulations. In this case a SynchronousMachine in the static model is not represented by anything in the dynamics model, instead it is treated as ordinary load.</font> <font color="#0f0f0f"> </font><font color="#0f0f0f"><b>Parameter Notes:</b></font> <ol> <li><font color="#0f0f0f">Synchronous machine parameters such as <b>Xl, Xd</b>,<b> Xp</b> etc. are actually used as inductances (L) in the models,</font> but are commonly referred to as reactances since, at nominal frequency, the per unit values are the same. However, some references use the symbol L instead of X. </li> </ol>', 'schema/cim/IEC_CIM.ttl'),
  ('SynchronousMachineEquivalentCircuit', 'SynchronousMachineDetailed', 'http://www.iec.ch/TC57/CIM#', false, 'The electrical equations for all variations of the synchronous models are based on the SynchronousEquivalentCircuit diagram for the direct and quadrature axes. <b>Equations for conversion between Equivalent Circuit and Time Constant Reactance forms:</b> <b>Xd</b> = <b>Xad</b> + <b>Xl</b> <b>Xd</b> = <b>Xl</b> + <b>Xad</b> * <b>Xfd</b> / (<b>Xad</b> + <b>Xfd</b>) <b>Xd</b> = <b>Xl</b> + <b>Xad</b> * <b>Xfd </b>* <b>X1d</b> / (<b>Xad</b> * <b>Xfd</b> + <b>Xad</b> * <b>X1d</b> + <b>Xfd</b> * <b>X1d</b>) <b>Xq</b> = <b>Xaq</b> + <b>Xl</b> <b>Xq</b> = <b>Xl</b> + <b>Xaq</b> * <b>X1q</b> / (<b>Xaq</b>+ <b>X1q</b>) <b>Xq</b> = <b>Xl</b> + <b>Xaq</b> *<b> X1q</b>* <b>X2q</b> / (<b>Xaq</b> * <b>X1q</b> + <b>Xaq</b> * <b>X2q</b> + <b>X1q</b> * <b>X2q</b>) <b>Tdo</b> = (<b>Xad</b> + <b>Xfd</b>) / (<b>omega</b><b><sub>0</sub></b> * <b>Rfd</b>) <b>Tdo</b> = (<b>Xad</b> * <b>Xfd</b> + <b>Xad</b> * <b>X1d</b> + <b>Xfd</b> * <b>X1d</b>) / (<b>omega</b><b><sub>0</sub></b> * <b>R1d</b> * (<b>Xad</b> + <b>Xfd</b>) <b>Tqo</b> = (<b>Xaq</b> + <b>X1q</b>) / (<b>omega</b><b><sub>0</sub></b> * <b>R1q</b>) <b>Tqo</b> = (<b>Xaq</b> * <b>X1q</b> + <b>Xaq</b> * <b>X2q</b> + <b>X1q</b> * <b>X2q</b>)/ (<b>omega</b><b><sub>0</sub></b> * <b>R2q</b> * (<b>Xaq</b> + <b>X1q</b>) <b> </b>Same equations using CIM attributes from SynchronousMachineTimeConstantReactance class on left of = sign and SynchronousMachineEquivalentCircuit class on right (except as noted): xDirectSync = xad + RotatingMachineDynamics.statorLeakageReactance xDirectTrans = RotatingMachineDynamics.statorLeakageReactance + xad * xfd / (xad + xfd) xDirectSubtrans = RotatingMachineDynamics.statorLeakageReactance + xad * xfd * x1d / (xad * xfd + xad * x1d + xfd * x1d) xQuadSync = xaq + RotatingMachineDynamics.statorLeakageReactance xQuadTrans = RotatingMachineDynamics.statorLeakageReactance + xaq * x1q / (xaq+ x1q) xQuadSubtrans = RotatingMachineDynamics.statorLeakageReactance + xaq * x1q* x2q / (xaq * x1q + xaq * x2q + x1q * x2q) tpdo = (xad + xfd) / (2*pi*nominal frequency * rfd) tppdo = (xad * xfd + xad * x1d + xfd * x1d) / (2*pi*nominal frequency * r1d * (xad + xfd) tpqo = (xaq + x1q) / (2*pi*nominal frequency * r1q) tppqo = (xaq * x1q + xaq * x2q + x1q * x2q)/ (2*pi*nominal frequency * r2q * (xaq + x1q). Are only valid for a simplified model where "Canay" reactance is zero.', 'schema/cim/IEC_CIM.ttl'),
  ('SynchronousMachineKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SynchronousMachineModelKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SynchronousMachineOperatingMode', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SynchronousMachineSimplified', 'SynchronousMachineDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The simplified model represents a synchronous generator as a constant internal voltage behind an impedance (<b>Rs</b> + <b>jXp</b>) as shown in the Simplified diagram. Since internal voltage is held constant, there is no <b>Efd</b> input and any excitation system model will be ignored. There is also no <b>Ifd</b> output. This model should not be used for representing a real generator except, perhaps, small generators whose response is insignificant. The parameters used for the Simplified model include: <ul> <li>RotatingMachineDynamics.damping (D)</li> <li>RotatingMachineDynamics.inertia (H)</li> <li>RotatingMachineDynamics.statorLeakageReactance (used to exchange jXp for SynchronousMachineSimplified)</li> <li>RotatingMachineDynamics.statorResistance (Rs).</li> </ul>', 'schema/cim/IEC_CIM.ttl'),
  ('SynchronousMachineTimeConstantReactance', 'SynchronousMachineDetailed', 'http://www.iec.ch/TC57/CIM#', false, 'Synchronous machine detailed modelling types are defined by the combination of the attributes SynchronousMachineTimeConstantReactance.modelType and SynchronousMachineTimeConstantReactance.rotorType. <b> </b><b>Parameter notes:</b> <ol> <li>The p in the time-related attribute names is a substitution for a prime in the usual parameter notation, e.g. tpdo refers to <b>T''do</b>.</li> </ol> <b> </b>The parameters used for models expressed in time constant reactance form include: <ul> <li>RotatingMachine.ratedS (MVAbase)</li> <li>RotatingMachineDynamics.damping (D)</li> <li>RotatingMachineDynamics.inertia (H)</li> <li>RotatingMachineDynamics.saturationFactor (S1)</li> <li>RotatingMachineDynamics.saturationFactor120 (S12)</li> <li>RotatingMachineDynamics.statorLeakageReactance (Xl)</li> <li>RotatingMachineDynamics.statorResistance (Rs)</li> <li>SynchronousMachineTimeConstantReactance.ks (Ks)</li> <li>SynchronousMachineDetailed.saturationFactorQAxis (S1q)</li> <li>SynchronousMachineDetailed.saturationFactor120QAxis (S12q)</li> <li>SynchronousMachineDetailed.efdBaseRatio</li> <li>SynchronousMachineDetailed.ifdBaseType</li> <li>SynchronousMachineDetailed.ifdBaseValue, if present</li> <li>.xDirectSync (Xd)</li> <li>.xDirectTrans (X''d)</li> <li>.xDirectSubtrans (X''''d)</li> <li>.xQuadSync (Xq)</li> <li>.xQuadTrans (X''q)</li> <li>.xQuadSubtrans (X''''q)</li> <li>.tpdo (T''do)</li> <li>.tppdo (T''''do)</li> <li>.tpqo (T''qo)</li> <li>.tppqo (T''''qo)</li> <li>.tc.</li> </ul>', 'schema/cim/IEC_CIM.ttl'),
  ('SynchronousMachineUserDefined', 'SynchronousMachineDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Synchronous machine whose dynamic behaviour is described by a user-defined model.', 'schema/cim/IEC_CIM.ttl'),
  ('Synchronous_Generator', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Synchronous_Machine', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('SysLoadDistributionFactor', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'This class models the system distribution factors. This class needs to be used along with the HostControlArea and the ConnectivityNode to show the distribution of each individual party.', 'schema/cim/IEC_CIM.ttl'),
  ('SystemType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TACArea', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Transmission Access Charge Area. Charges assessed, on behalf of the Participating Transmission Owner, to parties who require access to the controlled grid.', 'schema/cim/IEC_CIM.ttl'),
  ('TASE2BilateralTable', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'This class describe the sending (providing) side in a bilateral ICCP data exchange. Hence the ICCP bilateral (table) descriptions are created by exchanging ICCPProvider data between the parties.', 'schema/cim/IEC_CIM.ttl'),
  ('TCPAcessPoint', 'IPAccessPoint', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TREntitlement', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'A Transmission Right(TR) can be a chain of TR''s or on individual. When a transmission right is not a chain, this is formally the ETC/TOR Entitlement for each ETC/TOR contract with the inclusion of CVR(Converted Rights) as an ETC. This is the sum of all entitlements on all related transmission interfaces for the same TR. When TR is a chain, its entitlement is the minimum of all entitlements for the individual TRs in the chain.', 'schema/cim/IEC_CIM.ttl'),
  ('TRType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TagAction', 'SwitchingStep', 'http://www.iec.ch/TC57/CIM#', false, 'Action on operation tag as a switching step.', 'schema/cim/IEC_CIM.ttl'),
  ('TagActionKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TailbayLossCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Relationship between tailbay head loss hight (y-axis) and the total discharge into the power station''s tailbay volume per time unit (x-axis) . There could be more than one curve depending on the level of the tailbay reservoir or river level.', 'schema/cim/IEC_CIM.ttl'),
  ('TapChanger', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'Mechanism for changing transformer winding tap positions.', 'schema/cim/IEC_CIM.ttl'),
  ('TapChangerControl', 'RegulatingControl', 'http://www.iec.ch/TC57/CIM#', false, 'Describes behavior specific to tap changers, e.g. how the voltage at the end of a line varies with the load level and compensation of the voltage drop by tap adjustment.', 'schema/cim/IEC_CIM.ttl'),
  ('TapChangerDynamicData', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Optimal Power Flow or State Estimator Phase Shifter Data. This is used for RealTime, Study and Maintenance Users. SE Solution Phase Shifter Measurements from the last run of SE', 'schema/cim/IEC_CIM.ttl'),
  ('TapChangerInfo', 'AssetInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Tap changer data.', 'schema/cim/IEC_CIM.ttl'),
  ('TapChangerTablePoint', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TapSchedule', 'SeasonDayTypeSchedule', 'http://www.iec.ch/TC57/CIM#', false, 'A pre-established pattern over time for a tap step.', 'schema/cim/IEC_CIM.ttl'),
  ('TapeShieldCableInfo', 'CableInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Tape shield cable data.', 'schema/cim/IEC_CIM.ttl'),
  ('TargetLevelSchedule', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'Reservoir water level targets from advanced studies or "rule curves". Typically in one hour increments for up to 10 days.', 'schema/cim/IEC_CIM.ttl'),
  ('Tariff', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Document, approved by the responsible regulatory agency, listing the terms and conditions, including a schedule of prices, under which utility services will be provided. It has a unique number within the state or province. For rate schedules it is frequently allocated by the affiliated Public utilities commission (PUC).', 'schema/cim/IEC_CIM.ttl'),
  ('TariffProfile', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'A schedule of charges; structure associated with Tariff that allows the definition of complex tarif structures such as step and time of use when used in conjunction with TimeTariffInterval and Charge. Inherited ''status.value'' is defined in the context of the utility''s business rules, for example: active, inactive, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('TelephoneNumber', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Telephone number.', 'schema/cim/IEC_CIM.ttl'),
  ('TempEquipActionKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Temperature', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Value of temperature in degrees Celsius.', 'schema/cim/IEC_CIM.ttl'),
  ('TemperatureDependentLimitPoint', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'A point on a table of limit verses temperature.', 'schema/cim/IEC_CIM.ttl'),
  ('TemperatureDependentLimitTable', 'EnvironmentalDependentLimit', 'http://www.iec.ch/TC57/CIM#', false, 'This is a table lookup that provides limit values corresponding to a temperature input.', 'schema/cim/IEC_CIM.ttl'),
  ('TemperaturePolynomialLimit', 'EnvironmentalDependentLimit', 'http://www.iec.ch/TC57/CIM#', false, 'This describes the coefficients of a polynomial function that has temperature as input and calculates limit values as output.', 'schema/cim/IEC_CIM.ttl'),
  ('TenMinAuxiliaryData', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Models 10-Minutes Auxillary Data', 'schema/cim/IEC_CIM.ttl'),
  ('Tender', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Tender is what is "offered" by the customer towards making a payment and is often more than the required payment (hence the need for ''change''). The payment is thus that part of the Tender that goes towards settlement of a particular transaction. Tender is modelled as an aggregation of Cheque and Card. Both these tender types can exist in a single tender bid thus ''accountHolderName'' has to exist separately in each of Cheque and Card as each could have a different account holder name.', 'schema/cim/IEC_CIM.ttl'),
  ('TenderKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Terminal', 'ACDCTerminal', 'http://www.iec.ch/TC57/CIM#', false, 'An AC electrical connection point to a piece of conducting equipment. Terminals are connected at physical connection points called connectivity nodes.', 'schema/cim/IEC_CIM.ttl'),
  ('TerminalConstraintTerm', 'ConstraintTerm', 'http://www.iec.ch/TC57/CIM#', false, 'A constraint term associated with a specific terminal on a physical piece of equipment.', 'schema/cim/IEC_CIM.ttl'),
  ('TestDataSet', 'ProcedureDataSet', 'http://www.iec.ch/TC57/CIM#', false, 'Test results, usually obtained by a lab or other independent organisation.', 'schema/cim/IEC_CIM.ttl'),
  ('Text', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TextDiagramObject', 'DiagramObject', 'http://www.iec.ch/TC57/CIM#', false, 'A diagram object for placing free-text or text derived from an associated domain object.', 'schema/cim/IEC_CIM.ttl'),
  ('ThermalGeneratingUnit', 'GeneratingUnit', 'http://www.iec.ch/TC57/CIM#', false, 'A generating unit whose prime mover could be a steam turbine, combustion turbine, or diesel engine.', 'schema/cim/IEC_CIM.ttl'),
  ('TieFlow', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'A flow specification in terms of location and direction for a control area.', 'schema/cim/IEC_CIM.ttl'),
  ('TieLine', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TiePoint', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Site of an interface between interchange areas. The tie point can be a network branch (e.g., transmission line or transformer) or a switching device. For transmission lines, the interchange area boundary is usually at a designated point such as the middle of the line. Line end metering is then corrected for line losses.', 'schema/cim/IEC_CIM.ttl'),
  ('Time', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Time as "hh:mm:ss.sss", which conforms with ISO 8601. UTC time zone is specified as "hh:mm:ss.sssZ". A local timezone relative UTC is specified as "hh:mm:ss.sss±hh:mm". The second component (shown here as "ss.sss") could have any number of digits in its fractional part to allow any kind of precision beyond seconds.', 'schema/cim/IEC_CIM.ttl'),
  ('TimeInterval', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Interval between two times.', 'schema/cim/IEC_CIM.ttl'),
  ('TimeOfUse', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TimePoint', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A point in time within a sequence of points in time relative to a time schedule.', 'schema/cim/IEC_CIM.ttl'),
  ('TimeSchedule', 'Document', 'http://www.iec.ch/TC57/CIM#', false, 'Description of anything that changes through time. Time schedule is used to perform a single-valued function of time. Use inherited ''type'' attribute to give additional information on this schedule, such as: periodic (hourly, daily, weekly, monthly, etc.), day of the month, by date, calendar (specific times and dates).', 'schema/cim/IEC_CIM.ttl'),
  ('TimeSeries', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A set of regular time-ordered measurements or values of quantitative nature of an individual or collective phenomenon taken at successive, in most cases equidistant, periods / points of time.', 'schema/cim/IEC_CIM.ttl'),
  ('TimeTariffInterval', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'One of a sequence of time intervals defined in terms of real time. It is typically used in association with TariffProfile to define the intervals in a time of use tariff structure, where startDateTime simultaneously determines the starting point of this interval and the ending point of the previous interval.', 'schema/cim/IEC_CIM.ttl'),
  ('TimeZoneType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Tool', 'WorkAsset', 'http://www.iec.ch/TC57/CIM#', false, 'Tool asset.', 'schema/cim/IEC_CIM.ttl'),
  ('TopologicalIsland', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'An electrically connected subset of the network. Topological islands can change as the current network state changes: e.g. due to - disconnect switches or breakers change state in a SCADA/EMS - manual creation, change or deletion of topological nodes in a planning tool.', 'schema/cim/IEC_CIM.ttl'),
  ('TopologicalNode', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'For a detailed substation model a topological node is a set of connectivity nodes that, in the current network state, are connected together through any type of closed switches, including jumpers. Topological nodes change as the current network state changes (i.e., switches, breakers, etc. change state). For a planning model, switch statuses are not used to form topological nodes. Instead they are manually created or deleted in a model builder tool. Topological nodes maintained this way are also called "busses".', 'schema/cim/IEC_CIM.ttl'),
  ('Tower', 'Structure', 'http://www.iec.ch/TC57/CIM#', false, 'Tower asset. Dimensions of the Tower are specified in associated DimensionsInfo class. When used for planning purposes, a transmission tower carrying two 3-phase circuits will have 2 instances of Connection, each of which will have 3 MountingPoint instances, one for each phase all with coordinates relative to a common origin on the tower. (It may also have a 3rd Connection with a single MountingPoint for the Neutral line).', 'schema/cim/IEC_CIM.ttl'),
  ('TowerConstructionKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TownDetail', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Town details, in the context of address.', 'schema/cim/IEC_CIM.ttl'),
  ('Trade', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Inter Scheduling Coordinator Trades to model financial trades which may impact settlement', 'schema/cim/IEC_CIM.ttl'),
  ('TradeError', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Trade error and warning messages associated with the rule engine processing of the submitted trade.', 'schema/cim/IEC_CIM.ttl'),
  ('TradeProduct', NULL, 'http://www.iec.ch/TC57/CIM#', false, '<b>TradeType</b> <b>TradeProduct</b> IST (InterSC Trade) PHY (Physical Energy Trade) IST APN (Energy Trades at Aggregated Pricing Nodes) IST CPT (Converted Physical Energy Trade) AST (Ancilliary Services Trade) RUT (Regulation Up Trade) AST RDT (Regulation Down Trade) AST SRT (Spinning Reserve Trade) AST NRT (Non-Spinning Reserve Trade) UCT (Unit Commitment Trade) null', 'schema/cim/IEC_CIM.ttl'),
  ('TradeProductType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TradeStatusType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TradeType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TradingHubPrice', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Models prices at Trading Hubs, interval based', 'schema/cim/IEC_CIM.ttl'),
  ('TradingHubValues', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Models prices at Trading Hubs', 'schema/cim/IEC_CIM.ttl'),
  ('Transaction', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The record of details of payment for service or token sale.', 'schema/cim/IEC_CIM.ttl'),
  ('TransactionBid', 'Bid', 'http://www.iec.ch/TC57/CIM#', false, 'Bilateral or scheduled transactions for energy and ancillary services considered by market clearing process', 'schema/cim/IEC_CIM.ttl'),
  ('TransactionBidClearing', 'MarketFactors', 'http://www.iec.ch/TC57/CIM#', false, 'Contains the intervals relavent for the associated TransactionBidResults. For example, Day Ahead cleared results for the transaction bids for each interval of the market day.', 'schema/cim/IEC_CIM.ttl'),
  ('TransactionBidResults', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Contains the cleared results for each TransactionBid submitted to and accepted by the market.', 'schema/cim/IEC_CIM.ttl'),
  ('TransactionKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Transactor', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The entity that ultimately executes the transaction and which is in control of the process; typically this is embodied in secure software running on a server that may employ secure hardware encryption devices for secure transaction processing.', 'schema/cim/IEC_CIM.ttl'),
  ('TransferInterface', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A Transfer Interface is made up of branches such as transmission lines and transformers.', 'schema/cim/IEC_CIM.ttl'),
  ('TransferInterfaceSolution', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'TNA Interface Definitions from OPF for VSA', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerConstructionKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TransformerControlMode', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TransformerCoreAdmittance', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The transformer core admittance. Used to specify the core admittance of a transformer in a manner that can be shared among power transformers.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerCoreKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEnd', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A conducting connection point of a power transformer. It corresponds to a physical transformer winding terminal. In earlier CIM versions, the TransformerWinding class served a similar purpose, but this class is more flexible because it associates to terminal but is not a specialization of ConductingEquipment.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEndInfo', 'AssetInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Transformer end data.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerFunctionKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TransformerMeshImpedance', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Transformer mesh impedance (Delta-model) between transformer ends. The typical case is that this class describes the impedance between two transformer ends pair-wise, i.e. the cardinalities at both tranformer end associations are 1. But in cases where two or more transformer ends are modeled the cardinalities are larger than 1.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerObservation', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Common information captured during transformer inspections and/or diagnostics. Note that some properties may be measured through other means and therefore have measurement values in addition to the observed values recorded here.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerObservationsBushing', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TransformerStarImpedance', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Transformer star impedance (Pi-model) that accurately reflects impedance for transformers with 2 or 3 windings. For transformers with 4 or more windings, you must use TransformerMeshImpedance class. For transmission networks use PowerTransformerEnd impedances (r, r0, x, x0, b, b0, g and g0).', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerTank', 'Equipment', 'http://www.iec.ch/TC57/CIM#', false, 'An assembly of two or more coupled windings that transform electrical power between voltage levels. These windings are bound on a common core and place in the same tank. Transformer tank can be used to model both single-phase and 3-phase transformers.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerTankEnd', 'TransformerEnd', 'http://www.iec.ch/TC57/CIM#', false, 'Transformer tank end represents an individual winding for unbalanced models or for transformer tanks connected into a bank (and bank is modelled with the PowerTransformer).', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerTankInfo', 'AssetInfo', 'http://www.iec.ch/TC57/CIM#', false, 'Set of transformer tank data, from an equipment library.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerTest', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Test result for transformer ends, such as short-circuit, open-circuit (excitation) or no-load test.', 'schema/cim/IEC_CIM.ttl'),
  ('TransmissionCapacity', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'This class models the transmission (either a transmission interface or a POR/POD pair) capacity including Total Transfer Capacity (TTC), Operating Transfer Capacity (OTC), and Capacity Benefit Margin (CBM)', 'schema/cim/IEC_CIM.ttl'),
  ('TransmissionCorridor', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'A corridor containing one or more rights of way', 'schema/cim/IEC_CIM.ttl'),
  ('TransmissionInterfaceRightEntitlement', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'This is formally called the branch group ETC/TOR entitlement with the inclusion of CVR as ETC. Is used to represent the entitlements. This could be also used to represent the TR entitlement on a POR/POD.', 'schema/cim/IEC_CIM.ttl'),
  ('TransmissionModeKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TransmissionPath', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'An electrical connection, link, or line consisting of one or more parallel transmission elements between two areas of the interconnected electric systems, or portions thereof. TransmissionCorridor and TransmissionRightOfWay refer to legal aspects. The TransmissionPath refers to the segments between a TransmissionProvider''s ServicePoints.', 'schema/cim/IEC_CIM.ttl'),
  ('TransmissionProduct', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TransmissionProvider', 'Organisation', 'http://www.iec.ch/TC57/CIM#', false, 'Provider of the transmission capacity (interconnecting wires between Generation and Consumption) required to fulfill and Energy Transaction''s energy exchange. Posts information for transmission paths and AvailableTransmissionCapacities on a reservation node. Buys and sells its products and services on the same reservation node.', 'schema/cim/IEC_CIM.ttl'),
  ('TransmissionReservation', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'A transmission reservation is obtained from the OASIS system to reserve transmission for a specified time period, transmission path and transmission product.', 'schema/cim/IEC_CIM.ttl'),
  ('TransmissionRightChain', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Allows chaining of TransmissionContractRights. Many individual contract rights can be included in the definition of a TransmissionRightChain. A TransmissionRightChain is also defined as a TransmissionContractRight itself.', 'schema/cim/IEC_CIM.ttl'),
  ('TransmissionRightOfWay', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'A collection of transmission lines that are close proximity to each other.', 'schema/cim/IEC_CIM.ttl'),
  ('TriggerCondition', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'A conditions that can trigger remedial actions.', 'schema/cim/IEC_CIM.ttl'),
  ('TroubleReportingKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TroubleTicket', 'Document', 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TurbLCFB1', 'TurbineLoadControllerDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Turbine Load Controller model developed in the WECC. This model represents a supervisory turbine load controller that acts to maintain turbine power at a set value by continuous adjustment of the turbine governor speed-load reference. This model is intended to represent slow reset ''outer loop'' controllers managing the action of the turbine governor.', 'schema/cim/IEC_CIM.ttl'),
  ('TurbineGovernorDynamics', 'DynamicsFunctionBlock', 'http://www.iec.ch/TC57/CIM#', false, 'Turbine-governor function block whose behavior is described by reference to a standard model <font color="#0f0f0f">or by definition of a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('TurbineGovernorUserDefined', 'TurbineGovernorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Turbine-governor function block whose dynamic behaviour is described by <font color="#0f0f0f">a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('TurbineLoadControllerDynamics', 'DynamicsFunctionBlock', 'http://www.iec.ch/TC57/CIM#', false, 'Turbine load controller function block whose behavior is described by reference to a standard model <font color="#0f0f0f">or by definition of a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('TurbineLoadControllerUserDefined', 'TurbineLoadControllerDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Turbine load controller function block whose dynamic behaviour is described by <font color="#0f0f0f">a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('TurbineType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Turbine_Governor', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TypeAssetCatalogue', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Catalogue of generic types of assets (TypeAsset) that may be used for design purposes. It is not associated with a particular manufacturer.', 'schema/cim/IEC_CIM.ttl'),
  ('TypeMaterial', 'WorkDocument', 'http://www.iec.ch/TC57/CIM#', false, 'Documentation for a generic material item that may be used for design, work and other purposes. Any number of MaterialItems manufactured by various vendors may be used to perform this TypeMaterial. Note that class analagous to "AssetModel" is not used for material items. This is because in some cases, for example, a utility sets up a Master material record for a 3 inch long half inch diameter steel bolt and they do not necessarily care what specific supplier is providing the material item. As different vendors are used to supply the part, the Stock Code of the material item can stay the same. In other cases, each time the vendor changes, a new stock code is set up so they can track material used by vendor. Therefore a Material Item "Model" is not typically needed.', 'schema/cim/IEC_CIM.ttl'),
  ('UOMType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('UnderexcLim2Simplified', 'UnderexcitationLimiterDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'This model can be derived from UnderexcLimIEEE2. The limit characteristic (look up table) is a single straight-line, the same as UnderexcLimIEEE2 (see Figure 10.4 (p 32), IEEE 421.5-2005 Section 10.2).', 'schema/cim/IEC_CIM.ttl'),
  ('UnderexcLimIEEE1', 'UnderexcitationLimiterDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents the Type UEL1 model which has a circular limit boundary when plotted in terms of machine reactive power vs. real power output. Reference: IEEE UEL1 421.5-2005 Section 10.1.', 'schema/cim/IEC_CIM.ttl'),
  ('UnderexcLimIEEE2', 'UnderexcitationLimiterDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents the Type UEL2 which has either a straight-line or multi-segment characteristic when plotted in terms of machine reactive power output vs. real power output. Reference: IEEE UEL2 421.5-2005 Section 10.2. (Limit characteristic lookup table shown in Figure 10.4 (p 32) of the standard).', 'schema/cim/IEC_CIM.ttl'),
  ('UnderexcLimX1', 'UnderexcitationLimiterDynamics', 'http://www.iec.ch/TC57/CIM#', false, '<font color="#0f0f0f">Allis-Chalmers minimum excitation limiter.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('UnderexcLimX2', 'UnderexcitationLimiterDynamics', 'http://www.iec.ch/TC57/CIM#', false, '<font color="#0f0f0f">Westinghouse minimum excitation limiter.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('UnderexcitationLimiterDynamics', 'DynamicsFunctionBlock', 'http://www.iec.ch/TC57/CIM#', false, 'Underexcitation limiter function block whose behaviour is described by reference to a standard model <font color="#0f0f0f">or by definition of a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('UnderexcitationLimiterUserDefined', 'UnderexcitationLimiterDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Underexcitation limiter function block whose dynamic behaviour is described by <font color="#0f0f0f">a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('UndergroundStructure', 'Structure', 'http://www.iec.ch/TC57/CIM#', false, 'Underground structure.', 'schema/cim/IEC_CIM.ttl'),
  ('UndergroundStructureKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Unit', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'The identification of the unit name for the time series quantities.', 'schema/cim/IEC_CIM.ttl'),
  ('UnitInitialConditions', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Resource status at the end of a given clearing period.', 'schema/cim/IEC_CIM.ttl'),
  ('UnitMultiplier', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('UnitSymbol', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('UnitType', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('UnitTypeEMS', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('UpdateCIMDataObject', 'IncrementalCIMDataObject', 'http://www.iec.ch/TC57/CIM#', false, 'The object already exists and is to be modified.', 'schema/cim/IEC_CIM.ttl'),
  ('Usage', 'WorkIdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The way material and assets are used to perform a certain type of work task. The way is described in text in the inheritied description attribute.', 'schema/cim/IEC_CIM.ttl'),
  ('UsagePoint', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Logical or physical point in the network to which readings or events may be attributed. Used at the place where a physical or virtual meter may be located; however, it is not required that a meter be present.', 'schema/cim/IEC_CIM.ttl'),
  ('UsagePointConnectedKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('UsagePointGroup', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Abstraction for management of group communications within a two-way AMR system or the data for a group of related usage points. Commands can be issued to all of the usage points that belong to a usage point group using a defined group address and the underlying AMR communication infrastructure.', 'schema/cim/IEC_CIM.ttl'),
  ('UsagePointLocation', 'Location', 'http://www.iec.ch/TC57/CIM#', false, 'Location of an individual usage point.', 'schema/cim/IEC_CIM.ttl'),
  ('UserAttribute', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Generic name-value pair class, with optional sequence number and units for value; can be used to model parts of information exchange when concrete types are not known in advance.', 'schema/cim/IEC_CIM.ttl'),
  ('VAdjIEEE', 'VoltageAdjusterDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'The class represents IEEE Voltage Adjuster which is used to represent the voltage adjuster in either a power factor or var control system. Reference: IEEE Standard 421.5-2005 Section 11.1.', 'schema/cim/IEC_CIM.ttl'),
  ('VCompIEEEType1', 'VoltageCompensatorDynamics', 'http://www.iec.ch/TC57/CIM#', false, '<font color="#0f0f0f">The class represents the terminal voltage transducer and the load compensator as defined in the IEEE Std 421.5-2005, Section 4. This model is common to all excitation system models described in the IEEE Standard. </font> Reference: IEEE Standard 421.5-2005 Section 4.', 'schema/cim/IEC_CIM.ttl'),
  ('VCompIEEEType2', 'VoltageCompensatorDynamics', 'http://www.iec.ch/TC57/CIM#', false, '<font color="#0f0f0f">The class represents the terminal voltage transducer and the load compensator as defined in the IEEE Std 421.5-2005, Section 4. This model is designed to cover the following types of compensation: </font> <ul> <li><font color="#0f0f0f">reactive droop</font></li> <li><font color="#0f0f0f">transformer-drop or line-drop compensation</font></li> <li><font color="#0f0f0f">reactive differential compensation known also as cross-current compensation.</font></li> </ul> <font color="#0f0f0f"> </font><font color="#0f0f0f">Reference: IEEE Standard 421.5-2005, Section 4.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('Validity', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ValueAliasSet', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Describes the translation of a set of values into a name and is intendend to facilitate cusom translations. Each ValueAliasSet has a name, description etc. A specific Measurement may represent a discrete state like Open, Closed, Intermediate etc. This requires a translation from the MeasurementValue.value number to a string, e.g. 0-&gt;"Invalid", 1-&gt;"Open", 2-&gt;"Closed", 3-&gt;"Intermediate". Each ValueToAlias member in ValueAliasSet.Value describe a mapping for one particular value to a name.', 'schema/cim/IEC_CIM.ttl'),
  ('ValueToAlias', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Describes the translation of one particular value into a name, e.g. 1 as "Open".', 'schema/cim/IEC_CIM.ttl'),
  ('Vehicle', 'WorkAsset', 'http://www.iec.ch/TC57/CIM#', false, 'Vehicle asset.', 'schema/cim/IEC_CIM.ttl'),
  ('VehicleUsageKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Vendor', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The entity that owns the point of sale and contracts with the cashier to receipt payments and vend tokens using the payment system. The vendor has a private contract with and is managed by the merchant which is a type of organisation. The vendor is accountable to the merchant for revenue collected, and the merchant is in turn accountable to the supplier.', 'schema/cim/IEC_CIM.ttl'),
  ('VendorShift', 'Shift', 'http://www.iec.ch/TC57/CIM#', false, 'The operating shift for a vendor during which the vendor may transact against the merchant''s account. It aggregates transactions and receipts during the shift and periodically debits a merchant account. The totals in vendor shift should always be the sum of totals aggregated in all cashier shifts that were open under the particular vendor shift.', 'schema/cim/IEC_CIM.ttl'),
  ('ViolationLimit', 'Limit', 'http://www.iec.ch/TC57/CIM#', false, 'A type of limit that indicates if it is enforced and, through association, the organisation responsible for setting the limit.', 'schema/cim/IEC_CIM.ttl'),
  ('VisibilityLayer', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Layers are typically used for grouping diagram objects according to themes and scales. Themes are used to display or hide certain information (e.g., lakes, borders), while scales are used for hiding or displaying information depending on the current zoom level (hide text when it is too small to be read, or when it exceeds the screen size). This is also called de-cluttering. CIM based graphics exchange will support an m:n relationship between diagram objects and layers. It will be the task of the importing system to convert an m:n case into an appropriate 1:n representation if the importing system does not support m:n.', 'schema/cim/IEC_CIM.ttl'),
  ('Voltage', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Electrical voltage, can be both AC and DC.', 'schema/cim/IEC_CIM.ttl'),
  ('VoltageAdjusterDynamics', 'DynamicsFunctionBlock', 'http://www.iec.ch/TC57/CIM#', false, 'Voltage adjuster function block whose behaviour is described by reference to a standard model <font color="#0f0f0f">or by definition of a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('VoltageAdjusterUserDefined', 'VoltageAdjusterDynamics', 'http://www.iec.ch/TC57/CIM#', false, '<font color="#0f0f0f">Voltage adjuster</font> function block whose dynamic behaviour is described by <font color="#0f0f0f">a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('VoltageCompensatorDynamics', 'DynamicsFunctionBlock', 'http://www.iec.ch/TC57/CIM#', false, 'Voltage compensator function block whose behaviour is described by reference to a standard model <font color="#0f0f0f">or by definition of a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('VoltageCompensatorUserDefined', 'VoltageCompensatorDynamics', 'http://www.iec.ch/TC57/CIM#', false, 'Voltage compensator function block whose dynamic behaviour is described by <font color="#0f0f0f">a user-defined model.</font>', 'schema/cim/IEC_CIM.ttl'),
  ('VoltageControlZone', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'An area of the power system network which is defined for secondary voltage control purposes. A voltage control zone consists of a collection of substations with a designated bus bar section whose voltage will be controlled.', 'schema/cim/IEC_CIM.ttl'),
  ('VoltageLevel', 'EquipmentContainer', 'http://www.iec.ch/TC57/CIM#', false, 'A collection of equipment at one common system voltage forming a switchgear. The equipment typically consist of breakers, busbars, instrumentation, control, regulation and protection devices as well as assemblies of all these.', 'schema/cim/IEC_CIM.ttl'),
  ('VoltageLimit', 'OperationalLimit', 'http://www.iec.ch/TC57/CIM#', false, 'Operational limit applied to voltage.', 'schema/cim/IEC_CIM.ttl'),
  ('VoltagePerReactivePower', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Voltage variation with reactive power.', 'schema/cim/IEC_CIM.ttl'),
  ('Volume', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Volume.', 'schema/cim/IEC_CIM.ttl'),
  ('VolumeFlowRate', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Volume per time.', 'schema/cim/IEC_CIM.ttl'),
  ('VsCapabilityCurve', 'Curve', 'http://www.iec.ch/TC57/CIM#', false, 'The P-Q capability curve for a voltage source converter, with P on x-axis and Qmin and Qmax on y1-axis and y2-axis.', 'schema/cim/IEC_CIM.ttl'),
  ('VsConverter', 'ACDCConverter', 'http://www.iec.ch/TC57/CIM#', false, 'DC side of the voltage source converter (VSC).', 'schema/cim/IEC_CIM.ttl'),
  ('VsPpccControlKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('VsQpccControlKind', NULL, 'http://www.iec.ch/TC57/CIM#', false, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('WaterLevel', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'Reservoir water level referred to a given datum such as mean sea level.', 'schema/cim/IEC_CIM.ttl'),
  ('WaveTrap', 'AuxiliaryEquipment', 'http://www.iec.ch/TC57/CIM#', false, 'Line traps are devices that impede high frequency power line carrier signals yet present a negligible impedance at the main power frequency.', 'schema/cim/IEC_CIM.ttl'),
  ('WeatherStation', 'PowerSystemResource', 'http://www.iec.ch/TC57/CIM#', false, 'This represents a source of ambient temperature.', 'schema/cim/IEC_CIM.ttl'),
  ('Weight', NULL, 'http://www.iec.ch/TC57/CIM#', false, 'The weight of an object.', 'schema/cim/IEC_CIM.ttl'),
  ('WheelingCounterParty', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Counter party in a wheeling transaction.', 'schema/cim/IEC_CIM.ttl'),
  ('WheelingReferenceSchedule', 'BidHourlySchedule', 'http://www.iec.ch/TC57/CIM#', false, 'A unique identifier of a wheeling transaction. A wheeling transaction is a balanced Energy exchange among Supply and Demand Resources. This schedule is assocated with the hourly parameters in a resource bid.', 'schema/cim/IEC_CIM.ttl'),
  ('WindAeroConstIEC', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The constant aerodynamic torque model assumes that the aerodynamic torque is constant. Reference: IEC Standard 61400-27-1 Section 6.6.1.1.', 'schema/cim/IEC_CIM.ttl'),
  ('WindAeroLinearIEC', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The linearised aerodynamic model. Reference: IEC Standard 614000-27-1 Section 6.6.1.2.', 'schema/cim/IEC_CIM.ttl'),
  ('WindContCurrLimIEC', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Current limitation model. The current limitation model combines the physical limits. Reference: IEC Standard 61400-27-1 Section 6.6.5.7.', 'schema/cim/IEC_CIM.ttl'),
  ('WindContPType3IEC', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'P control model Type 3. Reference: IEC Standard 61400-27-1 Section 6.6.5.3.', 'schema/cim/IEC_CIM.ttl'),
  ('WindContPType4aIEC', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'P control model Type 4A. Reference: IEC Standard 61400-27-1 Section 6.6.5.4.', 'schema/cim/IEC_CIM.ttl'),
  ('WindContPType4bIEC', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'P control model Type 4B. Reference: IEC Standard 61400-27-1 Section 6.6.5.5.', 'schema/cim/IEC_CIM.ttl'),
  ('WindContPitchAngleIEC', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Pitch angle control model. Reference: IEC Standard 61400-27-1 Section 6.6.5.8.', 'schema/cim/IEC_CIM.ttl'),
  ('WindContQIEC', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Q control model. Reference: IEC Standard 61400-27-1 Section 6.6.5.6.', 'schema/cim/IEC_CIM.ttl'),
  ('WindContRotorRIEC', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'Rotor resistance control model. Reference: IEC Standard 61400-27-1 Section 6.6.5.2.', 'schema/cim/IEC_CIM.ttl'),
  ('WindDynamicsLookupTable', 'IdentifiedObject', 'http://www.iec.ch/TC57/CIM#', false, 'The class models a look up table for the purpose of wind standard models.', 'schema/cim/IEC_CIM.ttl'),
  ('WindGenTurbineType1IEC', 'WindTurbineType1or2IEC', 'http://www.iec.ch/TC57/CIM#', false, 'Wind turbine IEC Type 1. Reference: IEC Standard 61400-27-1, section 6.5.2.', 'schema/cim/IEC_CIM.ttl'),
